            <p className="text-sm text-gray-400 max-w-xs mx-auto leading-relaxed">{t.login.subtitle}</p>
          </div>
        </div>

        <div className="bg-gray-900/40 backdrop-blur-xl border border-gray-800 rounded-[32px] p-8 shadow-2xl">
          {!connecting && !signing ? (
            <div className="space-y-6">
              <p className="text-xs font-bold text-gray-500 uppercase tracking-widest text-center">{t.login.selectWallet}</p>
              <div className="grid grid-cols-2 gap-4">
                {wallets.map((wallet) => (
                  <button
