import { Language } from '../translations';

interface HeaderProps {
  address: string;
  onDisconnect: () => void;
}

const Header: React.FC<HeaderProps> = ({ address, onDisconnect }) => {
  const { language, setLanguage, t } = useLanguage();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const languages: { code: Language; label: string }[] = [
    { code: 'en', label: 'EN' },
    { code: 'zhCN', label: '简' },
    { code: 'zhTW', label: '繁' },
  ];

  const shortenedAddress = `${address.slice(0, 6)}...${address.slice(-4)}`;

  const handleCopy = () => {
    navigator.clipboard.writeText(address);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="h-16 bg-[#0a0a0b]/80 backdrop-blur-md border-b border-gray-800 flex items-center justify-between px-8 sticky top-0 z-50 transition-colors duration-300">
      <div className="flex items-center flex-1 max-w-xl">
        <div className="relative w-full">
          <span className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-4 w-4 text-gray-500" />
          </span>
          <input
            className="block w-full bg-gray-900/50 border border-gray-800 rounded-lg py-2 pl-10 pr-3 text-sm placeholder-gray-500 focus:outline-none focus:ring-1 focus:ring-amber-500 focus:border-amber-500 transition-all"
            placeholder={t.header.search}
            type="text"
          />
        </div>
      </div>

      <div className="flex items-center space-x-4">
        {/* Language Switcher */}
        <div className="flex items-center bg-gray-900/80 border border-gray-800 rounded-lg p-1">
          {languages.map((lang) => (
            <button
              key={lang.code}
              onClick={() => setLanguage(lang.code)}
              className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all duration-200 ${
                language === lang.code
                  ? 'bg-amber-500 text-white shadow-sm'
                  : 'text-gray-500 hover:text-gray-300'
              }`}
            >
              {lang.label}
            </button>
          ))}
        </div>

        <button className="relative p-2 text-gray-400 hover:text-amber-500 transition-colors">
          <Bell className="h-5 w-5" />
          <span className="absolute top-2 right-2 block h-2 w-2 rounded-full bg-red-500 ring-2 ring-[#0a0a0b]" />
        </button>

        {/* Authenticated Wallet Display */}
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center space-x-2">
            <div className="flex items-center space-x-1.5 px-3 py-1 text-[10px] font-bold bg-amber-500/10 text-amber-500 border border-amber-500/30 rounded-full">
               <Shield className="w-3 h-3" />
               <span className="uppercase tracking-tight">SUPER_ADMIN</span>
            </div>
            <button 
              onClick={() => setIsDropdownOpen(!isDropdownOpen)}
              className="flex items-center space-x-2 px-4 py-2 rounded-full border border-gray-800 bg-gray-900 text-gray-300 hover:bg-gray-800 transition-all duration-300 font-mono text-xs font-bold"
            >
              <WalletIcon className="h-4 w-4" />
              <span>{shortenedAddress}</span>
              <ChevronDown className={`h-3 w-3 transition-transform duration-200 ${isDropdownOpen ? 'rotate-180' : ''}`} />
            </button>
          </div>

          {/* Dropdown Menu */}
          {isDropdownOpen && (
            <div className="absolute right-0 mt-3 w-64 bg-gray-900 border border-gray-800 rounded-2xl shadow-2xl p-2 animate-in fade-in slide-in-from-top-2 duration-200">
              <div className="p-3 border-b border-gray-800 mb-2">
                <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-1">{t.header.connected}</p>
                <p className="text-xs font-mono text-gray-200 break-all">{address}</p>
              </div>

              <div className="space-y-1">
                <button 
                  onClick={handleCopy}
                  className="w-full flex items-center justify-between px-3 py-2 text-xs font-medium text-gray-400 hover:text-white hover:bg-gray-800 rounded-xl transition-all"
                >
                  <div className="flex items-center">
                    <Copy className="w-4 h-4 mr-2" />
                    {t.header.copy}
                  </div>
                  {copied && <Check className="w-3 h-3 text-green-500" />}
                </button>

                <button 
                  onClick={onDisconnect}
                  className="w-full flex items-center px-3 py-2 text-xs font-medium text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-xl transition-all"
                >
                  <LogOut className="w-4 h-4 mr-2" />
                  {t.header.disconnect}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </header>
  );
};

export default Header;

import React, { useState } from 'react';
import { UserPlus, Shield, Trash2, Edit2, ShieldAlert, Plus, X, Check } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface Role {
  id: string;
  name: string;
  isSuper?: boolean;
  permissions: string[];
}

interface Admin {
  id: string;
  name: string;
  wallet: string;
  roleId: string;
}

const AdminSettings: React.FC = () => {
  const { t } = useLanguage();

  // Initial Data
  const [roles, setRoles] = useState<Role[]>([
    { id: 'role-1', name: t.admin.roles.super, isSuper: true, permissions: ['*'] },
    { id: 'role-2', name: t.admin.roles.risk, permissions: ['/dashboard', '/market', '/risk', '/health'] },
    { id: 'role-3', name: t.admin.roles.finance, permissions: ['/funds', '/logs'] },
  ]);

  const [admins, setAdmins] = useState<Admin[]>([
    { id: '1', name: 'Root Admin', wallet: '0x71C7...d8976F', roleId: 'role-1' },
    { id: '2', name: 'Risk Lead A', wallet: '0xRisk...1111', roleId: 'role-2' },
    { id: '3', name: 'Finance Lead', wallet: '0xFin...2222', roleId: 'role-3' },
  ]);

  // Modal States
  const [adminModal, setAdminModal] = useState<{ open: boolean, editId?: string }>({ open: false });
  const [roleModal, setRoleModal] = useState<{ open: boolean, editId?: string }>({ open: false });

  // Form States
  const [adminForm, setAdminForm] = useState({ name: '', wallet: '', roleId: 'role-2' });
  const [roleForm, setRoleForm] = useState<{ name: string, permissions: string[] }>({ name: '', permissions: [] });

  const allPerms = [
    { path: '/dashboard', label: t.nav.dashboard },
    { path: '/admin', label: t.nav.admin },
    { path: '/market', label: t.nav.market },
    { path: '/risk', label: t.nav.risk },
    { path: '/health', label: t.nav.health },
    { path: '/alerts', label: t.nav.alerts },
    { path: '/users', label: t.nav.users },
    { path: '/funds', label: t.nav.funds },
    { path: '/logs', label: t.nav.logs },
    { path: '/settings', label: t.nav.params },
  ];

  // Admin Actions
  const openAdminModal = (editId?: string) => {
    if (editId) {
      const admin = admins.find(a => a.id === editId);
      if (admin) setAdminForm({ name: admin.name, wallet: admin.wallet, roleId: admin.roleId });
    } else {
      setAdminForm({ name: '', wallet: '', roleId: roles[1]?.id || 'role-2' });
    }
    setAdminModal({ open: true, editId });
  };

  const handleAdminSubmit = () => {
    if (adminModal.editId) {
      setAdmins(admins.map(a => a.id === adminModal.editId ? { ...a, ...adminForm } : a));
    } else {
      setAdmins([...admins, { id: Math.random().toString(36).substr(2, 9), ...adminForm }]);
    }
    setAdminModal({ open: false });
  };

  const deleteAdmin = (id: string) => {
    setAdmins(admins.filter(a => a.id !== id));
  };

  // Role Actions
  const openRoleModal = (editId?: string) => {
    if (editId) {
      const role = roles.find(r => r.id === editId);
      if (role) setRoleForm({ name: role.name, permissions: role.permissions });
    } else {
      setRoleForm({ name: '', permissions: [] });
    }
    setRoleModal({ open: true, editId });
  };

  const handleRoleSubmit = () => {
    if (roleModal.editId) {
      setRoles(roles.map(r => r.id === roleModal.editId ? { ...r, ...roleForm } : r));
    } else {
      setRoles([...roles, { id: Math.random().toString(36).substr(2, 9), ...roleForm }]);
    }
    setRoleModal({ open: false });
  };

  const deleteRole = (id: string) => {
    setRoles(roles.filter(r => r.id !== id));
  };

  const togglePermission = (path: string) => {
    setRoleForm(prev => ({
      ...prev,
      permissions: prev.permissions.includes(path) 
        ? prev.permissions.filter(p => p !== path) 
        : [...prev.permissions, path]
    }));
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-white">{t.admin.title}</h1>
          <p className="text-gray-400">{t.admin.subtitle}</p>
        </div>
        <div className="flex space-x-3">
          <button 
            onClick={() => openRoleModal()}
            className="flex items-center space-x-2 bg-gray-800 hover:bg-gray-700 px-4 py-2 rounded-lg text-white font-semibold transition-all"
          >
            <Shield className="w-4 h-4 text-amber-500" />
            <span>{t.admin.addRoleBtn}</span>
          </button>
          <button 
            onClick={() => openAdminModal()}
            className="flex items-center space-x-2 bg-amber-500 hover:bg-amber-600 px-4 py-2 rounded-lg text-white font-semibold transition-all shadow-lg shadow-amber-900/20"
          >
            <UserPlus className="w-4 h-4" />
            <span>{t.admin.addBtn}</span>
          </button>
        </div>
      </div>

      <div className="bg-blue-900/10 border border-blue-900/30 p-4 rounded-xl flex items-start space-x-3">
        <ShieldAlert className="w-5 h-5 text-blue-500 flex-shrink-0 mt-0.5" />
        <div className="text-sm text-blue-400">
          <p className="font-semibold mb-1">{t.admin.policyNote}</p>
          <p>{t.admin.policyDesc}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Admin List */}
        <div className="lg:col-span-2 space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.activeAdmins}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-800 text-gray-400 text-xs uppercase font-bold">
                <tr>
                  <th className="px-6 py-4">{t.admin.headers.nameId}</th>
                  <th className="px-6 py-4">{t.admin.headers.wallet}</th>
                  <th className="px-6 py-4">{t.admin.headers.role}</th>
                  <th className="px-6 py-4">{t.common.action}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800">
                {admins.map((admin) => {
                  const role = roles.find(r => r.id === admin.roleId);
                  return (
                    <tr key={admin.id} className="hover:bg-gray-800/20 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-medium text-white">{admin.name}</div>
                        <div className="text-xs text-gray-500">UID: {admin.id}</div>
                      </td>
                      <td className="px-6 py-4 font-mono text-xs text-amber-500">{admin.wallet}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded text-[10px] font-bold ${role?.isSuper ? 'bg-purple-500/20 text-purple-500' : 'bg-blue-500/20 text-blue-500'}`}>
                          {role?.name || t.common.none}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {!role?.isSuper && (
                          <div className="flex space-x-3">
                            <button 
                              onClick={() => openAdminModal(admin.id)}
                              className="text-gray-400 hover:text-amber-500 transition-colors"
                            >
                              <Edit2 className="w-4 h-4" />
                            </button>
                            <button 
                              onClick={() => deleteAdmin(admin.id)}
                              className="text-gray-400 hover:text-red-500 transition-colors"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        {/* Role Definitions */}
        <div className="space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.roleDefs}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl p-6 space-y-4">
            {roles.map(role => (
              <div 
                key={role.id} 
                className="p-4 bg-gray-800/40 rounded-xl border border-gray-800 hover:border-amber-500/50 transition-all relative group"
              >
                <div className="flex items-center justify-between mb-2">
                  <span className={`${role.isSuper ? 'text-amber-500' : 'text-blue-500'} font-bold text-sm uppercase`}>{role.name}</span>
                  {!role.isSuper && (
                    <div className="flex space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => openRoleModal(role.id)} className="text-gray-400 hover:text-white"><Edit2 className="w-3 h-3" /></button>
                      <button onClick={() => deleteRole(role.id)} className="text-gray-400 hover:text-red-500"><Trash2 className="w-3 h-3" /></button>
                    </div>
                  )}
                </div>
                <div className="flex flex-wrap gap-1 mt-2">
                   {role.isSuper ? (
                     <span className="text-[10px] bg-amber-500/10 text-amber-500 px-1.5 py-0.5 rounded">All Access</span>
                   ) : (
                     role.permissions.map(p => (
                       <span key={p} className="text-[10px] bg-gray-700/50 text-gray-400 px-1.5 py-0.5 rounded">
                         {allPerms.find(item => item.path === p)?.label || p}
                       </span>
                     ))
                   )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Modal: Admin Add/Edit */}
      {adminModal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setAdminModal({ open: false })} />
          <div className="relative w-full max-w-md bg-gray-900 border border-gray-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-6">
              {adminModal.editId ? t.admin.modals.editAdmin : t.admin.modals.addAdmin}
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.name}</label>
                <input 
                  type="text" 
                  value={adminForm.name}
                  onChange={e => setAdminForm({...adminForm, name: e.target.value})}
                  className="w-full bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-amber-500 transition-all"
                  placeholder="e.g. Satoshi"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.wallet}</label>
                <input 
                  type="text" 
                  value={adminForm.wallet}
                  onChange={e => setAdminForm({...adminForm, wallet: e.target.value})}
                  className="w-full bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-sm outline-none font-mono focus:border-amber-500 transition-all"
                  placeholder="0x..."
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.role}</label>
                <select 
                  value={adminForm.roleId}
                  onChange={e => setAdminForm({...adminForm, roleId: e.target.value})}
                  className="w-full bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-amber-500 transition-all appearance-none"
                >
                  {roles.map(r => (
                    <option key={r.id} value={r.id}>{r.name}</option>
                  ))}
                </select>
              </div>
            </div>
            <div className="flex space-x-3 mt-8">
              <button 
                onClick={() => setAdminModal({ open: false })}
                className="flex-1 px-4 py-2.5 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm font-bold text-gray-300 transition-all"
              >
                {t.common.cancel}
              </button>
              <button 
                onClick={handleAdminSubmit}
                className="flex-1 px-4 py-2.5 bg-amber-500 hover:bg-amber-600 rounded-xl text-sm font-bold text-white transition-all shadow-lg shadow-amber-900/20"
              >
                {t.common.confirm}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal: Role Add/Edit */}
      {roleModal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setRoleModal({ open: false })} />
          <div className="relative w-full max-w-lg bg-gray-900 border border-gray-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-6">
              {roleModal.editId ? t.admin.modals.editRole : t.admin.modals.addRole}
            </h3>
            <div className="space-y-6">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.name}</label>
                <input 
                  type="text" 
                  value={roleForm.name}
                  onChange={e => setRoleForm({...roleForm, name: e.target.value})}
                  className="w-full bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-amber-500 transition-all"
                  placeholder="e.g. Risk Manager"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-3">{t.admin.modals.fields.permissions}</label>
                <div className="grid grid-cols-2 gap-3 max-h-60 overflow-y-auto pr-2 custom-scroll">
                  {allPerms.map(p => (
                    <button
                      key={p.path}
                      onClick={() => togglePermission(p.path)}
                      className={`flex items-center justify-between p-3 rounded-xl border text-left transition-all ${
                        roleForm.permissions.includes(p.path)
                          ? 'bg-amber-500/10 border-amber-500/50 text-amber-500'
                          : 'bg-gray-800/40 border-gray-800 text-gray-500 hover:border-gray-700'
                      }`}
                    >
                      <span className="text-xs font-medium">{p.label}</span>
                      {roleForm.permissions.includes(p.path) && <Check className="w-3 h-3" />}
                    </button>
                  ))}
                </div>
              </div>
            </div>
            <div className="flex space-x-3 mt-8">
              <button 
                onClick={() => setRoleModal({ open: false })}
                className="flex-1 px-4 py-2.5 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm font-bold text-gray-300 transition-all"
              >
                {t.common.cancel}
              </button>
              <button 
                onClick={handleRoleSubmit}
                className="flex-1 px-4 py-2.5 bg-amber-500 hover:bg-amber-600 rounded-xl text-sm font-bold text-white transition-all shadow-lg shadow-amber-900/20"
              >
                {t.common.confirm}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminSettings;

import React, { useState } from 'react';
import { Trophy, ShieldCheck, Loader2 } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface LoginProps {
  onLogin: (address: string) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const { t } = useLanguage();
  const [connecting, setConnecting] = useState(false);
  const [signing, setSigning] = useState(false);
  const [selectedWallet, setSelectedWallet] = useState<string | null>(null);

  // Using high-quality SVG/PNG icons
  const wallets = [
    { 
      name: t.login.metamask, 
      id: 'metamask', 
      icon: "https://upload.wikimedia.org/wikipedia/commons/3/36/MetaMask_Fox.svg" 
    },
    { 
      name: t.login.okx, 
      id: 'okx', 
      icon: "https://static.okx.com/cdn/assets/imgs/221/9E9A68D5F6B9E8A2.png" 
    },
    { 
      name: t.login.binance, 
      id: 'binance', 
      icon: "https://upload.wikimedia.org/wikipedia/commons/1/12/Binance_logo.svg" 
    },
    { 
      name: t.login.walletconnect, 
      id: 'wc', 
      icon: "https://raw.githubusercontent.com/WalletConnect/walletconnect-assets/master/Logo/Blue%20(Default)/Logo.svg" 
    },
  ];

  const handleConnect = (id: string) => {
    setSelectedWallet(id);
    setConnecting(true);

    // Simulate connection delay
    setTimeout(() => {
      setConnecting(false);
      setSigning(true);

      // Simulate signing delay
      setTimeout(() => {
        onLogin('0x71C7656EC7ab88b098defB751B7401B5f6d8976F');
      }, 2000);
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-[#0a0a0b] flex items-center justify-center p-6 relative overflow-hidden">
      {/* Background Glow */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-amber-500/5 blur-[120px] rounded-full pointer-events-none" />

      <div className="w-full max-w-4xl space-y-8 animate-in fade-in zoom-in-95 duration-700 relative">
        <div className="text-center space-y-4">
          <div className="inline-flex items-center justify-center w-20 h-20 gold-gradient rounded-3xl shadow-2xl shadow-amber-900/40 mb-2">
            <Trophy className="w-10 h-10 text-white" />
          </div>
          <h1 className="text-4xl font-black gold-text tracking-tighter">{t.login.mainTitle}</h1>
          <div className="space-y-2">
            <h2 className="text-xl font-bold text-white">{t.login.title}</h2>
            {/* Ensuring subtitle stays on one line */}
            <p className="text-sm text-gray-400 whitespace-nowrap px-4 w-full text-center">
              {t.login.subtitle}
            </p>
          </div>
        </div>

        <div className="bg-gray-900/40 backdrop-blur-xl border border-gray-800 rounded-[32px] p-8 shadow-2xl mx-auto max-w-md">
          {!connecting && !signing ? (
            <div className="space-y-6">
              <p className="text-xs font-bold text-gray-500 uppercase tracking-widest text-center">{t.login.selectWallet}</p>
              <div className="grid grid-cols-2 gap-4">
                {wallets.map((wallet) => (
                  <button
                    key={wallet.id}
                    onClick={() => handleConnect(wallet.id)}
                    className="flex flex-col items-center justify-center p-4 bg-gray-800/40 border border-gray-800 rounded-2xl hover:border-amber-500/50 hover:bg-amber-500/5 transition-all duration-300 group"
                  >
                    <div className="w-12 h-12 mb-3 flex items-center justify-center group-hover:scale-110 transition-transform">
                      <img src={wallet.icon} alt={wallet.name} className="w-10 h-10 object-contain rounded-md" />
