import React, { useState, useRef, useEffect } from 'react';
import { Search, Bell, Wallet as WalletIcon, ChevronDown, Copy, LogOut, Check, Shield } from 'lucide-react';
import { useLanguage } from '../LanguageContext';
import { Language } from '../translations';

interface HeaderProps {
  address: string;
  onDisconnect: () => void;
}

const Header: React.FC<HeaderProps> = ({ address, onDisconnect }) => {
  const { language, setLanguage, t } = useLanguage();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const languages: { code: Language; label: string }[] = [
    { code: 'en', label: 'EN' },
    { code: 'zhCN', label: '简' },
    { code: 'zhTW', label: '繁' },
  ];

  const shortenedAddress = `${address.slice(0, 6)}...${address.slice(-4)}`;

  const handleCopy = () => {
    navigator.clipboard.writeText(address);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="h-16 bg-[#0a0a0b]/80 backdrop-blur-md border-b border-gray-800 flex items-center justify-between px-8 sticky top-0 z-50 transition-colors duration-300">
      <div className="flex items-center flex-1 max-w-xl">
        <div className="relative w-full">
          <span className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-4 w-4 text-gray-500" />
          </span>
          <input
            className="block w-full bg-gray-900/50 border border-gray-800 rounded-lg py-2 pl-10 pr-3 text-sm placeholder-gray-500 focus:outline-none focus:ring-1 focus:ring-amber-500 focus:border-amber-500 transition-all"
            placeholder={t.header.search}
            type="text"
          />
        </div>
      </div>

      <div className="flex items-center space-x-4">
        {/* Language Switcher */}
        <div className="flex items-center bg-gray-900/80 border border-gray-800 rounded-lg p-1">
          {languages.map((lang) => (
            <button
              key={lang.code}
              onClick={() => setLanguage(lang.code)}
              className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all duration-200 ${
                language === lang.code
                  ? 'bg-amber-500 text-white shadow-sm'
                  : 'text-gray-500 hover:text-gray-300'
              }`}
            >
              {lang.label}
            </button>
          ))}
        </div>

        <button className="relative p-2 text-gray-400 hover:text-amber-500 transition-colors">
          <Bell className="h-5 w-5" />
          <span className="absolute top-2 right-2 block h-2 w-2 rounded-full bg-red-500 ring-2 ring-[#0a0a0b]" />
        </button>

        {/* Authenticated Wallet Display */}
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center space-x-2">
            <div className="flex items-center space-x-1.5 px-3 py-1 text-[10px] font-bold bg-amber-500/10 text-amber-500 border border-amber-500/30 rounded-full">
               <Shield className="w-3 h-3" />
               <span className="uppercase tracking-tight">{t.admin.roles.super}</span>
            </div>
            <button 
              onClick={() => setIsDropdownOpen(!isDropdownOpen)}
              className="flex items-center space-x-2 px-4 py-2 rounded-full border border-gray-800 bg-gray-900 text-gray-300 hover:bg-gray-800 transition-all duration-300 font-mono text-xs font-bold"
            >
              <WalletIcon className="h-4 w-4" />
              <span>{shortenedAddress}</span>
              <ChevronDown className={`h-3 w-3 transition-transform duration-200 ${isDropdownOpen ? 'rotate-180' : ''}`} />
            </button>
          </div>

          {/* Dropdown Menu */}
          {isDropdownOpen && (
            <div className="absolute right-0 mt-3 w-64 bg-gray-900 border border-gray-800 rounded-2xl shadow-2xl p-2 animate-in fade-in slide-in-from-top-2 duration-200">
              <div className="p-3 border-b border-gray-800 mb-2">
                <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-1">{t.header.connected}</p>
                <p className="text-xs font-mono text-gray-200 break-all">{address}</p>
              </div>

              <div className="space-y-1">
                <button 
                  onClick={handleCopy}
                  className="w-full flex items-center justify-between px-3 py-2 text-xs font-medium text-gray-400 hover:text-white hover:bg-gray-800 rounded-xl transition-all"
                >
                  <div className="flex items-center">
                    <Copy className="w-4 h-4 mr-2" />
                    {t.header.copy}
                  </div>
                  {copied && <Check className="w-3 h-3 text-green-500" />}
                </button>

                <button 
                  onClick={onDisconnect}
                  className="w-full flex items-center px-3 py-2 text-xs font-medium text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-xl transition-all"
                >
                  <LogOut className="w-4 h-4 mr-2" />
                  {t.header.disconnect}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </header>
  );
};

export default Header;

import React, { useState } from 'react';
import { UserPlus, Shield, Trash2, Edit2, ShieldAlert, Plus, X, Check } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface Role {
  id: string;
  name: string;
  isSuper?: boolean;
  permissions: string[];
}

interface Admin {
  id: string;
  name: string;
  wallet: string;
  roleId: string;
}

const AdminSettings: React.FC = () => {
  const { t } = useLanguage();

  const [roles, setRoles] = useState<Role[]>([
    { id: 'role-1', name: t.admin.roles.super, isSuper: true, permissions: ['*'] },
    { id: 'role-2', name: t.admin.roles.risk, permissions: ['/dashboard', '/market', '/risk', '/health'] },
    { id: 'role-3', name: t.admin.roles.finance, permissions: ['/funds', '/logs'] },
  ]);

  const [admins, setAdmins] = useState<Admin[]>([
    { id: '1', name: 'Root Admin', wallet: '0x71C7...d8976F', roleId: 'role-1' },
    { id: '2', name: 'Risk Lead A', wallet: '0xRisk...1111', roleId: 'role-2' },
    { id: '3', name: 'Finance Lead', wallet: '0xFin...2222', roleId: 'role-3' },
  ]);

  const [adminModal, setAdminModal] = useState<{ open: boolean, editId?: string }>({ open: false });
  const [roleModal, setRoleModal] = useState<{ open: boolean, editId?: string }>({ open: false });

  const [adminForm, setAdminForm] = useState({ name: '', wallet: '', roleId: 'role-2' });
  const [roleForm, setRoleForm] = useState<{ name: string, permissions: string[] }>({ name: '', permissions: [] });

  const allPerms = [
    { path: '/dashboard', label: t.nav.dashboard },
    { path: '/admin', label: t.nav.admin },
    { path: '/market', label: t.nav.market },
    { path: '/risk', label: t.nav.risk },
    { path: '/health', label: t.nav.health },
    { path: '/alerts', label: t.nav.alerts },
    { path: '/users', label: t.nav.users },
    { path: '/funds', label: t.nav.funds },
    { path: '/logs', label: t.nav.logs },
    { path: '/settings', label: t.nav.params },
  ];

  const openAdminModal = (editId?: string) => {
    if (editId) {
      const admin = admins.find(a => a.id === editId);
      if (admin) setAdminForm({ name: admin.name, wallet: admin.wallet, roleId: admin.roleId });
    } else {
      setAdminForm({ name: '', wallet: '', roleId: roles[1]?.id || 'role-2' });
    }
    setAdminModal({ open: true, editId });
  };

  const handleAdminSubmit = () => {
    if (adminModal.editId) {
      setAdmins(admins.map(a => a.id === adminModal.editId ? { ...a, ...adminForm } : a));
    } else {
      setAdmins([...admins, { id: Math.random().toString(36).substr(2, 9), ...adminForm }]);
    }
    setAdminModal({ open: false });
  };

  const deleteAdmin = (id: string) => {
    setAdmins(admins.filter(a => a.id !== id));
  };

  const openRoleModal = (editId?: string) => {
    if (editId) {
      const role = roles.find(r => r.id === editId);
      if (role) setRoleForm({ name: role.name, permissions: role.permissions });
    } else {
      setRoleForm({ name: '', permissions: [] });
    }
    setRoleModal({ open: true, editId });
  };

  const handleRoleSubmit = () => {
    if (roleModal.editId) {
      setRoles(roles.map(r => r.id === roleModal.editId ? { ...r, ...roleForm } : r));
    } else {
      setRoles([...roles, { id: Math.random().toString(36).substr(2, 9), ...roleForm }]);
    }
    setRoleModal({ open: false });
  };

  const deleteRole = (id: string) => {
    setRoles(roles.filter(r => r.id !== id));
  };

  const togglePermission = (path: string) => {
    setRoleForm(prev => ({
      ...prev,
      permissions: prev.permissions.includes(path) 
        ? prev.permissions.filter(p => p !== path) 
        : [...prev.permissions, path]
    }));
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-white">{t.admin.title}</h1>
          <p className="text-gray-400">{t.admin.subtitle}</p>
        </div>
        <div className="flex space-x-3">
          <button 
            onClick={() => openRoleModal()}
            className="flex items-center space-x-2 bg-gray-800 hover:bg-gray-700 px-4 py-2 rounded-lg text-white font-semibold transition-all"
          >
            <Shield className="w-4 h-4 text-amber-500" />
            <span>{t.admin.addRoleBtn}</span>
          </button>
          <button 
            onClick={() => openAdminModal()}
            className="flex items-center space-x-2 bg-amber-500 hover:bg-amber-600 px-4 py-2 rounded-lg text-white font-semibold transition-all shadow-lg shadow-amber-900/20"
          >
            <UserPlus className="w-4 h-4" />
            <span>{t.admin.addBtn}</span>
          </button>
        </div>
      </div>

      <div className="bg-blue-900/10 border border-blue-900/30 p-4 rounded-xl flex items-start space-x-3">
        <ShieldAlert className="w-5 h-5 text-blue-500 flex-shrink-0 mt-0.5" />
        <div className="text-sm text-blue-400">
          <p className="font-semibold mb-1">{t.admin.policyNote}</p>
          <p>{t.admin.policyDesc}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.activeAdmins}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-800 text-gray-400 text-xs uppercase font-bold">
                <tr>
                  <th className="px-6 py-4">{t.admin.headers.nameId}</th>
                  <th className="px-6 py-4">{t.admin.headers.wallet}</th>
                  <th className="px-6 py-4">{t.admin.headers.role}</th>
                  <th className="px-6 py-4">{t.common.action}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800">
                {admins.map((admin) => {
                  const role = roles.find(r => r.id === admin.roleId);
                  return (
                    <tr key={admin.id} className="hover:bg-gray-800/20 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-medium text-white">{admin.name}</div>
                        <div className="text-xs text-gray-500">UID: {admin.id}</div>
                      </td>
                      <td className="px-6 py-4 font-mono text-xs text-amber-500">{admin.wallet}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded text-[10px] font-bold ${role?.isSuper ? 'bg-purple-500/20 text-purple-500' : 'bg-blue-500/20 text-blue-500'}`}>
                          {role?.name || t.common.none}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {!role?.isSuper && (
                          <div className="flex space-x-3">
                            <button 
                              onClick={() => openAdminModal(admin.id)}
                              className="text-gray-400 hover:text-amber-500 transition-colors"
                            >
                              <Edit2 className="w-4 h-4" />
                            </button>
                            <button 
                              onClick={() => deleteAdmin(admin.id)}
                              className="text-gray-400 hover:text-red-500 transition-colors"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.roleDefs}</h2>
