                  <td className="px-6 py-5">
                    <span className={`text-[10px] font-black px-2 py-1 rounded-md tracking-tighter ${trade.orderType === t.market.marketOrder ? 'bg-blue-500/10 text-blue-500' : 'bg-purple-500/10 text-purple-500'}`}>
