                    <ChevronDown className="h-3 w-3 text-amber-500" />
                  </div>
                </div>
              )}
            </div>

            <div className={`grid gap-4 ${category.isBusiness ? 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-4' : 'grid-cols-1'}`}>
              {category.metrics.map((metric, mIdx) => (
                <div key={mIdx} className="flex items-center justify-between p-4 rounded-xl bg-gray-800/30 border border-transparent hover:border-gray-700 transition-colors">
                  <div className="flex items-center space-x-3">
                    {!category.isBusiness && (metric.status === 'green' ? <CheckCircle2 className="w-5 h-5 text-green-500" /> : <AlertCircle className="w-5 h-5 text-amber-500" />)}
                    <div>
                      <p className="text-sm font-medium text-gray-300">{metric.label}</p>
                      {metric.desc && <p className="text-[10px] text-gray-500 uppercase tracking-wider">{metric.desc}</p>}
                    </div>
                  </div>
                  <div className="text-right">
                    <div className={`text-lg font-black ${category.isBusiness ? 'text-white' : (metric.status === 'green' ? 'text-white' : 'text-amber-500')}`}>
                      {metric.value}
                    </div>
                    {category.isBusiness && metric.trend !== undefined && (
                      <div className={`flex items-center justify-end text-[10px] font-bold ${getTrendColor(metric.trend)}`}>
                        {metric.trend > 0 ? '+' : ''}{metric.trend}%
                        {getTrendIcon(metric.trend)}
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default SystemHealth;

