                  <div className="flex items-center space-x-3">
                    <div className={`p-2 rounded-xl transition-colors ${mainTab === 'DEPOSIT' ? 'bg-green-500/10 text-green-500' : 'bg-amber-500/10 text-amber-500'}`}>
