                { label: t.contract.params.maxMarketQty, val: '10', unit: form.symbol, desc: t.contract.params.desc.maxMarketQty },
                { label: t.contract.params.maxLimitQty, val: '10', unit: form.symbol, desc: t.contract.params.desc.maxLimitQty },
                { label: t.contract.params.maxOpenOrders, val: '200', unit: t.contract.params.units.count, desc: t.contract.params.desc.maxOpenOrders },
                { label: t.contract.params.minOrderPrice, val: '0.01', unit: 'USDC', desc: t.contract.params.desc.minOrderPrice },
                { label: t.contract.params.minPriceFluc, val: '0.01', unit: 'USDC', desc: t.contract.params.desc.minPriceFluc },
                { label: t.contract.params.marketPriceCap, val: '3', unit: t.contract.params.units.pct, desc: t.contract.params.desc.marketPriceCap },
                { label: t.contract.params.limitPriceUpper, val: '3', unit: t.contract.params.units.pct, desc: t.contract.params.desc.limitPriceUpper },
                { label: t.contract.params.limitPriceLower, val: '3', unit: t.contract.params.units.pct, desc: t.contract.params.desc.limitPriceLower },
              ].map((p, idx) => (
                <div key={idx} className="space-y-1.5">
