                  <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">{t.contract.modals.pendingSigs}</span>
                  <div className="flex space-x-2">
                    {[1, 2].map(n => (
                      <div key={n} className={`w-10 h-10 rounded-xl border flex items-center justify-center transition-all ${sigCount >= n ? 'bg-green-500/20 border-green-500 text-green-500' : 'bg-gray-800 border-gray-700 text-gray-600'}`}>
                        {sigCount >= n ? <Shield className="w-5 h-5" /> : <Shield className="w-5 h-5 opacity-20" />}
                      </div>
                    ))}
                  </div>
                </div>
                <div className="text-sm text-gray-500 font-medium max-w-[200px]">
                  {t.contract.modals.sigRequired}
                </div>
              </div>

              <div className="flex space-x-4 w-full md:w-auto">
                <button 
                  onClick={simulateSigning}
                  disabled={isSigning || sigCount >= 2}
                  className={`flex-1 md:flex-none px-8 py-4 rounded-2xl text-sm font-black uppercase tracking-widest transition-all flex items-center justify-center
                    ${sigCount >= 2 ? 'bg-gray-800 text-gray-500 cursor-default' : 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-900/20 active:scale-95'}
                  `}
                >
                  {isSigning ? <Loader2 className="w-5 h-5 animate-spin mr-2" /> : <Shield className="w-5 h-5 mr-2" />}
                  {t.contract.modals.sign}
                </button>
                <button 
                  onClick={handleCommitParams}
                  disabled={sigCount < 2}
                  className={`flex-1 md:flex-none px-10 py-4 rounded-2xl text-sm font-black uppercase tracking-widest transition-all
                    ${sigCount < 2 ? 'bg-gray-800 text-gray-700 cursor-not-allowed' : 'bg-green-500 hover:bg-green-400 text-white shadow-xl shadow-green-900/20 active:scale-95'}
                  `}
                >
                   {t.contract.modals.submit}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

