                    type="text" 
                    value={paramValues[p.key as keyof ParamState]}
                    onChange={(e) => setParamValues({...paramValues, [p.key]: e.target.value})}
                    placeholder="..."
                    className={`w-full bg-gray-950 border ${paramValues[p.key as keyof ParamState].trim() === '' ? 'border-red-500/50 shadow-[0_0_5px_rgba(239,68,68,0.2)]' : 'border-gray-800'} rounded-xl px-4 py-2 text-sm font-bold text-white outline-none focus:border-blue-500 transition-all`}
                  />
                  <p className="text-[9px] text-gray-600 leading-relaxed px-1 line-clamp-2" title={p.desc}>{p.desc}</p>
                </div>
              ))}
            </div>

            <div className="mt-8 pt-6 border-t border-gray-800 flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex items-center space-x-6">
                <div className="flex flex-col">
                  <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">{t.contract.modals.pendingSigs}</span>
                  <div className="flex space-x-2">
                    {[1, 2].map(n => (
                      <div key={n} className={`w-8 h-8 rounded-lg border flex items-center justify-center transition-all ${sigCount >= n ? 'bg-green-500/20 border-green-500 text-green-500' : 'bg-gray-800 border-gray-700 text-gray-600'}`}>
                        {sigCount >= n ? <Shield className="w-4 h-4" /> : <Shield className="w-4 h-4 opacity-20" />}
                      </div>
                    ))}
                  </div>
                </div>
                <div className="text-xs text-gray-500 font-medium max-w-[180px]">
                  {t.contract.modals.sigRequired}
                </div>
              </div>

              <div className="flex space-x-4 w-full md:w-auto">
                <button 
                  onClick={simulateSigning}
                  disabled={isSigning || sigCount >= 2 || !isParamsValid}
                  className={`flex-1 md:flex-none px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center
                    ${sigCount >= 2 ? 'bg-gray-800 text-gray-500 cursor-default' : 
                      (!isParamsValid ? 'bg-gray-800 text-gray-600 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-900/20 active:scale-95')}
                  `}
                >
                  {isSigning ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Shield className="w-4 h-4 mr-2" />}
                  {t.contract.modals.sign}
                </button>
                <button 
                  onClick={handleCommitParams}
                  disabled={sigCount < 2}
                  className={`flex-1 md:flex-none px-8 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all
                    ${sigCount < 2 ? 'bg-gray-800 text-gray-700 cursor-not-allowed' : 'bg-green-500 hover:bg-green-400 text-white shadow-xl shadow-green-900/20 active:scale-95'}
                  `}
                >
                   {t.contract.modals.submit}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ContractManager;

import React, { useState, useMemo } from 'react';
import { Bell, CheckCheck, Clock, Calendar, Filter } from 'lucide-react';
import { Alert as AlertType } from '../types';
import { useLanguage } from '../LanguageContext';

interface EnhancedAlert extends Omit<AlertType, 'type' | 'description'> {
  typeKey: string;
}

const AlertCenter: React.FC = () => {
  const { t } = useLanguage();
  const [activeTab, setActiveTab] = useState<'ALL' | 'UNREAD'>('ALL');

  // Filtering state
  const [typeFilter, setTypeFilter] = useState('ALL');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Safety helper for translation access
  const safeT = useMemo(() => {
    return t.alerts?.messages || {};
  }, [t]);

  // Initial data using keys instead of translated strings to prevent crash and support language switching
  const [alerts, setAlerts] = useState<EnhancedAlert[]>([
    { 
      id: 'A001', 
      timestamp: '2025-12-10 12:45:00', 
      contract: 'XAUUSDC', 
      typeKey: 'oracleDelay', 
      level: 'MEDIUM', 
      isRead: false 
    },
    { 
      id: 'A002', 
      timestamp: '2025-12-10 12:44:12', 
      contract: 'XAUUSDC', 
      typeKey: 'highMarginRate', 
      level: 'HIGH', 
      isRead: false 
    },
    { 
      id: 'A003', 
      timestamp: '2025-12-10 12:30:05', 
      contract: 'XAUUSDC', 
      typeKey: 'liqEvent', 
      level: 'HIGH', 
      isRead: true 
    },
    { 
      id: 'A004', 
      timestamp: '2025-12-10 12:15:00', 
      contract: 'XAUUSDC', 
      typeKey: 'priceAnomaly', 
      level: 'LOW', 
      isRead: true 
    },
  ]);

  const handleMarkAsRead = (id: string) => {
    setAlerts(prev => prev.map(a => a.id === id ? { ...a, isRead: true } : a));
  };

  const handleMarkAllAsRead = () => {
    setAlerts(prev => prev.map(a => ({ ...a, isRead: true })));
  };

  const alertTypes = useMemo(() => [
    { label: t.common.all, value: 'ALL' },
    { label: safeT.oracleDelay || 'Oracle Delay', value: 'oracleDelay' },
    { label: safeT.highMarginRate || 'High MR', value: 'highMarginRate' },
    { label: safeT.liqEvent || 'Liquidation', value: 'liqEvent' },
    { label: safeT.priceAnomaly || 'Price Anomaly', value: 'priceAnomaly' },
  ], [t, safeT]);

  const filteredAlerts = useMemo(() => {
    return alerts.filter(alert => {
      // Status filter
      if (activeTab === 'UNREAD' && alert.isRead) return false;

      // Type filter
      if (typeFilter !== 'ALL' && alert.typeKey !== typeFilter) return false;

      // Date filter
      if (dateRange.start) {
        const alertDate = alert.timestamp.split(' ')[0];
        if (alertDate < dateRange.start) return false;
      }
      if (dateRange.end) {
        const alertDate = alert.timestamp.split(' ')[0];
        if (alertDate > dateRange.end) return false;
      }

      return true;
    });
  }, [alerts, activeTab, typeFilter, dateRange]);

  const getUnreadBorderStyle = (level: string) => {
    switch (level) {
      case 'HIGH': return 'border-red-500/50 ring-1 ring-red-500/10 shadow-[0_0_15px_rgba(239,68,68,0.1)]';
      case 'MEDIUM': return 'border-amber-500/50 ring-1 ring-amber-500/10 shadow-[0_0_15px_rgba(245,158,11,0.1)]';
      case 'LOW': return 'border-green-500/50 ring-1 ring-green-500/10 shadow-[0_0_15px_rgba(34,197,94,0.1)]';
      default: return 'border-gray-800';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center">
            <Bell className="w-6 h-6 mr-3 text-amber-500" />
            {t.alerts?.title || 'Alerts'}
          </h1>
          <p className="text-gray-400">{t.alerts?.subtitle || 'System Notifications'}</p>
        </div>
        <button 
          onClick={handleMarkAllAsRead}
          className="flex items-center space-x-2 text-gray-400 hover:text-amber-500 transition-colors bg-gray-900 border border-gray-800 px-4 py-2 rounded-xl"
        >
          <CheckCheck className="w-4 h-4" />
          <span className="text-sm font-bold uppercase tracking-tight">{t.alerts?.markRead || 'Ack All'}</span>
        </button>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-gray-900/40 border border-gray-800 rounded-2xl p-4 flex flex-wrap gap-4 items-center">
        {/* Unread Switcher */}
        <div className="bg-gray-900 border border-gray-800 p-1 rounded-xl flex shrink-0">
          <button 
            onClick={() => setActiveTab('ALL')}
            className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${activeTab === 'ALL' ? 'bg-amber-500 text-white' : 'text-gray-500 hover:text-white'}`}
          >
            {t.alerts?.allMsgs || 'All'}
          </button>
          <button 
            onClick={() => setActiveTab('UNREAD')}
            className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${activeTab === 'UNREAD' ? 'bg-amber-500 text-white' : 'text-gray-500 hover:text-white'}`}
          >
            {t.alerts?.unread || 'Unread'}
          </button>
        </div>

        {/* Type Filter */}
        <div className="flex items-center space-x-2 bg-gray-900 border border-gray-800 rounded-xl px-3 py-1.5 hover:border-gray-700 transition-all">
          <Filter className="w-3.5 h-3.5 text-gray-500" />
          <span className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">{t.alerts?.filterType || 'Category'}:</span>
          <select 
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
            className="bg-transparent text-xs text-gray-300 font-bold outline-none cursor-pointer pr-4"
          >
            {alertTypes.map(type => (
              <option key={type.value} value={type.value} className="bg-gray-900">{type.label}</option>
            ))}
          </select>
        </div>

        {/* Date Filter */}
        <div className="flex items-center bg-gray-900 border border-gray-800 rounded-xl px-4 py-1.5 space-x-3 group hover:border-gray-700 transition-all">
          <Calendar className="w-4 h-4 text-gray-500 group-hover:text-amber-500 transition-colors" />
          <div className="flex items-center space-x-2">
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">{t.market?.dateRange || 'Range'}:</span>
            <input 
              type="date" 
              className="bg-transparent text-xs text-gray-300 outline-none [color-scheme:dark] cursor-pointer"
              value={dateRange.start}
              onChange={(e) => setDateRange({...dateRange, start: e.target.value})}
            />
            <span className="text-gray-700">-</span>
            <input 
              type="date" 
              className="bg-transparent text-xs text-gray-300 outline-none [color-scheme:dark] cursor-pointer"
              value={dateRange.end}
              onChange={(e) => setDateRange({...dateRange, end: e.target.value})}
            />
          </div>
        </div>
      </div>

      <div className="space-y-4">
        {filteredAlerts.length > 0 ? (
          filteredAlerts.map((alert) => (
            <div 
              key={alert.id} 
              className={`bg-gray-900/40 border rounded-2xl p-5 transition-all flex items-start space-x-4
                ${alert.isRead ? 'border-gray-800 opacity-60 grayscale-[0.3]' : getUnreadBorderStyle(alert.level)}
              `}
            >
              <div className={`mt-1.5 h-3 w-3 rounded-full flex-shrink-0
                ${alert.level === 'HIGH' ? 'bg-red-500 shadow-[0_0_10px_rgba(239,68,68,0.5)]' : 
                  alert.level === 'MEDIUM' ? 'bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.5)]' : 
                  'bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]'}
              `} />

              <div className="flex-1 space-y-1">
                <div className="flex justify-between items-start">
                  <h4 className={`font-bold tracking-wide transition-colors ${alert.isRead ? 'text-gray-400' : 'text-white'}`}>
                    {(safeT as any)[alert.typeKey] || alert.typeKey}
                  </h4>
                  <div className="flex items-center text-[10px] text-gray-500 font-mono">
                    <Clock className="w-3 h-3 mr-1" />
                    {alert.timestamp}
                  </div>
                </div>
                <div className="flex items-center space-x-2 mb-2">
                  <span className={`text-[10px] font-black px-1.5 py-0.5 rounded tracking-tighter uppercase ${alert.isRead ? 'bg-gray-800 text-gray-600' : 'bg-amber-500/10 text-amber-500'}`}>{alert.contract}</span>
                  <span className={`text-[10px] font-black px-1.5 py-0.5 rounded tracking-tighter uppercase
                    ${alert.isRead ? 'bg-gray-800 text-gray-600' : (
                      alert.level === 'HIGH' ? 'bg-red-900/20 text-red-500' : 
                      alert.level === 'MEDIUM' ? 'bg-amber-900/20 text-amber-500' : 
                      'bg-green-900/20 text-green-500'
                    )}
                  `}>
                    {(t.common?.level || 'Level')}: {(t.common?.levels as any)?.[alert.level] || alert.level}
                  </span>
                </div>
                <p className={`text-sm leading-relaxed ${alert.isRead ? 'text-gray-500' : 'text-gray-300'}`}>
                  {(safeT as any)[`${alert.typeKey}Desc`] || 'Alert details...'}
                </p>

                {!alert.isRead && (
                  <div className="pt-4">
                    <button 
                      onClick={() => handleMarkAsRead(alert.id)}
                      className="text-xs font-black text-amber-500 hover:text-amber-400 transition-colors uppercase tracking-widest flex items-center group"
                    >
                      <CheckCheck className="w-3.5 h-3.5 mr-1.5 opacity-0 group-hover:opacity-100 transition-opacity" />
                      {t.alerts?.ack || 'Acknowledge'}
                    </button>
                  </div>
                )}
              </div>
            </div>
          ))
        ) : (
          <div className="py-20 flex flex-col items-center justify-center text-center opacity-30">
             <Bell className="w-16 h-16 mb-4" />
             <p className="text-sm font-bold uppercase tracking-widest">{t.common?.none || 'None'}</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default AlertCenter;

import React, { useState, useMemo } from 'react';
import { Trophy, Plus, Edit2, Settings, Shield, Loader2, Save, X, Image as ImageIcon, Search } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface ContractItem {
  id: string;
  name: string;
  symbol: string;
  icon: string;
}

interface ParamState {
  maxLeverage: string;
  minOrderQty: string;
  minNotional: string;
  maxMarketQty: string;
  maxLimitQty: string;
  maxOpenOrders: string;
  minOrderPrice: string;
  minPriceFluc: string;
  marketPriceCap: string;
  limitPriceUpper: string;
  limitPriceLower: string;
}

const ContractManager: React.FC = () => {
  const { t } = useLanguage();

  const [contracts, setContracts] = useState<ContractItem[]>([
    { id: 'T001', name: '黄金', symbol: 'XAU', icon: 'https://cdn-icons-png.flaticon.com/512/2992/2992742.png' },
    { id: 'T002', name: '比特币', symbol: 'BTC', icon: 'https://cryptologos.cc/logos/bitcoin-btc-logo.svg' },
  ]);

  const [searchQuery, setSearchQuery] = useState('');
  const [modal, setModal] = useState<{ open: boolean, type: 'ADD' | 'EDIT' | 'PARAMS', selectedId?: string }>({ open: false, type: 'ADD' });
  const [form, setForm] = useState({ name: '', symbol: '', icon: '' });
  const [formErrors, setFormErrors] = useState({ name: false, symbol: false });

  // Params State
  const [paramValues, setParamValues] = useState<ParamState>({
    maxLeverage: '20',
    minOrderQty: '0.001',
    minNotional: '5',
    maxMarketQty: '10',
    maxLimitQty: '10',
    maxOpenOrders: '200',
    minOrderPrice: '0.01',
    minPriceFluc: '0.01',
    marketPriceCap: '3',
    limitPriceUpper: '3',
    limitPriceLower: '3',
  });

  // Multi-sig state simulation
  const [sigCount, setSigCount] = useState(0);
  const [isSigning, setIsSigning] = useState(false);

  const openModal = (type: 'ADD' | 'EDIT' | 'PARAMS', id?: string) => {
    const item = contracts.find(c => c.id === id);
    if (item && (type === 'EDIT' || type === 'PARAMS')) {
      setForm({ name: item.name, symbol: item.symbol, icon: item.icon });
    } else {
      setForm({ name: '', symbol: '', icon: '' });
    }
    setFormErrors({ name: false, symbol: false });
    setSigCount(0);
    setModal({ open: true, type, selectedId: id });
  };

  const handleSaveInfo = () => {
    const errors = {
      name: !form.name.trim(),
      symbol: !form.symbol.trim()
    };
    setFormErrors(errors);

    if (errors.name || errors.symbol) return;

    if (modal.type === 'ADD') {
      const newId = `T00${contracts.length + 1}`;
      setContracts([...contracts, { ...form, id: newId }]);
    } else if (modal.type === 'EDIT') {
      setContracts(contracts.map(c => c.id === modal.selectedId ? { ...c, ...form } : c));
    }
    setModal({ ...modal, open: false });
  };

  const isParamsValid = useMemo(() => {
    return Object.values(paramValues).every(val => val.trim() !== '');
  }, [paramValues]);

  const simulateSigning = () => {
    if (!isParamsValid) return;
    setIsSigning(true);
    setTimeout(() => {
      setSigCount(prev => Math.min(prev + 1, 2));
      setIsSigning(false);
    }, 1200);
  };

  const handleCommitParams = () => {
    if (sigCount >= 2) {
      alert("Parameters committed successfully with multi-sig approval.");
      setModal({ ...modal, open: false });
    }
  };

  const filteredContracts = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return contracts;
    return contracts.filter(c => 
      c.name.toLowerCase().includes(query) || 
      c.symbol.toLowerCase().includes(query)
    );
  }, [contracts, searchQuery]);

  const paramConfigList = [
    { key: 'maxLeverage', label: t.contract.params.maxLeverage, unit: t.contract.params.units.times, desc: t.contract.params.desc.maxLeverage },
    { key: 'minOrderQty', label: t.contract.params.minOrderQty, unit: form.symbol, desc: t.contract.params.desc.minOrderQty },
    { key: 'minNotional', label: t.contract.params.minNotional, unit: 'USDC', desc: t.contract.params.desc.minNotional },
    { key: 'maxMarketQty', label: t.contract.params.maxMarketQty, unit: form.symbol, desc: t.contract.params.desc.maxMarketQty },
    { key: 'maxLimitQty', label: t.contract.params.maxLimitQty, unit: form.symbol, desc: t.contract.params.desc.maxLimitQty },
    { key: 'maxOpenOrders', label: t.contract.params.maxOpenOrders, unit: t.contract.params.units.count, desc: t.contract.params.desc.maxOpenOrders },
    { key: 'minOrderPrice', label: t.contract.params.minOrderPrice, unit: 'USDC', desc: t.contract.params.desc.minOrderPrice },
    { key: 'minPriceFluc', label: t.contract.params.minPriceFluc, unit: 'USDC', desc: t.contract.params.desc.minPriceFluc },
    { key: 'marketPriceCap', label: t.contract.params.marketPriceCap, unit: t.contract.params.units.pct, desc: t.contract.params.desc.marketPriceCap },
    { key: 'limitPriceUpper', label: t.contract.params.limitPriceUpper, unit: t.contract.params.units.pct, desc: t.contract.params.desc.limitPriceUpper },
    { key: 'limitPriceLower', label: t.contract.params.limitPriceLower, unit: t.contract.params.units.pct, desc: t.contract.params.desc.limitPriceLower },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center tracking-tight">
            <Trophy className="w-6 h-6 mr-3 text-amber-500" />
            {t.contract.title}
          </h1>
          <p className="text-gray-400 text-sm">{t.contract.subtitle}</p>
        </div>
        <div className="flex w-full md:w-auto space-x-3">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-500" />
            <input 
              type="text" 
              placeholder={t.common.search}
              className="w-full bg-gray-900 border border-gray-800 rounded-xl py-2 pl-10 pr-4 text-sm text-gray-300 outline-none focus:border-amber-500/50 transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            onClick={() => openModal('ADD')}
            className="bg-amber-500 hover:bg-amber-600 text-white px-6 py-2 rounded-xl font-bold flex items-center shadow-lg shadow-amber-900/20 transition-all whitespace-nowrap"
          >
            <Plus className="w-4 h-4 mr-2" />
            {t.contract.addBtn}
          </button>
        </div>
      </div>

      <div className="bg-gray-900/40 border border-gray-800 rounded-3xl overflow-hidden shadow-2xl">
        <table className="w-full text-left">
          <thead className="bg-gray-800/50 text-gray-400 text-[10px] font-black uppercase tracking-widest">
            <tr>
              <th className="px-6 py-5">{t.contract.table.icon}</th>
              <th className="px-6 py-5">{t.contract.table.id}</th>
              <th className="px-6 py-5">{t.contract.table.name}</th>
              <th className="px-6 py-5">{t.contract.table.symbol}</th>
              <th className="px-6 py-5">{t.contract.table.pair}</th>
              <th className="px-6 py-5 text-right">{t.common.action}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-800/50">
            {filteredContracts.length > 0 ? filteredContracts.map(item => (
              <tr key={item.id} className="hover:bg-amber-500/[0.01] transition-all group">
                <td className="px-6 py-5">
                  <div className="w-10 h-10 rounded-xl bg-gray-800 p-2 flex items-center justify-center border border-gray-700 group-hover:border-amber-500/50 transition-colors">
                    <img src={item.icon || 'https://cdn-icons-png.flaticon.com/512/2992/2992742.png'} alt={item.symbol} className="w-full h-full object-contain" />
                  </div>
                </td>
                <td className="px-6 py-5 text-sm font-mono text-gray-500">{item.id}</td>
                <td className="px-6 py-5 text-sm font-bold text-white">{item.name}</td>
                <td className="px-6 py-5 text-sm font-black text-amber-500">{item.symbol}</td>
                <td className="px-6 py-5 text-sm font-bold text-gray-300">{item.symbol}USDC</td>
                <td className="px-6 py-5">
                  <div className="flex justify-end space-x-2">
                    <button 
                      onClick={() => openModal('EDIT', item.id)}
                      className="p-2 text-gray-400 hover:text-amber-500 bg-gray-800/50 hover:bg-amber-500/10 rounded-xl transition-all border border-gray-800 hover:border-amber-500/30"
                      title={t.contract.editBtn}
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => openModal('PARAMS', item.id)}
                      className="p-2 text-gray-400 hover:text-blue-500 bg-gray-800/50 hover:bg-blue-500/10 rounded-xl transition-all border border-gray-800 hover:border-blue-500/30"
                      title={t.contract.setParams}
                    >
                      <Settings className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            )) : (
              <tr>
                <td colSpan={6} className="px-6 py-20 text-center opacity-30">
                  <div className="flex flex-col items-center">
                    <X className="w-10 h-10 mb-2" />
                    <span className="text-sm font-bold uppercase tracking-widest">{t.common.noData}</span>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Info Add/Edit Modal */}
      {(modal.open && (modal.type === 'ADD' || modal.type === 'EDIT')) && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setModal({ ...modal, open: false })} />
          <div className="relative w-full max-w-md bg-gray-900 border border-gray-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-6">
              {modal.type === 'ADD' ? t.contract.modals.addTitle : t.contract.modals.editTitle}
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">{t.contract.modals.uploadIcon}</label>
                <div className="flex items-center space-x-4">
