            <div className="flex space-x-3 mt-8">
              <button 
                onClick={() => setAdminModal({ open: false })}
                className="flex-1 px-4 py-2.5 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm font-bold text-gray-300 transition-all"
