    { id: 'P1', typeKey: 'posOpen', userId: 'U776655', ip: '11.22.33.44', address: '0x999000...111a', time: '2025-12-10 11:45:10', category: 'POS', meta: { id: 'P223', sym: 'XAUUSDC', side: t.market.long, lev: '20', qty: '23.42', price: '2234.22' } },
