              <ShieldAlert className="w-4 h-4 mr-2" />
              {t.risk.monitoring}
            </span>
          </div>
        </div>
      </div>

      {/* Global Insurance Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-gradient-to-br from-gray-900/80 to-gray-900/40 border border-gray-800 p-6 rounded-2xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
            <ShieldCheck className="w-12 h-12 text-green-500" />
          </div>
          <p className="text-xs text-gray-500 uppercase font-black tracking-widest mb-2">{t.risk.insuranceBalance}</p>
          <p className="text-3xl font-black text-white">${insuranceBalanceValue.toLocaleString()}</p>

          <div className="flex space-x-2 mt-4">
            <button 
              onClick={() => handleOpenModal('RECHARGE')}
              className="flex-1 flex items-center justify-center space-x-2 bg-amber-500/10 hover:bg-amber-500/20 text-amber-500 py-2 rounded-xl text-xs font-bold transition-all border border-amber-500/20"
            >
              <PlusCircle className="w-3.5 h-3.5" />
              <span>{t.risk.recharge}</span>
            </button>
            <button 
              onClick={() => handleOpenModal('WITHDRAW')}
              className="flex-1 flex items-center justify-center space-x-2 bg-gray-800 hover:bg-gray-700 text-gray-300 py-2 rounded-xl text-xs font-bold transition-all border border-gray-700"
            >
              <MinusCircle className="w-3.5 h-3.5" />
              <span>{t.risk.withdraw}</span>
            </button>
          </div>
        </div>

        {[
          { label: t.risk.insuranceUsage, value: globalInsurance.usageRate, icon: Activity, color: 'text-blue-500' },
          { label: t.risk.insurancePaid, value: globalInsurance.totalPaid, icon: ShieldAlert, color: 'text-amber-500' }
        ].map((item, idx) => (
          <div key={idx} className="bg-gradient-to-br from-gray-900/80 to-gray-900/40 border border-gray-800 p-6 rounded-2xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
              <item.icon className={`w-12 h-12 ${item.color}`} />
            </div>
            <p className="text-xs text-gray-500 uppercase font-black tracking-widest mb-2">{item.label}</p>
            <p className={`text-3xl font-black text-white`}>{item.value}</p>
          </div>
        ))}
      </div>

      {/* Recharge / Withdraw Modal */}
      {opModal.type && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setOpModal({ type: null })} />
          <div className="relative w-full max-w-md bg-gray-900 border border-gray-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-6">
              {opModal.type === 'RECHARGE' ? t.risk.modals.rechargeTitle : t.risk.modals.withdrawTitle}
            </h3>

            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.risk.modals.chain}</label>
                <div className="relative">
                  <Globe className="absolute left-3 top-2.5 h-4 w-4 text-amber-500" />
                  <select className="w-full bg-gray-800 border border-gray-700 rounded-xl py-2.5 pl-10 pr-4 text-sm outline-none appearance-none text-gray-300">
                    <option>Arbitrum</option>
                    <option>Ethereum</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.risk.modals.token}</label>
                <div className="relative">
                  <Coins className="absolute left-3 top-2.5 h-4 w-4 text-amber-500" />
                  <select className="w-full bg-gray-800 border border-gray-700 rounded-xl py-2.5 pl-10 pr-4 text-sm outline-none appearance-none text-gray-300">
                    <option>USDC</option>
                    <option>USDT</option>
                  </select>
                </div>
              </div>

              <div>
                <div className="flex justify-between mb-1.5 px-1">
                   <label className="text-xs font-bold text-gray-500 uppercase">{t.common.amount}</label>
                   <span className="text-[10px] font-bold text-gray-600 uppercase">
                     {opModal.type === 'RECHARGE' ? t.risk.modals.walletBalance : t.risk.modals.fundBalance}: 
                     <span className="text-amber-500 ml-1">
                       {opModal.type === 'RECHARGE' ? walletBalance.toLocaleString() : insuranceBalanceValue.toLocaleString()} USDC
                     </span>
                   </span>
                </div>
                <div className="relative">
                   <input 
                      type="text" 
                      value={amount}
                      onChange={e => {
                        setAmount(e.target.value);
                        if (error && e.target.value.trim()) setError(false);
                      }}
                      placeholder="0.00"
                      className={`w-full bg-gray-800 border ${error ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl py-2.5 px-4 text-sm font-bold text-white outline-none focus:border-amber-500 transition-all`}
                   />
                   <button 
                    onClick={() => setAmount(opModal.type === 'RECHARGE' ? walletBalance.toString() : insuranceBalanceValue.toString())}
                    className="absolute right-3 top-2.5 text-[10px] font-black text-amber-500 hover:text-amber-400 uppercase tracking-widest"
                   >
                     Max
                   </button>
                </div>
              </div>

              {opModal.type === 'WITHDRAW' && (
                <div className="mt-4 p-4 bg-gray-800/40 border border-gray-800 rounded-2xl space-y-3">
                  <div className="flex justify-between items-center text-[10px] font-black uppercase text-gray-500 tracking-widest">
                    <span>{t.contract.modals.pendingSigs}</span>
                    <span className="text-amber-500">{sigCount} / 2</span>
                  </div>
                  <div className="flex space-x-2">
                    {[1, 2].map(n => (
                      <div key={n} className={`h-1.5 flex-1 rounded-full transition-all duration-700 ${sigCount >= n ? 'bg-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.5)]' : 'bg-gray-700'}`} />
                    ))}
                  </div>
                  <p className="text-[10px] text-gray-500 italic">{t.risk.modals.multiSigInfo}</p>
                </div>
              )}
            </div>

            <div className="flex space-x-3 mt-8">
              <button 
                onClick={() => setOpModal({ type: null })}
                className="flex-1 px-4 py-3 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm font-bold text-gray-300 transition-all"
                disabled={isSigning}
              >
                {t.common.cancel}
              </button>

              {opModal.type === 'RECHARGE' ? (
                <button 
                  onClick={handleSign}
                  disabled={isSigning}
                  className={`flex-1 px-4 py-3 rounded-xl text-sm font-bold text-white transition-all shadow-lg flex items-center justify-center ${isSigning ? 'bg-gray-700 cursor-not-allowed' : 'bg-amber-500 hover:bg-amber-600 shadow-amber-900/20'}`}
                >
                  {isSigning ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin mr-2" />
                      <span>{t.login.connecting}</span>
                    </>
                  ) : (
                    <>
                      <Shield className="w-4 h-4 mr-2" />
                      <span>{t.common.confirm}</span>
                    </>
                  )}
                </button>
              ) : (
                <div className="flex flex-1 space-x-2">
                   <button 
                    onClick={handleSign}
                    disabled={isSigning || sigCount >= 2}
                    className={`w-full px-4 py-3 rounded-xl text-sm font-bold text-white transition-all shadow-lg flex items-center justify-center ${isSigning || sigCount >= 2 ? 'bg-gray-800 text-gray-500 cursor-default' : 'bg-blue-600 hover:bg-blue-500 shadow-blue-900/20'}`}
                  >
                    {isSigning ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Shield className="w-4 h-4 mr-2" />}
                    <span>{sigCount === 1 ? t.common.confirm : t.contract.modals.sign}</span>
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Contract Specific Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {[
          { label: t.risk.avgMr, value: '34.2%', sub: t.risk.healthy, color: 'text-amber-500' },
          { label: t.risk.pendingLiq, value: '3', sub: `$12,500 ${t.risk.value}`, color: 'text-red-500' },
          { label: t.risk.inLiq, value: '1', sub: `$42,000 ${t.risk.value}`, color: 'text-orange-500' },
          { label: t.risk.liquidated, value: '142', sub: `$1.2M ${t.risk.value}`, color: 'text-blue-500' }
        ].map((stat, idx) => (
          <div key={idx} className="bg-gray-900/60 border border-gray-800 p-6 rounded-2xl hover:border-gray-700 transition-all">
            <p className="text-xs text-gray-500 uppercase font-bold mb-2">{stat.label}</p>
            <p className={`text-3xl font-black ${stat.color}`}>{stat.value}</p>
            <p className="text-[10px] text-gray-400 mt-2 font-bold uppercase tracking-tight opacity-70">{stat.sub}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Margin Rate Grading Curve */}
        <div className="bg-gray-900/40 border border-gray-800 rounded-3xl p-6">
          <h3 className="text-lg font-bold text-gray-300 mb-6 flex items-center">
            <TrendingDown className="w-5 h-5 mr-2 text-blue-500" />
            {t.risk.curveTitle}
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={marginCurveData}>
                <defs>
                  <linearGradient id="colorMR" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" vertical={false} />
                <XAxis 
                  dataKey="size" 
                  axisLine={false} 
                  tick={{fill: '#9ca3af', fontSize: 10}} 
                  unit=" USDC" 
                  name={t.risk.nominalValue}
                />
                <YAxis 
                  axisLine={false} 
                  tick={{fill: '#9ca3af', fontSize: 10}} 
                  tickFormatter={(val) => `${val}%`}
                />
                <Tooltip 
                  labelFormatter={(val) => `${t.risk.nominalValue}: ${val} USDC`}
                  formatter={(value: number) => [`${value}%`, 'MR']}
                  contentStyle={{ backgroundColor: '#111827', border: 'none', borderRadius: '12px', fontSize: '12px', color: '#fff' }}
                  itemStyle={{ color: '#fff' }}
                />
                <Area type="monotone" dataKey="MR" stroke="#3b82f6" fillOpacity={1} fill="url(#colorMR)" strokeWidth={3} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
          <p className="text-xs text-gray-500 mt-4 text-center italic font-medium">{t.risk.curveDesc}</p>
        </div>

        {/* Liquidation Timeline */}
        <div className="bg-gray-900/40 border border-gray-800 rounded-3xl p-6">
          <h3 className="text-lg font-bold text-gray-300 mb-6 flex items-center">
            <Clock className="w-5 h-5 mr-2 text-amber-500" />
            {t.risk.timelineTitle}
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={timelineData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" vertical={false} />
                <XAxis dataKey="time" axisLine={false} tick={{fill: '#9ca3af', fontSize: 10}} />
                <YAxis axisLine={false} tick={{fill: '#9ca3af', fontSize: 10}} tickFormatter={(val) => `$${val}`} />
                <Tooltip 
                  formatter={(value: number) => [`$${value.toLocaleString()} USDC`, t.risk.liqValue]}
                  contentStyle={{ backgroundColor: '#111827', border: 'none', borderRadius: '12px', fontSize: '12px', color: '#fff' }}
                  itemStyle={{ color: '#fff' }}
                />
                <Line type="monotone" dataKey="amount" stroke="#f59e0b" strokeWidth={3} dot={{fill: '#f59e0b', r: 4}} activeDot={{ r: 6 }} />
              </LineChart>
            </ResponsiveContainer>
          </div>
          <p className="text-xs text-gray-500 mt-4 text-center italic font-medium">{t.risk.timelineDesc}</p>
        </div>

        {/* Liquidation Distribution Scatter */}
        <div className="bg-gray-900/40 border border-gray-800 rounded-3xl p-6 lg:col-span-2">
          <h3 className="text-lg font-bold text-gray-300 mb-6 flex items-center">
            <Target className="w-5 h-5 mr-2 text-red-500" />
            {t.risk.scatterTitle}
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" vertical={false} />
                <XAxis type="number" dataKey="leverage" name={t.market.leverage} unit="x" axisLine={false} tick={{fill: '#9ca3af', fontSize: 10}} domain={[0, 150]} />
                <YAxis type="number" dataKey="price" name={t.market.liqPrice} axisLine={false} tick={{fill: '#9ca3af', fontSize: 10}} domain={['dataMin - 10', 'dataMax + 10']} />
                <ZAxis type="number" dataKey="amount" range={[100, 1000]} />
                <Tooltip 
                  cursor={{ strokeDasharray: '3 3' }} 
                  formatter={(value: any, name: string) => {
                    if (name === t.market.liqPrice) return [`$${value.toLocaleString()} USDC`, name];
                    if (name === 'amount' || name === t.common.amount) return [`$${value.toLocaleString()} USDC`, t.common.amount];
                    if (name === t.market.leverage) return [`${value}x`, name];
                    return [value, name];
                  }}
                  contentStyle={{ backgroundColor: '#111827', border: 'none', borderRadius: '12px', fontSize: '12px', color: '#fff' }}
                  itemStyle={{ color: '#fff' }}
                  labelStyle={{ color: '#fff' }}
                />
                <Scatter name="Liquidations" data={scatterData} fill="#ef4444" fillOpacity={0.5} />
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="text-xs text-gray-500 mt-4 text-center italic font-medium">{t.risk.scatterDesc}</p>
        </div>
      </div>
    </div>
  );
};

export default RiskCenter;

import React, { useState, useMemo } from 'react';
import { UserPlus, Shield, Trash2, Edit2, ShieldAlert, Plus, X, Check, ListChecks, ShieldCheck } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface Role {
  id: string;
  name: string;
  isSuper?: boolean;
  permissions: string[];
}

interface Admin {
  id: string;
  name: string;
  wallet: string;
  roleId: string;
}

const AdminSettings: React.FC = () => {
  const { t } = useLanguage();

  const [roles, setRoles] = useState<Role[]>([
    { id: 'role-1', name: t.admin.roles.super, isSuper: true, permissions: ['*'] },
    { id: 'role-2', name: t.admin.roles.risk, permissions: ['/dashboard', '/market', '/risk', '/health'] },
    { id: 'role-3', name: t.admin.roles.finance, permissions: ['/funds', '/logs'] },
  ]);

  const [admins, setAdmins] = useState<Admin[]>([
    { id: '1', name: 'Root Admin', wallet: '0x71C7...d8976F', roleId: 'role-1' },
    { id: '2', name: 'Risk Lead A', wallet: '0xRisk...1111', roleId: 'role-2' },
    { id: '3', name: 'Finance Lead', wallet: '0xFin...2222', roleId: 'role-3' },
  ]);

  const [adminModal, setAdminModal] = useState<{ open: boolean, editId?: string, isSubmitted?: boolean }>({ open: false });
  const [roleModal, setRoleModal] = useState<{ open: boolean, editId?: string, isSubmitted?: boolean }>({ open: false });

  const [adminForm, setAdminForm] = useState({ name: '', wallet: '', roleId: 'role-2' });
  const [roleForm, setRoleForm] = useState<{ name: string, permissions: string[] }>({ name: '', permissions: [] });

  // Inline Validation Logic (used on button click)
  const validateAdminForm = () => {
    return adminForm.name.trim() !== '' && adminForm.wallet.trim() !== '';
  };

  const validateRoleForm = () => {
    return roleForm.name.trim() !== '' && roleForm.permissions.length > 0;
  };

  const allPerms = [
    { path: '/dashboard', label: t.nav.dashboard },
    { path: '/admin', label: t.nav.admin },
    { path: '/market', label: t.nav.market },
    { path: '/risk', label: t.nav.risk },
    { path: '/health', label: t.nav.health },
    { path: '/alerts', label: t.nav.alerts },
    { path: '/users', label: t.nav.users },
    { path: '/funds', label: t.nav.funds },
    { path: '/logs', label: t.nav.logs },
    { path: '/contracts', label: t.nav.contractManager },
    { path: '/settings', label: t.nav.params },
  ];

  const openAdminModal = (editId?: string) => {
    if (editId) {
      const admin = admins.find(a => a.id === editId);
      if (admin) setAdminForm({ name: admin.name, wallet: admin.wallet, roleId: admin.roleId });
    } else {
      setAdminForm({ name: '', wallet: '', roleId: roles[1]?.id || 'role-2' });
    }
    setAdminModal({ open: true, editId, isSubmitted: false });
  };

  const handleAdminSubmit = () => {
    setAdminModal(prev => ({ ...prev, isSubmitted: true }));
    if (!validateAdminForm()) return;

    if (adminModal.editId) {
      setAdmins(admins.map(a => a.id === adminModal.editId ? { ...a, ...adminForm } : a));
    } else {
      setAdmins([...admins, { id: Math.random().toString(36).substr(2, 9), ...adminForm }]);
    }
    setAdminModal({ open: false });
  };

  const deleteAdmin = (id: string) => {
    setAdmins(admins.filter(a => a.id !== id));
  };

  const openRoleModal = (editId?: string) => {
    if (editId) {
      const role = roles.find(r => r.id === editId);
      if (role) setRoleForm({ name: role.name, permissions: role.permissions });
    } else {
      setRoleForm({ name: '', permissions: [] });
    }
    setRoleModal({ open: true, editId, isSubmitted: false });
  };

  const handleRoleSubmit = () => {
    setRoleModal(prev => ({ ...prev, isSubmitted: true }));
    if (!validateRoleForm()) return;

    if (roleModal.editId) {
      setRoles(roles.map(r => r.id === roleModal.editId ? { ...r, ...roleForm } : r));
    } else {
      setRoles([...roles, { id: Math.random().toString(36).substr(2, 9), ...roleForm }]);
    }
    setRoleModal({ open: false });
  };

  const deleteRole = (id: string) => {
    setRoles(roles.filter(r => r.id !== id));
  };

  const togglePermission = (path: string) => {
    setRoleForm(prev => ({
      ...prev,
      permissions: prev.permissions.includes(path) 
        ? prev.permissions.filter(p => p !== path) 
        : [...prev.permissions, path]
    }));
  };

  const toggleAllPermissions = () => {
    if (roleForm.permissions.length === allPerms.length) {
      setRoleForm(prev => ({ ...prev, permissions: [] }));
    } else {
      setRoleForm(prev => ({ ...prev, permissions: allPerms.map(p => p.path) }));
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center">
            <ShieldCheck className="w-6 h-6 mr-3 text-amber-500" />
            {t.admin.title}
          </h1>
          <p className="text-gray-400">{t.admin.subtitle}</p>
        </div>
        <div className="flex space-x-3">
          <button 
            onClick={() => openRoleModal()}
            className="flex items-center space-x-2 bg-gray-800 hover:bg-gray-700 px-4 py-2 rounded-lg text-white font-semibold transition-all"
          >
            <Shield className="w-4 h-4 text-amber-500" />
            <span>{t.admin.addRoleBtn}</span>
          </button>
          <button 
            onClick={() => openAdminModal()}
            className="flex items-center space-x-2 bg-amber-500 hover:bg-amber-600 px-4 py-2 rounded-lg text-white font-semibold transition-all shadow-lg shadow-amber-900/20"
          >
            <UserPlus className="w-4 h-4" />
            <span>{t.admin.addBtn}</span>
          </button>
        </div>
      </div>

      <div className="bg-blue-900/10 border border-blue-900/30 p-4 rounded-xl flex items-start space-x-3">
        <ShieldAlert className="w-5 h-5 text-blue-500 flex-shrink-0 mt-0.5" />
        <div className="text-sm text-blue-400">
          <p className="font-semibold mb-1">{t.admin.policyNote}</p>
          <p>{t.admin.policyDesc}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.activeAdmins}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-800 text-gray-400 text-xs uppercase font-bold">
                <tr>
                  <th className="px-6 py-4">{t.admin.headers.nameId}</th>
                  <th className="px-6 py-4">{t.admin.headers.wallet}</th>
                  <th className="px-6 py-4">{t.admin.headers.role}</th>
                  <th className="px-6 py-4">{t.common.action}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800">
                {admins.map((admin) => {
                  const role = roles.find(r => r.id === admin.roleId);
                  return (
                    <tr key={admin.id} className="hover:bg-gray-800/20 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-medium text-white">{admin.name}</div>
                        <div className="text-xs text-gray-500">UID: {admin.id}</div>
                      </td>
                      <td className="px-6 py-4 font-mono text-xs text-amber-500">{admin.wallet}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded text-[10px] font-bold ${role?.isSuper ? 'bg-purple-500/20 text-purple-500' : 'bg-blue-500/20 text-blue-500'}`}>
                          {role?.name || t.common.none}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {!role?.isSuper && (
                          <div className="flex space-x-3">
                            <button 
                              onClick={() => openAdminModal(admin.id)}
                              className="text-gray-400 hover:text-amber-500 transition-colors"
                            >
                              <Edit2 className="w-4 h-4" />
                            </button>
                            <button 
                              onClick={() => deleteAdmin(admin.id)}
                              className="text-gray-400 hover:text-red-500 transition-colors"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.roleDefs}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl p-6 space-y-4">
            {roles.map(role => (
              <div 
                key={role.id} 
                className="p-4 bg-gray-800/40 rounded-xl border border-gray-800 hover:border-amber-500/50 transition-all relative group"
              >
