          <div className="flex items-center space-x-2">
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">{t.users.regTime}:</span>
            <input 
              type="date" 
              className="bg-transparent text-xs text-gray-300 outline-none [color-scheme:dark] cursor-pointer"
              value={dateRange.start}
              onChange={(e) => setDateRange({...dateRange, start: e.target.value})}
            />
            <span className="text-gray-700">-</span>
            <input 
              type="date" 
              className="bg-transparent text-xs text-gray-300 outline-none [color-scheme:dark] cursor-pointer"
              value={dateRange.end}
              onChange={(e) => setDateRange({...dateRange, end: e.target.value})}
            />
          </div>
        </div>

        <select 
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="bg-gray-900 border border-gray-800 rounded-lg py-2 px-4 text-sm focus:border-amber-500 outline-none text-gray-400 font-bold cursor-pointer"
        >
          <option value="ALL">{t.common.status}: {t.common.all}</option>
          <option value="ACTIVE">{t.users.statusActive}</option>
          <option value="FROZEN">{t.users.statusFrozen}</option>
        </select>
      </div>

      <div className="bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden shadow-2xl">
        <table className="w-full text-left">
          <thead className="bg-gray-800/50 text-gray-400 text-[10px] font-black uppercase tracking-widest">
            <tr>
              <th className="px-6 py-4">{t.users.identity}</th>
              <th className="px-6 py-4">{t.users.assets}</th>
              <th className="px-6 py-4">{t.users.regTime}</th>
              <th className="px-6 py-4">{t.users.lastLoginTime}</th>
              <th className="px-6 py-4">{t.users.lastLogin}</th>
              <th className="px-6 py-4">{t.users.security}</th>
              <th className="px-6 py-4">{t.common.action}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-800/50">
            {filteredUsers.map((user) => (
              <tr key={user.uid} className="hover:bg-amber-500/[0.01] transition-all group">
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <div className="text-sm font-bold text-white flex items-center group-hover:text-amber-500 transition-colors">
                      {user.wallet}
                      <ExternalLink className="w-3 h-3 ml-2 text-gray-600 cursor-pointer hover:text-amber-500" />
                    </div>
                    <div className="flex items-center text-[10px] text-gray-500 mt-1 font-bold">
                      <span className="mr-3 uppercase tracking-tighter">UID: {user.uid}</span>
                      <span className="flex items-center"><Mail className="w-3 h-3 mr-1 opacity-50" /> {user.email}</span>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="text-sm font-black text-amber-500">${user.balance.toLocaleString()}</div>
                </td>
                <td className="px-6 py-4">
                  <div className="text-xs text-gray-400 font-mono font-bold tracking-tight">{user.registeredAt}</div>
                </td>
                <td className="px-6 py-4">
                  <div className="text-xs text-gray-400 font-mono font-bold tracking-tight">{user.lastLoginAt}</div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center text-xs text-gray-500 font-mono font-bold">
                    <Globe className="w-3 h-3 mr-1.5 text-blue-500/50" />
                    {user.lastIp}
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center space-x-1.5">
                    <span className={`px-2.5 py-1 rounded text-[10px] font-black uppercase tracking-widest ${user.isFrozen ? 'bg-red-500/10 text-red-500 ring-1 ring-red-500/20' : 'bg-green-500/10 text-green-500 ring-1 ring-green-500/20'}`}>
                      {user.isFrozen ? t.users.statusFrozen : t.users.verified}
                    </span>
                    {user.lastActionReason && (
                      <div className="relative group/tooltip">
                        <HelpCircle className="w-4 h-4 text-gray-600 cursor-help hover:text-amber-500 transition-colors" />
                        {/* Tooltip Content */}
                        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 hidden group-hover/tooltip:block z-50 transition-all">
                           <div className="bg-gray-800 text-white text-[10px] font-bold py-2 px-3 rounded-xl shadow-2xl border border-gray-700 whitespace-nowrap">
                             <div className="flex flex-col">
                               <span className="text-gray-500 uppercase text-[8px] mb-0.5">{t.users.lastReason}</span>
                               <span>{user.lastActionReason}</span>
                             </div>
                             {/* Tooltip Arrow */}
                             <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-gray-800" />
                           </div>
                        </div>
                      </div>
                    )}
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end space-x-2">
                    {user.isFrozen ? (
                      <button 
                        onClick={() => setConfirmModal({ uid: user.uid, wallet: user.wallet, action: 'unfreeze' })}
                        className="p-2 text-green-500 hover:bg-green-500/10 rounded-xl transition-all border border-transparent hover:border-green-500/30" 
                        title="Unfreeze"
                      >
                        <ShieldCheck className="w-4 h-4" />
                      </button>
                    ) : (
                      <button 
                        onClick={() => setConfirmModal({ uid: user.uid, wallet: user.wallet, action: 'freeze' })}
                        className="p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition-all border border-transparent hover:border-red-500/30" 
                        title="Freeze User"
                      >
                        <UserX className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {confirmModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={closeModal} />
          <div className="relative w-full max-w-sm bg-gray-900 border border-gray-800 rounded-[32px] shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <div className="flex flex-col items-center text-center space-y-4">
              <div className={`p-4 rounded-3xl ${confirmModal.action === 'freeze' ? 'bg-red-500/10 text-red-500' : 'bg-green-500/10 text-green-500'}`}>
                 <AlertTriangle className="w-10 h-10" />
              </div>
              <div className="space-y-2 w-full">
                <h3 className="text-xl font-bold text-white">
                  {confirmModal.action === 'freeze' ? t.users.freezeTitle : t.users.unfreezeTitle}
                </h3>
                <p className="text-sm text-gray-400">
                  {confirmModal.action === 'freeze' 
                    ? t.users.freezeDesc.replace('{uid}', confirmModal.uid) 
                    : t.users.unfreezeDesc.replace('{uid}', confirmModal.uid)}
                </p>

                <div className="mt-6 text-left space-y-2">
                   <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest px-1">
                     {t.users.reasonLabel} <span className="text-red-500">*</span>
                   </label>
                   <textarea 
                     value={reason}
                     onChange={(e) => setReason(e.target.value)}
                     placeholder={t.users.reasonPlaceholder}
                     className={`w-full bg-gray-950 border ${isSubmitted && !reason.trim() ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-800'} rounded-2xl px-4 py-3 text-sm text-white outline-none focus:border-amber-500/50 transition-all resize-none h-24`}
                   />
                </div>
              </div>
            </div>
            <div className="flex space-x-3 mt-8">
              <button 
                onClick={closeModal}
                className="flex-1 px-4 py-3 bg-gray-800/60 hover:bg-gray-700/60 rounded-2xl text-sm font-bold text-gray-300 transition-all border border-gray-700"
              >
                {t.common.cancel}
              </button>
              <button 
                onClick={handleAction}
                className={`flex-1 px-4 py-3 rounded-2xl text-sm font-bold text-white transition-all shadow-lg ${
                  confirmModal.action === 'freeze' 
                    ? 'bg-red-500 hover:bg-red-600 shadow-red-900/20' 
                    : 'bg-green-500 hover:bg-green-600 shadow-green-900/20'
                }`}
              >
                {t.common.confirm}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserManagement;

import React, { useState, useMemo } from 'react';
import { 
  ShieldCheck, 
  Settings, 
  AlertTriangle, 
  ToggleLeft, 
  ToggleRight, 
  Save, 
  Loader2, 
  CheckCircle,
  Database,
  Globe,
  Coins,
  Percent,
  Clock,
  ArrowRightLeft,
  Users,
  RotateCcw
} from 'lucide-react';
import { useLanguage } from '../LanguageContext';

type TabType = 'ON_CHAIN' | 'OFF_CHAIN';

interface OnChainParams {
  vaultDepositArb: boolean;
  vaultWithdrawArb: boolean;
  liqPenaltyRatio: string;
  insFundSplit: string;
  keeperSplit: string;
}

interface OffChainParams {
  globalTrading: boolean;
  regSwitch: boolean;
  mmrRatio: string;
  fundingCap: string;
  maxUserPos: string;
  makerFee: string;
  takerFee: string;
  interestRate: string;
  fundingFreq: string;
  orderFreqLimit: string;
}

const ON_CHAIN_DEFAULTS: OnChainParams = {
  vaultDepositArb: true,
  vaultWithdrawArb: true,
  liqPenaltyRatio: '10',
  insFundSplit: '50',
  keeperSplit: '50',
};

const OFF_CHAIN_DEFAULTS: OffChainParams = {
  globalTrading: true,
  regSwitch: true,
  mmrRatio: '50',
  fundingCap: '0.05',
  maxUserPos: '200',
  makerFee: '0.010',
  takerFee: '0.035',
  interestRate: '0.01',
  fundingFreq: '1',
  orderFreqLimit: '1000',
};

const ContractSettings: React.FC = () => {
  const { t } = useLanguage();
  const [activeTab, setActiveTab] = useState<TabType>('ON_CHAIN');

  // Multi-sig states
  const [onChainSigs, setOnChainSigs] = useState(0);
  const [offChainSigs, setOffChainSigs] = useState(0);
  const [isSigning, setIsSigning] = useState(false);

  // Form states
  const [onChainForm, setOnChainForm] = useState<OnChainParams>(ON_CHAIN_DEFAULTS);
  const [offChainForm, setOffChainForm] = useState<OffChainParams>(OFF_CHAIN_DEFAULTS);

  const isOnChainValid = useMemo(() => {
    return Object.values(onChainForm).every(val => val.toString().trim() !== '');
  }, [onChainForm]);

  const isOffChainValid = useMemo(() => {
    return Object.values(offChainForm).every(val => val.toString().trim() !== '');
  }, [offChainForm]);

  const handleSign = () => {
    const isValid = activeTab === 'ON_CHAIN' ? isOnChainValid : isOffChainValid;
    if (!isValid) return;

    setIsSigning(true);
    setTimeout(() => {
      if (activeTab === 'ON_CHAIN') {
        const nextSigs = onChainSigs + 1;
        if (nextSigs >= 2) {
          // Requirement: On-chain completion instantly on 2nd signature
          alert(t.common.confirm + " OK");
          setOnChainSigs(0);
        } else {
          setOnChainSigs(nextSigs);
        }
      } else {
        setOffChainSigs(prev => Math.min(prev + 1, 2));
      }
      setIsSigning(false);
    }, 1200);
  };

  const handleExecute = () => {
    alert("Applying off-chain parameters...");
    setOffChainSigs(0);
  };

  const handleResetProgress = () => {
    if (activeTab === 'ON_CHAIN') setOnChainSigs(0);
    else setOffChainSigs(0);
  };

  const handleRestoreDefaults = () => {
    if (activeTab === 'ON_CHAIN') {
      setOnChainForm(ON_CHAIN_DEFAULTS);
      setOnChainSigs(0);
    } else {
      setOffChainForm(OFF_CHAIN_DEFAULTS);
      setOffChainSigs(0);
    }
  };

  const Switch = ({ active, onClick, label, disabled }: { active: boolean, onClick: () => void, label: string, disabled?: boolean }) => (
    <div className={`flex items-center justify-between p-4 bg-gray-900/60 border border-gray-800 rounded-xl transition-all ${disabled ? 'opacity-50' : 'hover:border-amber-500/30'}`}>
      <span className="text-sm font-bold text-gray-400 uppercase tracking-tight">{label}</span>
      <button onClick={onClick} disabled={disabled} className="focus:outline-none">
        {active 
          ? <ToggleRight className="w-10 h-10 text-amber-500" /> 
          : <ToggleLeft className="w-10 h-10 text-gray-600" />
        }
      </button>
    </div>
  );

  const InputField = ({ label, value, onChange, unit, desc, disabled }: { label: string, value: string, onChange: (v: string) => void, unit?: string, desc?: string, disabled?: boolean }) => {
    const isEmpty = value.toString().trim() === '';
    return (
      <div className={`space-y-1.5 p-4 bg-gray-900/40 border ${isEmpty ? 'border-red-500/50 shadow-[0_0_8px_rgba(239,68,68,0.15)]' : 'border-gray-800'} rounded-xl group transition-all ${disabled ? 'opacity-50' : 'hover:border-blue-500/30'}`}>
        <div className="flex justify-between items-center">
          <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{label}</label>
          {unit && <span className="text-[9px] font-bold text-gray-600 uppercase">{unit}</span>}
        </div>
        <input 
          type="text" 
          value={value}
          disabled={disabled}
          onChange={(e) => onChange(e.target.value)}
          className={`w-full bg-gray-950 border ${isEmpty ? 'border-red-500' : 'border-gray-800'} rounded-lg px-3 py-2 text-sm font-bold text-white outline-none focus:border-amber-500 transition-all`}
        />
        {desc && <p className="text-[9px] text-gray-600 leading-tight italic">{desc}</p>}
      </div>
    );
  };

  const curSigs = activeTab === 'ON_CHAIN' ? onChainSigs : offChainSigs;
  const isCurrentFormValid = activeTab === 'ON_CHAIN' ? isOnChainValid : isOffChainValid;

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Header Area */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h1 className="text-3xl font-black text-white flex items-center">
            <Settings className="w-8 h-8 mr-3 text-amber-500" />
            {t.params.title}
          </h1>
          <p className="text-gray-400 mt-1">{t.params.subtitle}</p>
        </div>

        <div className="flex bg-gray-900 border border-gray-800 p-1.5 rounded-2xl shadow-inner">
          <button 
            onClick={() => setActiveTab('ON_CHAIN')}
            className={`flex items-center px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'ON_CHAIN' ? 'bg-amber-500 text-white shadow-lg shadow-amber-900/40' : 'text-gray-500 hover:text-gray-300'}`}
          >
            <Database className="w-3.5 h-3.5 mr-2" />
            {t.params.onChainTab}
          </button>
          <button 
            onClick={() => setActiveTab('OFF_CHAIN')}
            className={`flex items-center px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'OFF_CHAIN' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'text-gray-500 hover:text-gray-300'}`}
          >
            <Globe className="w-3.5 h-3.5 mr-2" />
            {t.params.offChainTab}
          </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-4 items-stretch">
        <div className="flex-1 bg-red-900/10 border border-red-900/30 p-5 rounded-3xl flex items-start space-x-4 shadow-sm">
          <AlertTriangle className="w-6 h-6 text-red-500 flex-shrink-0 mt-0.5" />
          <div className="text-sm">
            <p className="font-black text-red-500 uppercase tracking-tight mb-1">{t.params.warningTitle}</p>
            <p className="text-red-400/80 leading-relaxed">{t.params.warningDesc}</p>
          </div>
        </div>
        <button 
          onClick={handleRestoreDefaults}
          className="lg:w-48 flex flex-col items-center justify-center p-5 bg-gray-900 border border-gray-800 hover:border-amber-500/50 rounded-3xl group transition-all"
        >
          <RotateCcw className="w-6 h-6 text-gray-500 group-hover:text-amber-500 mb-2 transition-colors" />
          <span className="text-[10px] font-black uppercase text-gray-500 group-hover:text-white tracking-widest">{t.params.restoreDefaults}</span>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Configuration Forms */}
        <div className="lg:col-span-2 space-y-8">
          {activeTab === 'ON_CHAIN' ? (
            <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-4">
                  <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                    <ArrowRightLeft className="w-4 h-4 mr-2 text-amber-500" />
                    {t.params.switches}
                  </h3>
                  <Switch 
                    label={t.params.labels.vaultDeposit} 
                    active={onChainForm.vaultDepositArb} 
                    onClick={() => setOnChainForm({...onChainForm, vaultDepositArb: !onChainForm.vaultDepositArb})} 
                    disabled={curSigs > 0}
                  />
                  <Switch 
                    label={t.params.labels.vaultWithdraw} 
                    active={onChainForm.vaultWithdrawArb} 
                    onClick={() => setOnChainForm({...onChainForm, vaultWithdrawArb: !onChainForm.vaultWithdrawArb})}
                    disabled={curSigs > 0}
                  />
                </div>
                <div className="space-y-4">
                  <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                    <Coins className="w-4 h-4 mr-2 text-amber-500" />
                    {t.params.fees}
                  </h3>
                  <InputField 
                    label={t.params.labels.liqPenalty} 
                    unit="%"
                    value={onChainForm.liqPenaltyRatio} 
                    onChange={(v) => setOnChainForm({...onChainForm, liqPenaltyRatio: v})}
                    disabled={curSigs > 0}
                  />
                  <div className="grid grid-cols-2 gap-3">
                    <InputField 
                      label={t.params.labels.insSplit} 
                      unit="%"
                      value={onChainForm.insFundSplit} 
                      onChange={(v) => setOnChainForm({...onChainForm, insFundSplit: v})}
                      disabled={curSigs > 0}
                    />
                    <InputField 
                      label={t.params.labels.keeperSplit} 
                      unit="%"
                      value={onChainForm.keeperSplit} 
                      onChange={(v) => setOnChainForm({...onChainForm, keeperSplit: v})}
                      disabled={curSigs > 0}
                    />
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-4">
                    <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                      <ArrowRightLeft className="w-4 h-4 mr-2 text-blue-500" />
                      {t.params.switches}
                    </h3>
                    <Switch 
                      label={t.params.labels.trading} 
                      active={offChainForm.globalTrading} 
                      onClick={() => setOffChainForm({...offChainForm, globalTrading: !offChainForm.globalTrading})}
                      disabled={curSigs > 0}
                    />
                    <Switch 
                      label={t.params.labels.reg} 
                      active={offChainForm.regSwitch} 
                      onClick={() => setOffChainForm({...offChainForm, regSwitch: !offChainForm.regSwitch})}
                      disabled={curSigs > 0}
                    />
                  </div>
                  <div className="space-y-4">
                    <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                      <Percent className="w-4 h-4 mr-2 text-blue-500" />
                      {t.params.constants}
                    </h3>
                    <InputField 
                      label={t.params.labels.mmr} 
                      unit="% of IMR"
                      value={offChainForm.mmrRatio} 
                      onChange={(v) => setOffChainForm({...offChainForm, mmrRatio: v})}
                      disabled={curSigs > 0}
                    />
                    <InputField 
                      label={t.params.labels.fundingCap} 
                      unit="%"
                      value={offChainForm.fundingCap} 
                      onChange={(v) => setOffChainForm({...offChainForm, fundingCap: v})}
                      disabled={curSigs > 0}
                    />
                  </div>
               </div>

               <div className="space-y-4">
                 <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                    <Users className="w-4 h-4 mr-2 text-blue-500" />
                    {t.params.tradingParams}
                 </h3>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <InputField label={t.params.labels.maxUserPos} unit="M USDC" value={offChainForm.maxUserPos} onChange={(v) => setOffChainForm({...offChainForm, maxUserPos: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.makerFee} unit="%" value={offChainForm.makerFee} onChange={(v) => setOffChainForm({...offChainForm, makerFee: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.takerFee} unit="%" value={offChainForm.takerFee} onChange={(v) => setOffChainForm({...offChainForm, takerFee: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.interestRate} unit="%/H" value={offChainForm.interestRate} onChange={(v) => setOffChainForm({...offChainForm, interestRate: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.settleFreq} unit="H" value={offChainForm.fundingFreq} onChange={(v) => setOffChainForm({...offChainForm, fundingFreq: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.orderFreq} unit="笔/秒/IP" value={offChainForm.orderFreqLimit} onChange={(v) => setOffChainForm({...offChainForm, orderFreqLimit: v})} disabled={curSigs > 0} />
                 </div>
               </div>
            </div>
          )}
        </div>

        {/* Multi-sig Panel */}
        <div className="lg:col-span-1">
          <div className="bg-gray-900 border border-gray-800 rounded-[32px] p-8 sticky top-24 shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-lg font-bold text-white flex items-center">
                <ShieldCheck className="w-5 h-5 mr-2 text-amber-500" />
                {t.params.govStatus}
              </h2>
              {/* Requirement: Allow resetting signature progress */}
              {curSigs > 0 && (
                <button 
                  onClick={handleResetProgress}
                  className="text-gray-500 hover:text-amber-500 transition-colors p-1"
                  title="Reset Progress"
                >
                  <RotateCcw className="w-4 h-4" />
                </button>
              )}
            </div>

            <div className="space-y-8">
              <div className="space-y-3">
                <div className="flex justify-between text-[10px] font-black uppercase text-gray-500 tracking-widest">
                  <span>{t.params.authSigs}</span>
                  <span>{curSigs} / 2</span>
                </div>
                <div className="flex space-x-2">
                  {[1, 2].map(n => (
                    <div key={n} className={`h-3 flex-1 rounded-full transition-all duration-700 ${curSigs >= n ? (activeTab === 'ON_CHAIN' ? 'bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.5)]' : 'bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]') : 'bg-gray-800'}`} />
                  ))}
                </div>
              </div>

              <div className="space-y-3 pt-4">
                <button 
                  onClick={handleSign}
                  disabled={isSigning || curSigs >= 2 || !isCurrentFormValid}
                  className={`w-full py-4 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center justify-center transition-all
                    ${curSigs >= 2 ? 'bg-gray-800 text-gray-500 cursor-default border border-gray-700' : 
                      (!isCurrentFormValid 
                        ? 'bg-gray-950 text-gray-700 border border-gray-800 cursor-not-allowed'
                        : (activeTab === 'ON_CHAIN' 
                          ? 'bg-amber-500 hover:bg-amber-600 text-white shadow-xl shadow-amber-900/20 active:scale-95' 
                          : 'bg-blue-600 hover:bg-blue-700 text-white shadow-xl shadow-blue-900/20 active:scale-95'))}
                  `}
                >
                  {isSigning ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                  {isSigning ? t.params.requesting : t.params.reqSign}
                </button>

                {/* Requirement: Only show Execute for Off-Chain, On-Chain auto-completes */}
                {activeTab === 'OFF_CHAIN' && (
                  <button 
                    onClick={handleExecute}
                    disabled={curSigs < 2}
                    className={`w-full py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center
                      ${curSigs < 2 ? 'bg-gray-900 text-gray-700 cursor-not-allowed border border-gray-800' : 'bg-green-500 hover:bg-green-600 text-white shadow-xl shadow-green-900/20 active:scale-95'}
                    `}
                  >
                    {curSigs >= 2 ? <CheckCircle className="w-4 h-4 mr-2" /> : null}
                    {t.params.applyVals}
                  </button>
                )}
              </div>

              <div className="p-4 bg-gray-950/50 rounded-2xl border border-gray-800">
                <h4 className="text-[10px] font-black text-gray-600 uppercase tracking-widest mb-3">{t.params.pendingLog}</h4>
                {curSigs > 0 ? (
                  <div className="space-y-3">
                    <div className="flex items-center space-x-3 opacity-60">
                      <div className="w-1.5 h-1.5 rounded-full bg-green-500" />
                      <p className="text-[10px] text-gray-400">{t.params.logSigned.replace('{admin}', 'Admin A').replace('{id}', 'P-0012')}</p>
                    </div>
                    {curSigs > 1 && (
                      <div className="flex items-center space-x-3 animate-in fade-in">
                        <div className="w-1.5 h-1.5 rounded-full bg-green-500" />
                        <p className="text-[10px] text-gray-400">{t.params.logSigned.replace('{admin}', 'Admin B').replace('{id}', 'P-0012')}</p>
                      </div>
                    )}
                  </div>
                ) : (
                  <p className="text-[10px] text-gray-700 italic">{t.params.noSigs}</p>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ContractSettings;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  ShieldCheck, 
  Settings, 
  AlertTriangle, 
  ToggleLeft, 
  ToggleRight, 
  Save, 
  Loader2, 
  CheckCircle,
  Database,
  Globe,
  Coins,
  Percent,
  ArrowRightLeft,
  Users,
  RotateCcw,
  BellRing,
  X
} from 'lucide-react';
import { useLanguage } from '../LanguageContext';

type TabType = 'ON_CHAIN' | 'OFF_CHAIN';

interface OnChainParams {
  vaultDepositArb: boolean;
  vaultWithdrawArb: boolean;
  liqPenaltyRatio: string;
  insFundSplit: string;
  keeperSplit: string;
}

interface OffChainParams {
  globalTrading: boolean;
  regSwitch: boolean;
  mmrRatio: string;
  fundingCap: string;
  maxUserPos: string;
  makerFee: string;
  takerFee: string;
  interestRate: string;
  fundingFreq: string;
  orderFreqLimit: string;
}

const ON_CHAIN_DEFAULTS: OnChainParams = {
  vaultDepositArb: true,
  vaultWithdrawArb: true,
  liqPenaltyRatio: '10',
  insFundSplit: '50',
  keeperSplit: '50',
};

const OFF_CHAIN_DEFAULTS: OffChainParams = {
  globalTrading: true,
  regSwitch: true,
  mmrRatio: '50',
  fundingCap: '0.05',
  maxUserPos: '200',
  makerFee: '0.010',
  takerFee: '0.035',
  interestRate: '0.01',
  fundingFreq: '1',
  orderFreqLimit: '1000',
};

const ContractSettings: React.FC = () => {
  const { t } = useLanguage();
  const [activeTab, setActiveTab] = useState<TabType>('ON_CHAIN');

  // Toast System
  const [toast, setToast] = useState<{ show: boolean, msg: string, type: 'success' | 'info' }>({ show: false, msg: '', type: 'success' });

  const showTips = (msg: string, type: 'success' | 'info' = 'success') => {
    setToast({ show: true, msg, type });
    setTimeout(() => setToast(prev => ({ ...prev, show: false })), 3000);
  };

  // Multi-sig states
  const [onChainSigs, setOnChainSigs] = useState(0);
  const [offChainSigs, setOffChainSigs] = useState(0);
  const [isSigning, setIsSigning] = useState(false);

  // Form states
  const [onChainForm, setOnChainForm] = useState<OnChainParams>(ON_CHAIN_DEFAULTS);
  const [offChainForm, setOffChainForm] = useState<OffChainParams>(OFF_CHAIN_DEFAULTS);

  const isOnChainValid = useMemo(() => {
    return Object.values(onChainForm).every(val => val.toString().trim() !== '');
  }, [onChainForm]);

  const isOffChainValid = useMemo(() => {
    return Object.values(offChainForm).every(val => val.toString().trim() !== '');
  }, [offChainForm]);

  const handleSign = () => {
    const isValid = activeTab === 'ON_CHAIN' ? isOnChainValid : isOffChainValid;
    if (!isValid) return;

    setIsSigning(true);
    setTimeout(() => {
      if (activeTab === 'ON_CHAIN') {
        const nextSigs = onChainSigs + 1;
        if (nextSigs >= 2) {
          // Complete modification instantly
          setOnChainSigs(0);
          showTips("On-chain modification completed successfully", "success");
        } else {
          setOnChainSigs(nextSigs);
          showTips(`Administrator signature recorded (${nextSigs}/2)`, "info");
        }
      } else {
        const nextSigs = Math.min(offChainSigs + 1, 2);
        setOffChainSigs(nextSigs);
        if (nextSigs === 2) {
            showTips("Off-chain signatures complete. Ready to apply.", "info");
        } else {
            showTips(`Administrator signature recorded (${nextSigs}/2)`, "info");
        }
      }
      setIsSigning(false);
    }, 1000);
  };

  const handleExecute = () => {
    showTips("Off-chain parameters applied and synchronized", "success");
    setOffChainSigs(0);
  };

  const handleResetProgress = () => {
    if (activeTab === 'ON_CHAIN') setOnChainSigs(0);
    else setOffChainSigs(0);
    showTips("Governance progress reset successfully", "info");
  };

  const handleRestoreDefaults = () => {
    if (activeTab === 'ON_CHAIN') {
      setOnChainForm(ON_CHAIN_DEFAULTS);
      setOnChainSigs(0);
    } else {
      setOffChainForm(OFF_CHAIN_DEFAULTS);
      setOffChainSigs(0);
    }
    showTips("Default parameters restored", "info");
  };

  const Switch = ({ active, onClick, label, disabled }: { active: boolean, onClick: () => void, label: string, disabled?: boolean }) => (
    <div className={`flex items-center justify-between p-4 bg-gray-900/60 border border-gray-800 rounded-xl transition-all ${disabled ? 'opacity-50' : 'hover:border-amber-500/30'}`}>
      <span className="text-sm font-bold text-gray-400 uppercase tracking-tight">{label}</span>
      <button onClick={onClick} disabled={disabled} className="focus:outline-none">
        {active 
          ? <ToggleRight className="w-10 h-10 text-amber-500" /> 
          : <ToggleLeft className="w-10 h-10 text-gray-600" />
        }
      </button>
    </div>
  );

  const InputField = ({ label, value, onChange, unit, desc, disabled }: { label: string, value: string, onChange: (v: string) => void, unit?: string, desc?: string, disabled?: boolean }) => {
    const isEmpty = value.toString().trim() === '';
    return (
      <div className={`space-y-1.5 p-4 bg-gray-900/40 border ${isEmpty ? 'border-red-500/50 shadow-[0_0_8px_rgba(239,68,68,0.15)]' : 'border-gray-800'} rounded-xl group transition-all ${disabled ? 'opacity-50' : 'hover:border-blue-500/30'}`}>
        <div className="flex justify-between items-center">
          <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{label}</label>
          {unit && <span className="text-[9px] font-bold text-gray-600 uppercase">{unit}</span>}
        </div>
        <input 
          type="text" 
          value={value}
          disabled={disabled}
          onChange={(e) => onChange(e.target.value)}
          className={`w-full bg-gray-950 border ${isEmpty ? 'border-red-500' : 'border-gray-800'} rounded-lg px-3 py-2 text-sm font-bold text-white outline-none focus:border-amber-500 transition-all`}
        />
        {desc && <p className="text-[9px] text-gray-600 leading-tight italic">{desc}</p>}
      </div>
    );
  };

  const curSigs = activeTab === 'ON_CHAIN' ? onChainSigs : offChainSigs;
  const isCurrentFormValid = activeTab === 'ON_CHAIN' ? isOnChainValid : isOffChainValid;

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20 relative">

      {/* Toast Feedback */}
      <div className={`fixed top-8 right-8 z-[200] transform transition-all duration-500 ${toast.show ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0'}`}>
         <div className={`flex items-center space-x-4 p-4 rounded-2xl shadow-2xl border ${toast.type === 'success' ? 'bg-green-500/10 border-green-500/50 text-green-400' : 'bg-amber-500/10 border-amber-500/50 text-amber-400'}`}>
            <BellRing className="w-5 h-5" />
            <span className="text-sm font-bold">{toast.msg}</span>
            <button onClick={() => setToast(prev => ({...prev, show: false}))} className="p-1 hover:bg-white/10 rounded-lg">
                <X className="w-4 h-4" />
            </button>
         </div>
      </div>

      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h1 className="text-3xl font-black text-white flex items-center">
            <Settings className="w-8 h-8 mr-3 text-amber-500" />
            {t.params.title}
          </h1>
          <p className="text-gray-400 mt-1">{t.params.subtitle}</p>
        </div>

        <div className="flex bg-gray-900 border border-gray-800 p-1.5 rounded-2xl shadow-inner">
          <button 
            onClick={() => setActiveTab('ON_CHAIN')}
            className={`flex items-center px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'ON_CHAIN' ? 'bg-amber-500 text-white shadow-lg shadow-amber-900/40' : 'text-gray-500 hover:text-gray-300'}`}
          >
            <Database className="w-3.5 h-3.5 mr-2" />
            {t.params.onChainTab}
          </button>
          <button 
            onClick={() => setActiveTab('OFF_CHAIN')}
            className={`flex items-center px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'OFF_CHAIN' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'text-gray-500 hover:text-gray-300'}`}
          >
            <Globe className="w-3.5 h-3.5 mr-2" />
            {t.params.offChainTab}
          </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-4 items-stretch">
        <div className="flex-1 bg-red-900/10 border border-red-900/30 p-5 rounded-3xl flex items-start space-x-4 shadow-sm">
          <AlertTriangle className="w-6 h-6 text-red-500 flex-shrink-0 mt-0.5" />
          <div className="text-sm">
            <p className="font-black text-red-500 uppercase tracking-tight mb-1">{t.params.warningTitle}</p>
            <p className="text-red-400/80 leading-relaxed">{t.params.warningDesc}</p>
          </div>
        </div>
        <button 
          onClick={handleRestoreDefaults}
          className="lg:w-48 flex flex-col items-center justify-center p-5 bg-gray-900 border border-gray-800 hover:border-amber-500/50 rounded-3xl group transition-all"
        >
          <RotateCcw className="w-6 h-6 text-gray-500 group-hover:text-amber-500 mb-2 transition-colors" />
          <span className="text-[10px] font-black uppercase text-gray-500 group-hover:text-white tracking-widest">{t.params.restoreDefaults}</span>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          {activeTab === 'ON_CHAIN' ? (
            <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-4">
                  <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                    <ArrowRightLeft className="w-4 h-4 mr-2 text-amber-500" />
                    {t.params.switches}
                  </h3>
                  <Switch 
                    label={t.params.labels.vaultDeposit} 
                    active={onChainForm.vaultDepositArb} 
                    onClick={() => setOnChainForm({...onChainForm, vaultDepositArb: !onChainForm.vaultDepositArb})} 
                    disabled={curSigs > 0}
                  />
                  <Switch 
                    label={t.params.labels.vaultWithdraw} 
                    active={onChainForm.vaultWithdrawArb} 
                    onClick={() => setOnChainForm({...onChainForm, vaultWithdrawArb: !onChainForm.vaultWithdrawArb})}
                    disabled={curSigs > 0}
                  />
                </div>
                <div className="space-y-4">
                  <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                    <Coins className="w-4 h-4 mr-2 text-amber-500" />
                    {t.params.fees}
                  </h3>
                  <InputField 
                    label={t.params.labels.liqPenalty} 
                    unit="%"
                    value={onChainForm.liqPenaltyRatio} 
                    onChange={(v) => setOnChainForm({...onChainForm, liqPenaltyRatio: v})}
                    disabled={curSigs > 0}
                  />
                  <div className="grid grid-cols-2 gap-3">
                    <InputField 
                      label={t.params.labels.insRatio} 
                      unit="%"
                      value={onChainForm.insFundSplit} 
                      onChange={(v) => setOnChainForm({...onChainForm, insFundSplit: v})}
                      disabled={curSigs > 0}
                    />
                    <InputField 
                      label={t.params.labels.keeperSplit} 
                      unit="%"
                      value={onChainForm.keeperSplit} 
                      onChange={(v) => setOnChainForm({...onChainForm, keeperSplit: v})}
                      disabled={curSigs > 0}
                    />
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-4">
                    <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                      <ArrowRightLeft className="w-4 h-4 mr-2 text-blue-500" />
                      {t.params.switches}
                    </h3>
                    <Switch 
                      label={t.params.labels.trading} 
                      active={offChainForm.globalTrading} 
                      onClick={() => setOffChainForm({...offChainForm, globalTrading: !offChainForm.globalTrading})}
                      disabled={curSigs > 0}
                    />
                    <Switch 
                      label={t.params.labels.reg} 
                      active={offChainForm.regSwitch} 
                      onClick={() => setOffChainForm({...offChainForm, regSwitch: !offChainForm.regSwitch})}
                      disabled={curSigs > 0}
                    />
                  </div>
                  <div className="space-y-4">
                    <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                      <Percent className="w-4 h-4 mr-2 text-blue-500" />
                      {t.params.constants}
                    </h3>
                    <InputField 
                      label={t.params.labels.mmr} 
                      unit="% of IMR"
                      value={offChainForm.mmrRatio} 
                      onChange={(v) => setOffChainForm({...offChainForm, mmrRatio: v})}
                      disabled={curSigs > 0}
                    />
                    <InputField 
                      label={t.params.labels.fundingCap} 
                      unit="%"
                      value={offChainForm.fundingCap} 
                      onChange={(v) => setOffChainForm({...offChainForm, fundingCap: v})}
                      disabled={curSigs > 0}
                    />
                  </div>
               </div>

               <div className="space-y-4">
                 <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest px-1 flex items-center">
                    <Users className="w-4 h-4 mr-2 text-blue-500" />
                    {t.params.tradingParams}
                 </h3>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <InputField label={t.params.labels.maxUserPos} unit="M USDC" value={offChainForm.maxUserPos} onChange={(v) => setOffChainForm({...offChainForm, maxUserPos: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.makerFee} unit="%" value={offChainForm.makerFee} onChange={(v) => setOffChainForm({...offChainForm, makerFee: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.takerFee} unit="%" value={offChainForm.takerFee} onChange={(v) => setOffChainForm({...offChainForm, takerFee: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.interestRate} unit="%/H" value={offChainForm.interestRate} onChange={(v) => setOffChainForm({...offChainForm, interestRate: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.settleFreq} unit="H" value={offChainForm.fundingFreq} onChange={(v) => setOffChainForm({...offChainForm, fundingFreq: v})} disabled={curSigs > 0} />
                    <InputField label={t.params.labels.orderFreq} unit="笔/秒/IP" value={offChainForm.orderFreqLimit} onChange={(v) => setOffChainForm({...offChainForm, orderFreqLimit: v})} disabled={curSigs > 0} />
                 </div>
               </div>
            </div>
          )}
        </div>

        <div className="lg:col-span-1">
          <div className="bg-gray-900 border border-gray-800 rounded-[32px] p-8 sticky top-24 shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-lg font-bold text-white flex items-center">
                <ShieldCheck className="w-5 h-5 mr-2 text-amber-500" />
                {t.params.govStatus}
              </h2>
              {curSigs > 0 && (
                <button 
                  onClick={handleResetProgress}
                  className="text-gray-500 hover:text-amber-500 transition-colors p-1"
                  title="Reset Progress"
                >
                  <RotateCcw className="w-4 h-4" />
                </button>
              )}
            </div>

            <div className="space-y-8">
              <div className="space-y-3">
                <div className="flex justify-between text-[10px] font-black uppercase text-gray-500 tracking-widest">
                  <span>{t.params.authSigs}</span>
                  <span>{curSigs} / 2</span>
                </div>
                <div className="flex space-x-2">
                  {[1, 2].map(n => (
                    <div key={n} className={`h-3 flex-1 rounded-full transition-all duration-700 ${curSigs >= n ? (activeTab === 'ON_CHAIN' ? 'bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.5)]' : 'bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]') : 'bg-gray-800'}`} />
                  ))}
                </div>
              </div>

              <div className="space-y-3 pt-4">
                <button 
                  onClick={handleSign}
                  disabled={isSigning || curSigs >= 2 || !isCurrentFormValid}
                  className={`w-full py-4 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center justify-center transition-all
                    ${curSigs >= 2 ? 'bg-gray-800 text-gray-500 cursor-default border border-gray-700' : 
                      (!isCurrentFormValid 
                        ? 'bg-gray-950 text-gray-700 border border-gray-800 cursor-not-allowed'
                        : (activeTab === 'ON_CHAIN' 
                          ? 'bg-amber-500 hover:bg-amber-600 text-white shadow-xl shadow-amber-900/20 active:scale-95' 
                          : 'bg-blue-600 hover:bg-blue-700 text-white shadow-xl shadow-blue-900/20 active:scale-95'))}
                  `}
                >
                  {isSigning ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                  {isSigning ? t.params.requesting : t.params.reqSign}
                </button>

                {activeTab === 'OFF_CHAIN' && (
                  <button 
                    onClick={handleExecute}
                    disabled={curSigs < 2}
                    className={`w-full py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center
                      ${curSigs < 2 ? 'bg-gray-900 text-gray-700 cursor-not-allowed border border-gray-800' : 'bg-green-500 hover:bg-green-600 text-white shadow-xl shadow-green-900/20 active:scale-95'}
                    `}
                  >
                    {curSigs >= 2 ? <CheckCircle className="w-4 h-4 mr-2" /> : null}
                    {t.params.applyVals}
                  </button>
                )}
              </div>

              <div className="p-4 bg-gray-950/50 rounded-2xl border border-gray-800">
                <h4 className="text-[10px] font-black text-gray-600 uppercase tracking-widest mb-3">{t.params.pendingLog}</h4>
                {curSigs > 0 ? (
                  <div className="space-y-3">
                    <div className="flex items-center space-x-3 opacity-60">
                      <div className="w-1.5 h-1.5 rounded-full bg-green-500" />
                      <p className="text-[10px] text-gray-400">{t.params.logSigned.replace('{admin}', 'Admin A').replace('{id}', 'P-0012')}</p>
                    </div>
                    {curSigs > 1 && (
                      <div className="flex items-center space-x-3 animate-in fade-in">
                        <div className="w-1.5 h-1.5 rounded-full bg-green-500" />
                        <p className="text-[10px] text-gray-400">{t.params.logSigned.replace('{admin}', 'Admin B').replace('{id}', 'P-0012')}</p>
                      </div>
                    )}
                  </div>
                ) : (
                  <p className="text-[10px] text-gray-700 italic">{t.params.noSigs}</p>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ContractSettings;

import React, { createContext, useContext, useState, ReactNode, useEffect } from 'react';
import { translations, Language } from './translations';
import { BellRing, X } from 'lucide-react';

interface ToastState {
  show: boolean;
  msg: string;
  type: 'success' | 'info' | 'error';
}

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: typeof translations.zhCN;
  showTip: (msg: string, type?: 'success' | 'info' | 'error') => void;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguage] = useState<Language>('zhCN');
  const [toast, setToast] = useState<ToastState>({ show: false, msg: '', type: 'success' });

  // Update HTML lang attribute to control native browser locale (like date picker placeholders)
  useEffect(() => {
    const html = document.documentElement;
    if (language === 'zhCN') html.setAttribute('lang', 'zh-CN');
    else if (language === 'zhTW') html.setAttribute('lang', 'zh-TW');
    else html.setAttribute('lang', 'en');
  }, [language]);

  const showTip = (msg: string, type: 'success' | 'info' | 'error' = 'success') => {
    setToast({ show: true, msg, type });
    setTimeout(() => setToast(prev => ({ ...prev, show: false })), 4000);
  };

  const value = {
    language,
    setLanguage,
    t: translations[language],
    showTip
  };

  return (
    <LanguageContext.Provider value={value}>
      {children}

      {/* Global Toast Component */}
      <div className={`fixed top-8 right-8 z-[2000] transform transition-all duration-500 ease-out ${toast.show ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0 pointer-events-none'}`}>
        <div className={`flex items-center space-x-4 p-4 rounded-2xl shadow-2xl border min-w-[320px] backdrop-blur-xl ${
          toast.type === 'success' ? 'bg-green-500/10 border-green-500/50 text-green-400' : 
          toast.type === 'error' ? 'bg-red-500/10 border-red-500/50 text-red-400' :
          'bg-amber-500/10 border-amber-500/50 text-amber-400'
        }`}>
          <div className="p-2 rounded-xl bg-white/5">
            <BellRing className="w-5 h-5" />
          </div>
          <div className="flex-1 flex flex-col">
            <span className="text-[10px] font-black uppercase opacity-60 tracking-widest mb-0.5">GoldenDex Terminal</span>
            <span className="text-sm font-bold leading-tight">{toast.msg}</span>
          </div>
          <button onClick={() => setToast(prev => ({ ...prev, show: false }))} className="p-1.5 hover:bg-white/10 rounded-xl transition-colors">
            <X className="w-4 h-4" />
          </button>
        </div>
      </div>
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

import React, { useState, useMemo } from 'react';
import { UserPlus, Shield, Trash2, Edit2, ShieldAlert, X, Check, ListChecks, ShieldCheck } from 'lucide-react';
