      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-gradient-to-br from-gray-900/80 to-gray-900/40 border border-gray-800 p-6 rounded-2xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
            <ShieldCheck className="w-12 h-12 text-green-500" />
          </div>
          <p className="text-xs text-gray-500 uppercase font-black tracking-widest mb-2">{t.risk.insuranceBalance}</p>
          <p className="text-3xl font-black text-white">${insuranceBalanceValue.toLocaleString()}</p>

          <div className="flex space-x-2 mt-4">
            <button 
              onClick={() => handleOpenModal('RECHARGE')}
              className="flex-1 flex items-center justify-center space-x-2 bg-amber-500/10 hover:bg-amber-500/20 text-amber-500 py-2 rounded-xl text-xs font-bold transition-all border border-amber-500/20"
            >
              <PlusCircle className="w-3.5 h-3.5" />
              <span>{t.risk.recharge}</span>
            </button>
            <button 
              onClick={() => handleOpenModal('WITHDRAW')}
              className="flex-1 flex items-center justify-center space-x-2 bg-gray-800 hover:bg-gray-700 text-gray-300 py-2 rounded-xl text-xs font-bold transition-all border border-gray-700"
            >
              <MinusCircle className="w-3.5 h-3.5" />
              <span>{t.risk.withdraw}</span>
            </button>
          </div>
        </div>

        {[
          { label: t.risk.insuranceUsage, value: globalInsurance.usageRate, icon: Activity, color: 'text-blue-500' },
          { label: t.risk.insurancePaid, value: globalInsurance.totalPaid, icon: ShieldAlert, color: 'text-amber-500' }
        ].map((item, idx) => (
          <div key={idx} className="bg-gradient-to-br from-gray-900/80 to-gray-900/40 border border-gray-800 p-6 rounded-2xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
              <item.icon className={`w-12 h-12 ${item.color}`} />
            </div>
            <p className="text-xs text-gray-500 uppercase font-black tracking-widest mb-2">{item.label}</p>
            <p className={`text-3xl font-black text-white`}>{item.value}</p>
          </div>
        ))}
      </div>

      {opModal.type && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => !isSigning && setOpModal({ type: null })} />
          <div className="relative w-full max-w-md bg-gray-900 border border-gray-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-6">
              {opModal.type === 'RECHARGE' ? t.risk.modals.rechargeTitle : t.risk.modals.withdrawTitle}
            </h3>

            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.risk.modals.chain}</label>
                <div className="relative">
                  <Globe className="absolute left-3 top-2.5 h-4 w-4 text-amber-500" />
                  <select className="w-full bg-gray-800 border border-gray-700 rounded-xl py-2.5 pl-10 pr-4 text-sm outline-none appearance-none text-gray-300">
                    <option>Arbitrum</option>
                    <option>Ethereum</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.risk.modals.token}</label>
                <div className="relative">
                  <Coins className="absolute left-3 top-2.5 h-4 w-4 text-amber-500" />
                  <select className="w-full bg-gray-800 border border-gray-700 rounded-xl py-2.5 pl-10 pr-4 text-sm outline-none appearance-none text-gray-300">
                    <option>USDC</option>
                    <option>USDT</option>
                  </select>
                </div>
              </div>

              <div>
                <div className="flex justify-between mb-1.5 px-1">
                   <label className="text-xs font-bold text-gray-500 uppercase">{t.common.amount}</label>
                   <span className="text-[10px] font-bold text-gray-600 uppercase">
                     {opModal.type === 'RECHARGE' ? t.risk.modals.walletBalance : t.risk.modals.fundBalance}: 
                     <span className="text-amber-500 ml-1">
                       {opModal.type === 'RECHARGE' ? walletBalance.toLocaleString() : insuranceBalanceValue.toLocaleString()} USDC
                     </span>
                   </span>
                </div>
                <div className="relative">
                   <input 
                      type="text" 
                      value={amount}
                      onChange={e => {
                        setAmount(e.target.value);
                        if (error && e.target.value.trim()) setError(false);
                      }}
                      placeholder="0.00"
                      disabled={sigCount > 0}
                      className={`w-full bg-gray-800 border ${error ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl py-2.5 px-4 text-sm font-bold text-white outline-none focus:border-amber-500 transition-all ${sigCount > 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
                   />
                   {sigCount === 0 && (
                    <button 
                      onClick={() => setAmount(opModal.type === 'RECHARGE' ? walletBalance.toString() : insuranceBalanceValue.toString())}
                      className="absolute right-3 top-2.5 text-[10px] font-black text-amber-500 hover:text-amber-400 uppercase tracking-widest"
                    >
                      Max
                    </button>
                   )}
                </div>
              </div>

              {opModal.type === 'WITHDRAW' && (
                <div className="mt-4 p-4 bg-gray-800/40 border border-gray-800 rounded-2xl space-y-3">
                  <div className="flex justify-between items-center text-[10px] font-black uppercase text-gray-500 tracking-widest">
                    <div className="flex items-center space-x-2">
                       <span>{t.contract.modals.pendingSigs}</span>
                       {sigCount > 0 && (
                        <button 
                          onClick={handleResetSig}
                          className="text-amber-500 hover:text-amber-400 p-1 rounded-md bg-amber-500/5 transition-colors"
                          title={t.risk.modals.resetSig}
                        >
                          <RotateCcw className="w-3 h-3" />
                        </button>
                       )}
                    </div>
                    <span className="text-amber-500">{sigCount} / 2</span>
                  </div>
                  <div className="flex space-x-2">
                    {[1, 2].map(n => (
                      <div key={n} className={`h-1.5 flex-1 rounded-full transition-all duration-700 ${sigCount >= n ? 'bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.5)]' : 'bg-gray-700'}`} />
                    ))}
                  </div>
                  <p className="text-[10px] text-gray-500 italic">{t.risk.modals.multiSigInfo}</p>
                </div>
              )}
            </div>

            <div className="flex space-x-3 mt-8">
              <button 
                onClick={() => setOpModal({ type: null })}
                className="flex-1 px-4 py-3 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm font-bold text-gray-300 transition-all"
                disabled={isSigning}
              >
                {t.common.cancel}
              </button>

              <button 
                onClick={handleSign}
                disabled={isSigning || (opModal.type === 'WITHDRAW' && sigCount >= 2)}
                className={`flex-1 px-4 py-3 rounded-xl text-sm font-bold text-white transition-all shadow-lg flex items-center justify-center 
                  ${isSigning ? 'bg-gray-700 cursor-not-allowed' : (opModal.type === 'WITHDRAW' && sigCount >= 2 ? 'bg-gray-800 cursor-default' : 'bg-amber-500 hover:bg-amber-600 shadow-amber-900/20')}`}
              >
                {isSigning ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin mr-2" />
                    <span>Signing...</span>
                  </>
                ) : (
                  <>
                    <Shield className="w-4 h-4 mr-2" />
                    <span>{opModal.type === 'WITHDRAW' ? (sigCount === 0 ? t.contract.modals.sign : t.common.confirm) : t.common.confirm}</span>
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {[
          { label: t.risk.avgMr, value: '34.2%', sub: t.risk.healthy, color: 'text-amber-500' },
          { label: t.risk.pendingLiq, value: '3', sub: `$12,500 ${t.risk.value}`, color: 'text-red-500' },
          { label: t.risk.inLiq, value: '1', sub: `$42,000 ${t.risk.value}`, color: 'text-orange-500' },
          { label: t.risk.liquidated, value: '142', sub: `$1.2M ${t.risk.value}`, color: 'text-blue-500' }
        ].map((stat, idx) => (
          <div key={idx} className="bg-gray-900/60 border border-gray-800 p-6 rounded-2xl hover:border-gray-700 transition-all">
            <p className="text-xs text-gray-500 uppercase font-bold mb-2">{stat.label}</p>
            <p className={`text-3xl font-black ${stat.color}`}>{stat.value}</p>
            <p className="text-[10px] text-gray-400 mt-2 font-bold uppercase tracking-tight opacity-70">{stat.sub}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-gray-900/40 border border-gray-800 rounded-3xl p-6">
          <h3 className="text-lg font-bold text-gray-300 mb-6 flex items-center">
            <TrendingDown className="w-5 h-5 mr-2 text-blue-500" />
            {t.risk.curveTitle}
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={marginCurveData}>
                <defs>
                  <linearGradient id="colorMR" x1="0" x1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" vertical={false} />
                <XAxis dataKey="size" axisLine={false} tick={{fill: '#9ca3af', fontSize: 10}} unit=" USDC" />
                <YAxis axisLine={false} tick={{fill: '#9ca3af', fontSize: 10}} tickFormatter={(val) => `${val}%`} />
                <Tooltip contentStyle={{ backgroundColor: '#111827', border: 'none', borderRadius: '12px', color: '#fff' }} />
                <Area type="monotone" dataKey="MR" stroke="#3b82f6" fillOpacity={1} fill="url(#colorMR)" strokeWidth={3} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-gray-900/40 border border-gray-800 rounded-3xl p-6 lg:col-span-1">
          <h3 className="text-lg font-bold text-gray-300 mb-6 flex items-center">
            <Target className="w-5 h-5 mr-2 text-red-500" />
            {t.risk.scatterTitle}
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" vertical={false} />
                <XAxis type="number" dataKey="leverage" name={t.market.leverage} unit="x" axisLine={false} tick={{fill: '#9ca3af', fontSize: 10}} domain={[0, 150]} />
                <YAxis type="number" dataKey="price" name={t.market.liqPrice} axisLine={false} tick={{fill: '#9ca3af', fontSize: 10}} />
                <ZAxis type="number" dataKey="amount" range={[100, 1000]} />
                <Tooltip cursor={{ strokeDasharray: '3 3' }} />
                <Scatter name="Liquidations" data={scatterData} fill="#ef4444" fillOpacity={0.5} />
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RiskCenter;

import React, { useState, useMemo } from 'react';
import { Search, UserX, ShieldCheck, Mail, Globe, ExternalLink, Calendar, AlertTriangle, Users, HelpCircle } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface ExtendedUserAccount {
  uid: string;
  wallet: string;
  email: string;
  registeredAt: string;
  balance: number;
  lastIp: string;
  lastLoginAt: string;
  isFrozen: boolean;
  lastActionReason?: string;
}

const UserManagement: React.FC = () => {
  const { t, showTip } = useLanguage();

  const initialUsers: ExtendedUserAccount[] = [
    { uid: 'U100254', wallet: '0xd3e...58e3', email: 'user1@example.com', registeredAt: '2025-10-01', balance: 12500, lastIp: '192.168.1.1', lastLoginAt: '2025-12-10 09:15:22', isFrozen: false, lastActionReason: '异常解除' },
    { uid: 'U100255', wallet: '0x8a2...3211', email: 'whale@deep.io', registeredAt: '2025-11-12', balance: 450000, lastIp: '45.12.33.2', lastLoginAt: '2025-12-10 11:45:10', isFrozen: false },
    { uid: 'U100256', wallet: '0x4f1...99bc', email: 'test@dev.com', registeredAt: '2025-12-01', balance: 50, lastIp: '127.0.0.1', lastLoginAt: '2025-12-05 14:20:00', isFrozen: true, lastActionReason: '异常操作' },
  ];

  const [users, setUsers] = useState(initialUsers);
  const [searchQuery, setSearchQuery] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [statusFilter, setStatusFilter] = useState('ALL');
  const [confirmModal, setConfirmModal] = useState<{ uid: string, wallet: string, action: 'freeze' | 'unfreeze' } | null>(null);

  const [reason, setReason] = useState('');
  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleAction = () => {
    if (!confirmModal) return;

    setIsSubmitted(true);
    if (!reason.trim()) return;

    setUsers(prev => prev.map(u => {
      if (u.uid === confirmModal.uid) {
        const isFreezing = confirmModal.action === 'freeze';
        return { 
          ...u, 
          isFrozen: isFreezing,
          lastActionReason: reason 
        };
      }
      return u;
    }));

    showTip(confirmModal.action === 'freeze' ? t.tips.userFrozen : t.tips.userUnfrozen, 'info');
    closeModal();
  };

  const closeModal = () => {
    setConfirmModal(null);
    setReason('');
    setIsSubmitted(false);
  };

  const filteredUsers = useMemo(() => {
    return users.filter(user => {
      if (statusFilter === 'ACTIVE' && user.isFrozen) return false;
      if (statusFilter === 'FROZEN' && !user.isFrozen) return false;

      const matchesSearch = user.wallet.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          user.uid.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          user.email.toLowerCase().includes(searchQuery.toLowerCase());
      if (!matchesSearch) return false;

      if (dateRange.start && user.registeredAt < dateRange.start) return false;
      if (dateRange.end && user.registeredAt > dateRange.end) return false;

      return true;
    });
  }, [users, searchQuery, dateRange, statusFilter]);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center">
            <Users className="w-6 h-6 mr-3 text-amber-500" />
            {t.users.title}
          </h1>
          <p className="text-gray-400">{t.users.subtitle}</p>
        </div>
        <div className="flex items-center space-x-2 bg-gray-900 border border-gray-800 rounded-lg px-4 py-2 shadow-xl">
          <span className="text-xs text-gray-500 font-bold uppercase">{t.users.total}:</span>
          <span className="text-sm font-black text-amber-500">892,102</span>
        </div>
      </div>

      <div className="bg-gray-900/40 border border-gray-800 rounded-2xl p-4 flex flex-wrap gap-4 items-center">
        <div className="relative flex-1 min-w-[300px]">
          <Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-500" />
          <input 
            type="text" 
            placeholder={t.users.placeholder} 
            className="w-full bg-gray-900 border border-gray-800 rounded-lg py-2 pl-10 text-sm focus:border-amber-500 outline-none transition-all"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        <div className="flex items-center bg-gray-900 border border-gray-800 rounded-xl px-4 py-2 space-x-3 group hover:border-gray-700 transition-all">
          <Calendar className="w-4 h-4 text-gray-500 group-hover:text-amber-500 transition-colors" />
          <div className="flex items-center space-x-2">
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">{t.users.regTime}:</span>
            <input 
              type="date" 
              className="bg-transparent text-xs text-gray-300 outline-none [color-scheme:dark] cursor-pointer"
              value={dateRange.start}
              onChange={(e) => setDateRange({...dateRange, start: e.target.value})}
            />
            <span className="text-gray-700">-</span>
            <input 
              type="date" 
              className="bg-transparent text-xs text-gray-300 outline-none [color-scheme:dark] cursor-pointer"
              value={dateRange.end}
              onChange={(e) => setDateRange({...dateRange, end: e.target.value})}
            />
          </div>
        </div>

        <select 
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="bg-gray-900 border border-gray-800 rounded-lg py-2 px-4 text-sm focus:border-amber-500 outline-none text-gray-400 font-bold cursor-pointer"
        >
          <option value="ALL">{t.common.status}: {t.common.all}</option>
          <option value="ACTIVE">{t.users.statusActive}</option>
          <option value="FROZEN">{t.users.statusFrozen}</option>
        </select>
      </div>

      <div className="bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden shadow-2xl">
        <table className="w-full text-left">
          <thead className="bg-gray-800/50 text-gray-400 text-[10px] font-black uppercase tracking-widest">
            <tr>
              <th className="px-6 py-4">{t.users.identity}</th>
              <th className="px-6 py-4">{t.users.assets}</th>
              <th className="px-6 py-4">{t.users.regTime}</th>
              <th className="px-6 py-4">{t.users.lastLoginTime}</th>
              <th className="px-6 py-4">{t.users.lastLogin}</th>
              <th className="px-6 py-4">{t.users.security}</th>
              <th className="px-6 py-4">{t.common.action}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-800/50">
            {filteredUsers.map((user) => (
              <tr key={user.uid} className="hover:bg-amber-500/[0.01] transition-all group">
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <div className="text-sm font-bold text-white flex items-center group-hover:text-amber-500 transition-colors">
                      {user.wallet}
                      <ExternalLink className="w-3 h-3 ml-2 text-gray-600 cursor-pointer hover:text-amber-500" />
                    </div>
                    <div className="flex items-center text-[10px] text-gray-500 mt-1 font-bold">
                      <span className="mr-3 uppercase tracking-tighter">UID: {user.uid}</span>
                      <span className="flex items-center"><Mail className="w-3 h-3 mr-1 opacity-50" /> {user.email}</span>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="text-sm font-black text-amber-500">${user.balance.toLocaleString()}</div>
                </td>
                <td className="px-6 py-4">
                  <div className="text-xs text-gray-400 font-mono font-bold tracking-tight">{user.registeredAt}</div>
                </td>
                <td className="px-6 py-4">
                  <div className="text-xs text-gray-400 font-mono font-bold tracking-tight">{user.lastLoginAt}</div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center text-xs text-gray-500 font-mono font-bold">
                    <Globe className="w-3 h-3 mr-1.5 text-blue-500/50" />
                    {user.lastIp}
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center space-x-1.5">
                    <span className={`px-2.5 py-1 rounded text-[10px] font-black uppercase tracking-widest ${user.isFrozen ? 'bg-red-500/10 text-red-500 ring-1 ring-red-500/20' : 'bg-green-500/10 text-green-500 ring-1 ring-green-500/20'}`}>
                      {user.isFrozen ? t.users.statusFrozen : t.users.verified}
                    </span>
                    {user.lastActionReason && (
                      <div className="relative group/tooltip">
                        <HelpCircle className="w-4 h-4 text-gray-600 cursor-help hover:text-amber-500 transition-colors" />
                        {/* Tooltip Content */}
                        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 hidden group-hover/tooltip:block z-50 transition-all">
                           <div className="bg-gray-800 text-white text-[10px] font-bold py-2 px-3 rounded-xl shadow-2xl border border-gray-700 whitespace-nowrap">
                             <div className="flex flex-col">
                               <span className="text-gray-500 uppercase text-[8px] mb-0.5">{t.users.lastReason}</span>
                               <span>{user.lastActionReason}</span>
                             </div>
                             {/* Tooltip Arrow */}
                             <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-gray-800" />
                           </div>
                        </div>
                      </div>
                    )}
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end space-x-2">
                    {user.isFrozen ? (
                      <button 
                        onClick={() => setConfirmModal({ uid: user.uid, wallet: user.wallet, action: 'unfreeze' })}
                        className="p-2 text-green-500 hover:bg-green-500/10 rounded-xl transition-all border border-transparent hover:border-green-500/30" 
                        title="Unfreeze"
                      >
                        <ShieldCheck className="w-4 h-4" />
                      </button>
                    ) : (
                      <button 
                        onClick={() => setConfirmModal({ uid: user.uid, wallet: user.wallet, action: 'freeze' })}
                        className="p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition-all border border-transparent hover:border-red-500/30" 
                        title="Freeze User"
                      >
                        <UserX className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {confirmModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={closeModal} />
          <div className="relative w-full max-w-sm bg-gray-900 border border-gray-800 rounded-[32px] shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <div className="flex flex-col items-center text-center space-y-4">
              <div className={`p-4 rounded-3xl ${confirmModal.action === 'freeze' ? 'bg-red-500/10 text-red-500' : 'bg-green-500/10 text-green-500'}`}>
                 <AlertTriangle className="w-10 h-10" />
              </div>
              <div className="space-y-2 w-full">
                <h3 className="text-xl font-bold text-white">
                  {confirmModal.action === 'freeze' ? t.users.freezeTitle : t.users.unfreezeTitle}
                </h3>
                <p className="text-sm text-gray-400">
                  {confirmModal.action === 'freeze' 
                    ? t.users.freezeDesc.replace('{uid}', confirmModal.uid) 
                    : t.users.unfreezeDesc.replace('{uid}', confirmModal.uid)}
                </p>

                <div className="mt-6 text-left space-y-2">
                   <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest px-1">
                     {t.users.reasonLabel} <span className="text-red-500">*</span>
                   </label>
                   <textarea 
                     value={reason}
                     onChange={(e) => setReason(e.target.value)}
                     placeholder={t.users.reasonPlaceholder}
                     className={`w-full bg-gray-950 border ${isSubmitted && !reason.trim() ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-800'} rounded-2xl px-4 py-3 text-sm text-white outline-none focus:border-amber-500/50 transition-all resize-none h-24`}
                   />
                </div>
              </div>
            </div>
            <div className="flex space-x-3 mt-8">
              <button 
                onClick={closeModal}
                className="flex-1 px-4 py-3 bg-gray-800/60 hover:bg-gray-700/60 rounded-2xl text-sm font-bold text-gray-300 transition-all border border-gray-700"
              >
                {t.common.cancel}
              </button>
              <button 
                onClick={handleAction}
                className={`flex-1 px-4 py-3 rounded-2xl text-sm font-bold text-white transition-all shadow-lg ${
                  confirmModal.action === 'freeze' 
                    ? 'bg-red-500 hover:bg-red-600 shadow-red-900/20' 
                    : 'bg-green-500 hover:bg-green-600 shadow-green-900/20'
                }`}
              >
                {t.common.confirm}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

