        setInsuranceBalanceValue(prev => prev + numAmount);
        setWalletBalance(prev => prev - numAmount);
        setIsSigning(false);
        setOpModal({ type: null });
        showTip(t.tips.rechargeSuccess, 'success');
      } else {
        const nextSigCount = sigCount + 1;
        setSigCount(nextSigCount);
        setIsSigning(false);

