  const [signingId, setSigningId] = useState<string | null>(null);

  // Rejection state
  const [rejectModal, setRejectModal] = useState<{ id: string, uid: string } | null>(null);

  // Use state for withdraw records to allow status updates
  const [withdrawRecords, setWithdrawRecords] = useState<FundRecord[]>([
    { id: 'W101', uid: '565682', wallet: '0xs4d5ad...88e1', token: 'USDC', network: 'Arbitrum', amount: 2000, time: '2025-12-10 10:31:19', status: 'PENDING' },
    { id: 'W102', uid: '123445', wallet: '0xabc999...f012', token: 'USDC', network: 'Arbitrum', amount: 5500, time: '2025-12-10 09:12:05', status: 'PENDING' },
    { id: 'W103', uid: '881223', wallet: '0xfee01a...d9e3', token: 'USDC', network: 'Arbitrum', amount: 150, time: '2025-12-10 08:45:00', status: 'PROCESSING' },
    { id: 'W104', uid: '992233', wallet: '0x321abc...77d2', token: 'USDC', network: 'Arbitrum', amount: 12000, time: '2025-12-09 14:20:11', status: 'COMPLETED' },
    { id: 'W105', uid: '776655', wallet: '0x999000...111a', token: 'USDC', network: 'Arbitrum', amount: 800, time: '2025-12-09 10:10:05', status: 'REJECTED' },
    { id: 'W106', uid: '112233', wallet: '0xdead...beef', token: 'USDC', network: 'Arbitrum', amount: 50, time: '2025-12-08 22:30:45', status: 'FAILED' },
  ]);

  const depositRecords = useMemo(() => [
    { uid: '565682', wallet: '0xs4d5ad...88e1', token: 'USDC', network: 'Arbitrum', amount: 2000, time: '2025-12-10 10:31:19' },
    { uid: '123445', wallet: '0xabc999...f012', token: 'USDC', network: 'Arbitrum', amount: 5500, time: '2025-12-10 09:12:05' },
    { uid: '881223', wallet: '0xfee01a...d9e3', token: 'USDC', network: 'Arbitrum', amount: 150, time: '2025-12-10 08:45:00' },
  ], []);

  const handleApprove = (id: string) => {
    setSigningId(id);
    // Simulate wallet signing delay
    setTimeout(() => {
      setSigs(prev => {
        const newVal = Math.min((prev[id] || 0) + 1, 2);
        if (newVal === 2) {
            // Once 2 sigs reached, mark as completed in mock state after a small delay
            setTimeout(() => {
                setWithdrawRecords(list => list.map(r => r.id === id ? { ...r, status: 'COMPLETED' } : r));
                showTip(t.tips.withdrawApproved, 'success');
            }, 500);
        } else {
            showTip(t.tips.paramsSigRecorded.replace('{sigs}', newVal.toString()), 'info');
        }
        return { ...prev, [id]: newVal };
      });
      setSigningId(null);
    }, 1500);
  };

  const handleResetSigs = (id: string) => {
    setSigs(prev => ({ ...prev, [id]: 0 }));
    showTip(t.tips.progressReset, 'info');
  };

  const handleRejectConfirm = () => {
    if (!rejectModal) return;
    setWithdrawRecords(list => list.map(r => r.id === rejectModal.id ? { ...r, status: 'REJECTED' } : r));
    setRejectModal(null);
    showTip(t.tips.withdrawRejected, 'info');
  };

  const filteredData = useMemo(() => {
    if (mainTab === 'DEPOSIT') {
      return depositRecords.filter(r => 
        (r.uid.includes(searchQuery) || r.wallet.includes(searchQuery)) &&
        r.token === tokenFilter &&
        r.network === networkFilter
      );
    } else {
      return withdrawRecords.filter(r => 
        r.status === withdrawTab &&
        (r.uid.includes(searchQuery) || r.wallet.includes(searchQuery)) &&
        r.token === tokenFilter &&
        r.network === networkFilter
      );
    }
  }, [mainTab, withdrawTab, searchQuery, tokenFilter, networkFilter, depositRecords, withdrawRecords]);

  // Statistics calculation based on requirements
  const stats = useMemo(() => {
    if (mainTab === 'DEPOSIT') {
      return {
        count: depositRecords.length,
        amount: depositRecords.reduce((acc, curr) => acc + curr.amount, 0)
      };
    } else {
      const filteredForStats = withdrawRecords.filter(r => r.status === withdrawTab);
      return {
        count: filteredForStats.length,
        amount: filteredForStats.reduce((acc, curr) => acc + curr.amount, 0)
      };
    }
  }, [mainTab, withdrawTab, depositRecords, withdrawRecords]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      {/* Top Header & Main Tab Switcher */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white tracking-tight flex items-center">
            <Wallet className="w-6 h-6 mr-3 text-amber-500" />
            {t.funds.title}
          </h1>
          <p className="text-gray-400 text-sm">{t.funds.subtitle}</p>
        </div>
        <div className="bg-gray-900/80 border border-gray-800 p-1 rounded-xl flex shadow-lg">
          <button 
            onClick={() => setMainTab('DEPOSIT')}
            className={`px-8 py-2.5 rounded-lg text-sm font-black uppercase tracking-widest transition-all ${mainTab === 'DEPOSIT' ? 'bg-amber-500 text-white shadow-xl shadow-amber-500/20' : 'text-gray-500 hover:text-gray-300'}`}
          >
            {t.funds.recharge}
          </button>
          <button 
            onClick={() => setMainTab('WITHDRAW')}
            className={`px-8 py-2.5 rounded-lg text-sm font-black uppercase tracking-widest transition-all ${mainTab === 'WITHDRAW' ? 'bg-amber-500 text-white shadow-xl shadow-amber-500/20' : 'text-gray-500 hover:text-gray-300'}`}
          >
            {t.funds.withdrawals}
          </button>
        </div>
      </div>

      {/* Sub-tabs for Withdrawals Only */}
      {mainTab === 'WITHDRAW' && (
        <div className="flex space-x-2 border-b border-gray-800/50 pb-px">
          {(['PENDING', 'PROCESSING', 'COMPLETED', 'REJECTED', 'FAILED'] as WithdrawSubTab[]).map(tab => (
            <button
              key={tab}
              onClick={() => setWithdrawTab(tab)}
              className={`px-4 py-3 text-xs font-black uppercase tracking-widest border-b-2 transition-all ${
                withdrawTab === tab 
                  ? 'border-amber-500 text-amber-500 bg-amber-500/5' 
                  : 'border-transparent text-gray-500 hover:text-gray-300 hover:bg-gray-800/30'
              }`}
            >
              {t.funds.tabs[tab.toLowerCase() as keyof typeof t.funds.tabs]}
            </button>
          ))}
        </div>
      )}

      {/* Stats Cards Section */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-gray-900/60 border border-gray-800 p-6 rounded-3xl relative overflow-hidden group">
          <div className="absolute -right-4 -top-4 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
            <Coins className="w-24 h-24 text-amber-500" />
          </div>
          <p className="text-[10px] text-gray-500 uppercase font-black tracking-widest mb-1.5">
            {mainTab === 'DEPOSIT' ? t.funds.stats.totalCount : t.funds.stats[`${withdrawTab.toLowerCase()}Count` as keyof typeof t.funds.stats]}
          </p>
          <div className="flex items-end space-x-3">
            <span className="text-4xl font-black text-white">{stats.count}</span>
            <span className="text-xs font-bold text-gray-500 mb-1.5 uppercase">Records</span>
          </div>
        </div>
        <div className="bg-gray-900/60 border border-gray-800 p-6 rounded-3xl relative overflow-hidden group">
          <div className="absolute -right-4 -top-4 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
            <Wallet className="w-24 h-24 text-blue-500" />
          </div>
          <p className="text-[10px] text-gray-500 uppercase font-black tracking-widest mb-1.5">
            {mainTab === 'DEPOSIT' ? t.funds.stats.totalAmount : t.funds.stats[`${withdrawTab.toLowerCase()}Amount` as keyof typeof t.funds.stats]}
          </p>
          <div className="flex items-end space-x-3">
            <span className="text-4xl font-black text-amber-500">{stats.amount.toLocaleString()}</span>
            <span className="text-xs font-bold text-gray-500 mb-1.5 uppercase">USDC</span>
          </div>
        </div>
      </div>

      {/* Search Bar & Advanced Filters */}
      <div className="bg-gray-900/40 border border-gray-800 rounded-2xl p-4 flex flex-wrap gap-4 items-center shadow-inner">
        <div className="relative flex-1 min-w-[300px]">
          <Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-500" />
          <input 
            type="text" 
            placeholder="Search Wallet Address or UID..." 
            className="w-full bg-gray-950 border border-gray-800 rounded-xl py-2 pl-10 text-sm focus:border-amber-500 outline-none transition-all text-gray-300"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        <div className="flex items-center bg-gray-950 border border-gray-800 rounded-xl px-4 py-2 space-x-3 group hover:border-gray-700 transition-all">
          <Calendar className="w-4 h-4 text-gray-500 group-hover:text-amber-500 transition-colors" />
          <div className="flex items-center space-x-2">
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">{t.funds.filters.dateRange}:</span>
            <input 
              type="date" 
              className="bg-transparent text-xs text-gray-300 outline-none [color-scheme:dark] cursor-pointer"
              value={dateRange.start}
              onChange={(e) => setDateRange({...dateRange, start: e.target.value})}
            />
            <span className="text-gray-700">-</span>
            <input 
              type="date" 
              className="bg-transparent text-xs text-gray-300 outline-none [color-scheme:dark] cursor-pointer"
              value={dateRange.end}
              onChange={(e) => setDateRange({...dateRange, end: e.target.value})}
            />
          </div>
        </div>

        <div className="flex space-x-2">
          <div className="relative">
            <select 
              value={tokenFilter}
              onChange={(e) => setTokenFilter(e.target.value)}
              className="bg-gray-950 border border-gray-800 rounded-xl py-2 px-4 text-xs font-bold text-gray-400 outline-none focus:border-amber-500 transition-colors cursor-pointer appearance-none pr-8"
            >
              <option value="USDC">USDC</option>
              <option value="ETH">ETH</option>
              <option value="BTC">BTC</option>
            </select>
            <Filter className="w-3 h-3 text-gray-600 absolute right-3 top-3 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              value={networkFilter}
              onChange={(e) => setNetworkFilter(e.target.value)}
              className="bg-gray-950 border border-gray-800 rounded-xl py-2 px-4 text-xs font-bold text-gray-400 outline-none focus:border-amber-500 transition-colors cursor-pointer appearance-none pr-8"
            >
              <option value="Arbitrum">Arbitrum</option>
              <option value="Ethereum">Ethereum</option>
              <option value="Solana">Solana</option>
              <option value="Polygon">Polygon</option>
            </select>
            <Filter className="w-3 h-3 text-gray-600 absolute right-3 top-3 pointer-events-none" />
          </div>
        </div>
      </div>

      {/* Main Table Content */}
      <div className="bg-gray-900/40 border border-gray-800 rounded-3xl overflow-hidden shadow-2xl">
        <table className="w-full text-left">
          <thead className="bg-gray-800/50 text-gray-400 text-[10px] font-black uppercase tracking-widest">
            <tr>
              {mainTab === 'WITHDRAW' && <th className="px-6 py-5 w-16">#</th>}
              <th className="px-6 py-5">{t.funds.table.uid} | {t.funds.table.address}</th>
              <th className="px-6 py-5">{t.funds.table.token}</th>
              <th className="px-6 py-5">{t.funds.table.network}</th>
              <th className="px-6 py-5">{mainTab === 'DEPOSIT' ? t.funds.table.quantity : t.funds.table.withdrawQty}</th>
              <th className="px-6 py-5">{t.funds.table.time}</th>
              {mainTab === 'WITHDRAW' && <th className="px-6 py-5 text-right">{t.common.status} / {t.funds.table.actions}</th>}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-800/50">
            {filteredData.length > 0 ? filteredData.map((rec, idx) => (
              <tr key={idx} className="hover:bg-amber-500/[0.01] transition-all group">
                {mainTab === 'WITHDRAW' && <td className="px-6 py-5 text-xs text-gray-600 font-mono">{(rec as any).id}</td>}
                <td className="px-6 py-5">
                  <div className="flex items-center space-x-3">
                    <div className={`p-2 rounded-xl transition-colors ${mainTab === 'DEPOSIT' ? 'bg-green-500/10 text-green-500' : 'bg-amber-500/10 text-amber-500'}`}>
                      {mainTab === 'DEPOSIT' ? <ArrowDownLeft className="w-5 h-5" /> : <ArrowUpRight className="w-5 h-5" />}
                    </div>
                    <div>
                      <div className="text-sm font-mono font-bold text-white group-hover:text-amber-500 transition-colors tracking-tight">{rec.wallet}</div>
                      <div className="text-[10px] text-gray-500 uppercase font-black tracking-tighter">UID: {rec.uid}</div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-5">
                  <span className="text-sm font-black text-white">{rec.token}</span>
                </td>
                <td className="px-6 py-5">
                  <span className="text-[10px] font-black uppercase bg-gray-800 px-2.5 py-1 rounded-lg border border-gray-700 text-gray-400 tracking-tighter">{rec.network}</span>
                </td>
                <td className="px-6 py-5">
                  <div className="text-sm font-black text-amber-500">{rec.amount.toLocaleString()} <span className="text-[10px] text-gray-500 font-bold tracking-tighter">USDC</span></div>
                </td>
                <td className="px-6 py-5">
                  <div className="text-[10px] text-gray-500 font-mono font-bold">{rec.time}</div>
                </td>
                {mainTab === 'WITHDRAW' && (
                  <td className="px-6 py-5">
                    <div className="flex items-center justify-end space-x-4">
                      {withdrawTab === 'PENDING' ? (
                        <>
                          <div className="flex flex-col items-end">
                            <div className="flex items-center space-x-2 mb-1.5">
                               {(sigs[(rec as any).id] || 0) > 0 && (
                                 <button 
                                   onClick={() => handleResetSigs((rec as any).id)}
                                   className="p-1 hover:bg-amber-500/20 text-amber-500 rounded transition-colors"
                                   title="Reset Signatures"
                                 >
                                   <RotateCcw className="w-3 h-3" />
                                 </button>
                               )}
                               <span className="text-[10px] text-gray-500 uppercase font-black tracking-tighter">
                                {t.funds.table.sigStatus}: {sigs[(rec as any).id] || 0}/2
                               </span>
                            </div>
                            <div className="w-20 h-1.5 bg-gray-800 rounded-full overflow-hidden shadow-inner">
                              <div 
                                className={`h-full transition-all duration-700 shadow-sm ${(sigs[(rec as any).id] || 0) >= 2 ? 'bg-green-500 shadow-green-500/50' : 'bg-amber-500 shadow-amber-500/50'}`} 
                                style={{ width: `${((sigs[(rec as any).id] || 0) / 2) * 100}%` }}
                              />
                            </div>
                          </div>
                          <div className="flex space-x-2">
                            <button 
                              onClick={() => handleApprove((rec as any).id)}
                              disabled={signingId === (rec as any).id || (sigs[(rec as any).id] || 0) >= 2}
                              className={`px-3 py-1.5 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all flex items-center
                                ${(sigs[(rec as any).id] || 0) >= 2 
                                  ? 'bg-green-500/10 border-green-500/30 text-green-500 cursor-default' 
                                  : 'bg-amber-500/10 border-amber-500/30 text-amber-500 hover:bg-amber-500/20 active:scale-95'}
                              `}
                            >
                              {signingId === (rec as any).id ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <Shield className="w-3 h-3 mr-1" />}
                              {t.funds.table.approve}
                            </button>
                            <button 
                              onClick={() => setRejectModal({ id: (rec as any).id, uid: rec.uid })}
                              className="p-1.5 rounded-xl border border-red-900/30 text-red-500 hover:bg-red-500/10 active:scale-95 transition-all"
                            >
                              <XCircle className="w-4 h-4" />
                            </button>
                          </div>
                        </>
                      ) : (
                        <div className="flex items-center space-x-2">
                           {withdrawTab === 'COMPLETED' && <CheckCircle className="w-4 h-4 text-green-500" />}
                           {withdrawTab === 'PROCESSING' && <Clock className="w-4 h-4 text-blue-500 animate-pulse" />}
                           {withdrawTab === 'REJECTED' && <XCircle className="w-4 h-4 text-red-500" />}
                           {withdrawTab === 'FAILED' && <AlertCircle className="w-4 h-4 text-gray-500" />}
                           <span className={`text-[10px] font-black uppercase tracking-widest ${
                             withdrawTab === 'COMPLETED' ? 'text-green-500' :
                             withdrawTab === 'PROCESSING' ? 'text-blue-500' :
                             withdrawTab === 'REJECTED' ? 'text-red-500' :
                             withdrawTab === 'FAILED' ? 'text-gray-500' : ''
                           }`}>
                             {t.funds.statusText[withdrawTab.toLowerCase() as keyof typeof t.funds.statusText]}
                           </span>
                        </div>
                      )}
                    </div>
                  </td>
                )}
              </tr>
            )) : (
              <tr>
                <td colSpan={mainTab === 'WITHDRAW' ? 7 : 6} className="px-6 py-20 text-center">
                   <div className="flex flex-col items-center justify-center opacity-20">
                     <Coins className="w-16 h-16 mb-4" />
                     <p className="text-sm font-black uppercase tracking-widest">{t.common.noData}</p>
                   </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Reject Confirmation Modal */}
      {rejectModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setRejectModal(null)} />
          <div className="relative w-full max-w-sm bg-gray-900 border border-gray-800 rounded-[32px] shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <div className="flex flex-col items-center text-center space-y-4">
              <div className="p-4 rounded-3xl bg-red-500/10 text-red-500">
                 <AlertTriangle className="w-10 h-10" />
              </div>
              <div className="space-y-2">
                <h3 className="text-xl font-bold text-white">{t.funds.modals.rejectTitle}</h3>
                <p className="text-sm text-gray-400">
                  {t.funds.modals.rejectDesc.replace('{id}', rejectModal.id).replace('{uid}', rejectModal.uid)}
                </p>
              </div>
            </div>
            <div className="flex space-x-3 mt-8">
              <button 
                onClick={() => setRejectModal(null)}
                className="flex-1 px-4 py-3 bg-gray-800/60 hover:bg-gray-700/60 rounded-2xl text-sm font-bold text-gray-300 transition-all border border-gray-700"
              >
                {t.common.cancel}
              </button>
              <button 
                onClick={handleRejectConfirm}
                className="flex-1 px-4 py-3 rounded-2xl text-sm font-bold text-white bg-red-500 hover:bg-red-600 transition-all shadow-lg shadow-red-900/20"
              >
                {t.common.confirm}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FundRecords;

import React, { useState, useMemo } from 'react';
import { Coins, Plus, Edit2, Settings, Shield, Loader2, Save, X, Image as ImageIcon, Search, RotateCcw } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface ContractItem {
  id: string;
  name: string;
  symbol: string;
  icon: string;
}

interface ParamState {
  maxLeverage: string;
  minOrderQty: string;
  minNotional: string;
  maxMarketQty: string;
  maxLimitQty: string;
  maxOpenOrders: string;
  minOrderPrice: string;
  minPriceFluc: string;
  marketPriceCap: string;
  limitPriceUpper: string;
  limitPriceLower: string;
}

const DEFAULT_PARAMS: ParamState = {
  maxLeverage: '20',
  minOrderQty: '0.001',
  minNotional: '5',
  maxMarketQty: '10',
  maxLimitQty: '10',
  maxOpenOrders: '200',
  minOrderPrice: '0.01',
  minPriceFluc: '0.01',
  marketPriceCap: '3',
  limitPriceUpper: '3',
  limitPriceLower: '3',
};

const ContractManager: React.FC = () => {
  const { t, showTip } = useLanguage();

  const [contracts, setContracts] = useState<ContractItem[]>([
    { id: 'T001', name: '黄金', symbol: 'XAU', icon: 'https://cdn-icons-png.flaticon.com/512/2992/2992742.png' },
    { id: 'T002', name: '比特币', symbol: 'BTC', icon: 'https://cryptologos.cc/logos/bitcoin-btc-logo.svg' },
  ]);

  const [searchQuery, setSearchQuery] = useState('');
  const [modal, setModal] = useState<{ open: boolean, type: 'ADD' | 'EDIT' | 'PARAMS', selectedId?: string }>({ open: false, type: 'ADD' });
  const [form, setForm] = useState({ name: '', symbol: '', icon: '' });
  const [formErrors, setFormErrors] = useState({ name: false, symbol: false });

  // Params State
  const [paramValues, setParamValues] = useState<ParamState>(DEFAULT_PARAMS);

  // Multi-sig state simulation
  const [sigCount, setSigCount] = useState(0);
  const [isSigning, setIsSigning] = useState(false);

  const openModal = (type: 'ADD' | 'EDIT' | 'PARAMS', id?: string) => {
    const item = contracts.find(c => c.id === id);
    if (item && (type === 'EDIT' || type === 'PARAMS')) {
      setForm({ name: item.name, symbol: item.symbol, icon: item.icon });
    } else {
      setForm({ name: '', symbol: '', icon: '' });
    }
    setFormErrors({ name: false, symbol: false });
    setSigCount(0);
    setModal({ open: true, type, selectedId: id });
  };

  const handleSaveInfo = () => {
    const errors = {
      name: !form.name.trim(),
      symbol: !form.symbol.trim()
    };
    setFormErrors(errors);

    if (errors.name || errors.symbol) return;

    if (modal.type === 'ADD') {
      const newId = `T00${contracts.length + 1}`;
      setContracts([...contracts, { ...form, id: newId }]);
      showTip(t.tips.contractAdded, 'success');
    } else if (modal.type === 'EDIT') {
      setContracts(contracts.map(c => c.id === modal.selectedId ? { ...c, ...form } : c));
      showTip(t.tips.contractUpdated, 'success');
    }
    setModal({ ...modal, open: false });
  };

  const handleRestoreDefaults = () => {
    setParamValues(DEFAULT_PARAMS);
  };

  const handleResetSigs = () => {
    setSigCount(0);
    showTip(t.tips.progressReset, 'info');
  };

  const isParamsValid = useMemo(() => {
    return Object.values(paramValues).every(val => val.toString().trim() !== '');
  }, [paramValues]);

  const simulateSigning = () => {
    if (!isParamsValid) return;

    setIsSigning(true);
    setTimeout(() => {
      const newCount = Math.min(sigCount + 1, 2);
      setSigCount(newCount);
      setIsSigning(false);

      if (newCount === 2) {
          showTip(t.tips.paramsMultiSigComplete, 'success');
      } else {
          showTip(t.tips.paramsSigRecorded.replace('{sigs}', newCount.toString()), 'info');
      }
    }, 1200);
  };

  const handleCommitParams = () => {
    if (sigCount >= 2) {
      setModal({ ...modal, open: false });
    }
  };

  const filteredContracts = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return contracts;
    return contracts.filter(c => 
      c.name.toLowerCase().includes(query) || 
      c.symbol.toLowerCase().includes(query)
    );
  }, [contracts, searchQuery]);

  const paramConfigList = [
    { key: 'maxLeverage', label: t.contract.params.maxLeverage, unit: t.contract.params.units.times, desc: t.contract.params.desc.maxLeverage },
    { key: 'minOrderQty', label: t.contract.params.minOrderQty, unit: form.symbol, desc: t.contract.params.desc.minOrderQty },
    { key: 'minNotional', label: t.contract.params.minNotional, unit: 'USDC', desc: t.contract.params.desc.minNotional },
    { key: 'maxMarketQty', label: t.contract.params.maxMarketQty, unit: form.symbol, desc: t.contract.params.desc.maxMarketQty },
    { key: 'maxLimitQty', label: t.contract.params.maxLimitQty, unit: form.symbol, desc: t.contract.params.desc.maxLimitQty },
    { key: 'maxOpenOrders', label: t.contract.params.maxOpenOrders, unit: t.contract.params.units.count, desc: t.contract.params.desc.maxOpenOrders },
    { key: 'minOrderPrice', label: t.contract.params.minOrderPrice, unit: 'USDC', desc: t.contract.params.desc.minOrderPrice },
    { key: 'minPriceFluc', label: t.contract.params.minPriceFluc, unit: 'USDC', desc: t.contract.params.desc.minOrderPrice },
    { key: 'marketPriceCap', label: t.contract.params.marketPriceCap, unit: t.contract.params.units.pct, desc: t.contract.params.desc.marketPriceCap },
    { key: 'limitPriceUpper', label: t.contract.params.limitPriceUpper, unit: t.contract.params.units.pct, desc: t.contract.params.desc.limitPriceUpper },
    { key: 'limitPriceLower', label: t.contract.params.limitPriceLower, unit: t.contract.params.units.pct, desc: t.contract.params.desc.limitPriceLower },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center tracking-tight">
            <Coins className="w-6 h-6 mr-3 text-amber-500" />
            {t.contract.title}
          </h1>
          <p className="text-gray-400 text-sm">{t.contract.subtitle}</p>
        </div>
        <div className="flex w-full md:w-auto space-x-3">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-500" />
            <input 
              type="text" 
              placeholder={t.common.search}
              className="w-full bg-gray-900 border border-gray-800 rounded-xl py-2 pl-10 pr-4 text-sm text-gray-300 outline-none focus:border-amber-500/50 transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            onClick={() => openModal('ADD')}
            className="bg-amber-500 hover:bg-amber-600 text-white px-6 py-2 rounded-xl font-bold flex items-center shadow-lg shadow-amber-900/20 transition-all whitespace-nowrap"
          >
            <Plus className="w-4 h-4 mr-2" />
            {t.contract.addBtn}
          </button>
        </div>
      </div>

      <div className="bg-gray-900/40 border border-gray-800 rounded-3xl overflow-hidden shadow-2xl">
        <table className="w-full text-left">
          <thead className="bg-gray-800/50 text-gray-400 text-[10px] font-black uppercase tracking-widest">
            <tr>
              <th className="px-6 py-5">{t.contract.table.icon}</th>
              <th className="px-6 py-5">{t.contract.table.id}</th>
              <th className="px-6 py-5">{t.contract.table.name}</th>
              <th className="px-6 py-5">{t.contract.table.symbol}</th>
              <th className="px-6 py-5">{t.contract.table.pair}</th>
              <th className="px-6 py-5 text-right">{t.common.action}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-800/50">
            {filteredContracts.length > 0 ? filteredContracts.map(item => (
              <tr key={item.id} className="hover:bg-amber-500/[0.01] transition-all group">
                <td className="px-6 py-5">
                  <div className="w-10 h-10 rounded-xl bg-gray-800 p-2 flex items-center justify-center border border-gray-700 group-hover:border-amber-500/50 transition-colors">
                    <img src={item.icon || 'https://cdn-icons-png.flaticon.com/512/2992/2992742.png'} alt={item.symbol} className="w-full h-full object-contain" />
                  </div>
                </td>
                <td className="px-6 py-5 text-sm font-mono text-gray-500">{item.id}</td>
                <td className="px-6 py-5 text-sm font-bold text-white">{item.name}</td>
                <td className="px-6 py-5 text-sm font-black text-amber-500">{item.symbol}</td>
                <td className="px-6 py-5 text-sm font-bold text-gray-300">{item.symbol}USDC</td>
                <td className="px-6 py-5">
                  <div className="flex justify-end space-x-2">
                    <button 
                      onClick={() => openModal('EDIT', item.id)}
                      className="p-2 text-gray-400 hover:text-amber-500 bg-gray-800/50 hover:bg-amber-500/10 rounded-xl transition-all border border-gray-800 hover:border-amber-500/30"
                      title={t.contract.editBtn}
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => openModal('PARAMS', item.id)}
                      className="p-2 text-gray-400 hover:text-blue-500 bg-gray-800/50 hover:bg-blue-500/10 rounded-xl transition-all border border-gray-800 hover:border-blue-500/30"
                      title={t.contract.setParams}
                    >
                      <Settings className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            )) : (
              <tr>
                <td colSpan={6} className="px-6 py-20 text-center opacity-30">
                  <div className="flex flex-col items-center">
                    <X className="w-10 h-10 mb-2" />
                    <span className="text-sm font-bold uppercase tracking-widest">{t.common.noData}</span>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {(modal.open && (modal.type === 'ADD' || modal.type === 'EDIT')) && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setModal({ ...modal, open: false })} />
          <div className="relative w-full max-w-md bg-gray-900 border border-gray-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-6">
              {modal.type === 'ADD' ? t.contract.modals.addTitle : t.contract.modals.editTitle}
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">{t.contract.modals.uploadIcon}</label>
                <div className="flex items-center space-x-4">
                  <div className="w-16 h-16 rounded-2xl bg-gray-800 border-2 border-dashed border-gray-700 flex items-center justify-center text-gray-600 hover:border-amber-500/50 transition-colors cursor-pointer overflow-hidden">
                    {form.icon ? <img src={form.icon} className="w-full h-full object-contain" /> : <ImageIcon className="w-6 h-6" />}
                  </div>
                  <input 
                    type="text" 
                    placeholder="URL: https://..." 
                    className="flex-1 bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-sm text-gray-200 outline-none focus:border-amber-500 transition-all"
                    value={form.icon}
                    onChange={e => setForm({...form, icon: e.target.value})}
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">{t.contract.modals.name} <span className="text-red-500">*</span></label>
                <input 
                  type="text" 
                  className={`w-full bg-gray-800 border ${formErrors.name ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl px-4 py-2.5 text-sm text-gray-200 outline-none focus:border-amber-500 transition-all`}
                  value={form.name}
                  onChange={e => {
                    setForm({...form, name: e.target.value});
                    if (formErrors.name && e.target.value.trim()) setFormErrors({...formErrors, name: false});
                  }}
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">{t.contract.modals.symbol} <span className="text-red-500">*</span></label>
                <input 
                  type="text" 
                  className={`w-full bg-gray-800 border ${formErrors.symbol ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl px-4 py-2.5 text-sm font-black text-amber-500 uppercase outline-none focus:border-amber-500 transition-all`}
                  value={form.symbol}
                  onChange={e => {
                    setForm({...form, symbol: e.target.value});
                    if (formErrors.symbol && e.target.value.trim()) setFormErrors({...formErrors, symbol: false});
                  }}
                />
              </div>
            </div>
            <div className="flex space-x-3 mt-8">
              <button 
                onClick={() => setModal({ ...modal, open: false })}
                className="flex-1 px-4 py-3 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm font-bold text-gray-300 transition-all"
              >
                {t.common.cancel}
              </button>
              <button 
                onClick={handleSaveInfo}
                className="flex-1 px-4 py-3 bg-amber-500 hover:bg-amber-600 rounded-xl text-sm font-bold text-white shadow-lg shadow-amber-900/40"
              >
                {t.common.confirm}
              </button>
            </div>
          </div>
        </div>
      )}

      {(modal.open && modal.type === 'PARAMS') && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setModal({ ...modal, open: false })} />
          <div className="relative w-full max-w-6xl bg-gray-900 border border-gray-800 rounded-[40px] shadow-2xl p-8 animate-in slide-in-from-bottom-8 duration-300 overflow-hidden">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h3 className="text-2xl font-black text-white flex items-center">
                  <Settings className="w-6 h-6 mr-3 text-blue-500" />
                  {t.contract.modals.paramsTitle} - {form.symbol}USDC
                </h3>
                <p className="text-gray-500 text-sm mt-1">{t.contract.subtitle}</p>
              </div>
              <div className="flex items-center space-x-2">
                <button 
                  onClick={handleRestoreDefaults}
                  className="flex items-center space-x-2 px-3 py-1.5 bg-gray-800 hover:bg-gray-700 border border-gray-700 rounded-xl text-[10px] font-black uppercase text-gray-400 hover:text-white transition-all"
                >
                  <RotateCcw className="w-3.5 h-3.5" />
                  <span>{t.params.restoreDefaults}</span>
                </button>
                <button onClick={() => setModal({ ...modal, open: false })} className="p-2 hover:bg-gray-800 rounded-full transition-colors">
                  <X className="w-6 h-6 text-gray-500" />
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-x-6 gap-y-4 max-h-[55vh] overflow-y-auto pr-4 custom-scrollbar">
              {paramConfigList.map((p) => (
                <div key={p.key} className="space-y-1.5 p-3 bg-gray-800/20 rounded-2xl border border-gray-800/50 transition-all">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest truncate">{p.label}</label>
                    <span className="text-[9px] font-bold text-gray-600 uppercase flex-shrink-0 ml-2">{p.unit}</span>
                  </div>
                  <input 
                    type="text" 
                    value={paramValues[p.key as keyof ParamState]}
                    onChange={(e) => setParamValues({...paramValues, [p.key]: e.target.value})}
                    placeholder="..."
                    className={`w-full bg-gray-950 border ${paramValues[p.key as keyof ParamState].toString().trim() === '' ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.25)]' : 'border-gray-800'} rounded-xl px-4 py-2 text-sm font-bold text-white outline-none focus:border-blue-500 transition-all`}
                  />
                  <p className="text-[9px] text-gray-600 leading-tight px-1 line-clamp-2" title={p.desc}>{p.desc}</p>
                </div>
              ))}
            </div>

            <div className="mt-8 pt-6 border-t border-gray-800 flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex items-center space-x-8">
                <div className="flex flex-col">
                  <div className="flex items-center space-x-2 mb-2">
                    <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{t.contract.modals.pendingSigs}</span>
                    {sigCount > 0 && (
                      <button onClick={handleResetSigs} className="p-1 hover:bg-white/5 rounded transition-colors text-blue-500" title="Reset Progress">
                        <RotateCcw className="w-3 h-3" />
                      </button>
                    )}
                  </div>
                  <div className="flex space-x-2">
                    {[1, 2].map(n => (
                      <div key={n} className={`w-8 h-8 rounded-lg border flex items-center justify-center transition-all ${sigCount >= n ? 'bg-green-500/20 border-green-500 text-green-500' : 'bg-gray-800 border-gray-700 text-gray-600'}`}>
                        {sigCount >= n ? <Shield className="w-4 h-4" /> : <Shield className="w-4 h-4 opacity-20" />}
                      </div>
                    ))}
                  </div>
                </div>
                <div className="text-xs text-gray-500 font-medium max-w-[180px]">
                  {t.contract.modals.sigRequired}
                </div>
              </div>

              <div className="flex space-x-4 w-full md:w-auto">
                <button 
                  onClick={simulateSigning}
                  disabled={isSigning || sigCount >= 2 || !isParamsValid}
                  className={`flex-1 md:flex-none px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center
                    ${sigCount >= 2 ? 'bg-gray-800 text-gray-500 cursor-default' : 
                      (!isParamsValid ? 'bg-gray-900 border border-red-500/30 text-gray-600 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-900/20 active:scale-95')}
                  `}
                >
                  {isSigning ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Shield className="w-4 h-4 mr-2" />}
                  {t.contract.modals.sign}
                </button>
                <button 
                  onClick={handleCommitParams}
                  disabled={sigCount < 2}
                  className={`flex-1 md:flex-none px-8 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all
                    ${sigCount < 2 ? 'bg-gray-800 text-gray-700 cursor-not-allowed' : 'bg-green-500 hover:bg-green-400 text-white shadow-xl shadow-green-900/20 active:scale-95'}
                  `}
                >
                   {t.contract.modals.submit}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ContractManager;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  ShieldCheck, 
  Settings, 
  AlertTriangle, 
  ToggleLeft, 
  ToggleRight, 
  Save, 
  Loader2, 
  CheckCircle,
  Database,
  Globe,
  Coins,
  Percent,
  ArrowRightLeft,
  Users,
  RotateCcw
} from 'lucide-react';
import { useLanguage } from '../LanguageContext';

type TabType = 'ON_CHAIN' | 'OFF_CHAIN';

interface OnChainParams {
  vaultDepositArb: boolean;
  vaultWithdrawArb: boolean;
  liqPenaltyRatio: string;
  insFundSplit: string;
  keeperSplit: string;
}

interface OffChainParams {
  globalTrading: boolean;
  regSwitch: boolean;
  mmrRatio: string;
  fundingCap: string;
  maxUserPos: string;
  makerFee: string;
  takerFee: string;
  interestRate: string;
  fundingFreq: string;
  orderFreqLimit: string;
}

const ON_CHAIN_DEFAULTS: OnChainParams = {
  vaultDepositArb: true,
  vaultWithdrawArb: true,
  liqPenaltyRatio: '10',
  insFundSplit: '50',
  keeperSplit: '50',
};

const OFF_CHAIN_DEFAULTS: OffChainParams = {
  globalTrading: true,
  regSwitch: true,
  mmrRatio: '50',
  fundingCap: '0.05',
  maxUserPos: '200',
  makerFee: '0.010',
  takerFee: '0.035',
  interestRate: '0.01',
  fundingFreq: '1',
  orderFreqLimit: '1000',
};

const ContractSettings: React.FC = () => {
  const { t, showTip } = useLanguage();
  const [activeTab, setActiveTab] = useState<TabType>('ON_CHAIN');

  // Multi-sig states
  const [onChainSigs, setOnChainSigs] = useState(0);
  const [offChainSigs, setOffChainSigs] = useState(0);
  const [isSigning, setIsSigning] = useState(false);

  // Form states
  const [onChainForm, setOnChainForm] = useState<OnChainParams>(ON_CHAIN_DEFAULTS);
  const [offChainForm, setOffChainForm] = useState<OffChainParams>(OFF_CHAIN_DEFAULTS);

  const isOnChainValid = useMemo(() => {
    return Object.values(onChainForm).every(val => val.toString().trim() !== '');
  }, [onChainForm]);

  const isOffChainValid = useMemo(() => {
    return Object.values(offChainForm).every(val => val.toString().trim() !== '');
  }, [offChainForm]);

  const handleSign = () => {
    const isValid = activeTab === 'ON_CHAIN' ? isOnChainValid : isOffChainValid;
    if (!isValid) return;

    setIsSigning(true);
    setTimeout(() => {
      if (activeTab === 'ON_CHAIN') {
        const nextSigs = onChainSigs + 1;
        if (nextSigs >= 2) {
          setOnChainSigs(0);
          showTip(t.tips.globalParamsUpdated, "success");
        } else {
          setOnChainSigs(nextSigs);
          showTip(t.tips.paramsSigRecorded.replace('{sigs}', nextSigs.toString()), "info");
        }
      } else {
        const nextSigs = offChainSigs + 1;
        if (nextSigs >= 2) {
            setOffChainSigs(0);
            showTip(t.tips.globalParamsUpdated, "success");
        } else {
            setOffChainSigs(nextSigs);
            showTip(t.tips.paramsSigRecorded.replace('{sigs}', nextSigs.toString()), "info");
        }
      }
      setIsSigning(false);
    }, 1000);
  };

  const handleResetProgress = () => {
    if (activeTab === 'ON_CHAIN') setOnChainSigs(0);
    else setOffChainSigs(0);
    showTip(t.tips.progressReset, "info");
  };

  const handleRestoreDefaults = () => {
    if (activeTab === 'ON_CHAIN') {
      setOnChainForm(ON_CHAIN_DEFAULTS);
      setOnChainSigs(0);
    } else {
      setOffChainForm(OFF_CHAIN_DEFAULTS);
      setOffChainSigs(0);
    }
    showTip(t.tips.success, "info");
  };

  const Switch = ({ active, onClick, label, disabled }: { active: boolean, onClick: () => void, label: string, disabled?: boolean }) => (
    <div className={`flex items-center justify-between p-4 bg-gray-900/60 border border-gray-800 rounded-xl transition-all ${disabled ? 'opacity-50' : 'hover:border-amber-500/30'}`}>
      <span className="text-sm font-bold text-gray-400 uppercase tracking-tight">{label}</span>
      <button onClick={onClick} disabled={disabled} className="focus:outline-none">
        {active 
          ? <ToggleRight className="w-10 h-10 text-amber-500" /> 
          : <ToggleLeft className="w-10 h-10 text-gray-600" />
        }
      </button>
    </div>
  );

  const InputField = ({ label, value, onChange, unit, desc, disabled }: { label: string, value: string, onChange: (v: string) => void, unit?: string, desc?: string, disabled?: boolean }) => {
    const isEmpty = value.toString().trim() === '';
    return (
      <div className={`space-y-1.5 p-4 bg-gray-900/40 border ${isEmpty ? 'border-red-500/50 shadow-[0_0_8px_rgba(239,68,68,0.15)]' : 'border-gray-800'} rounded-xl group transition-all ${disabled ? 'opacity-50' : 'hover:border-blue-500/30'}`}>
        <div className="flex justify-between items-center">
          <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{label}</label>
          {unit && <span className="text-[9px] font-bold text-gray-600 uppercase">{unit}</span>}
        </div>
        <input 
          type="text" 
          value={value}
          disabled={disabled}
          onChange={(e) => onChange(e.target.value)}
          className={`w-full bg-gray-950 border ${isEmpty ? 'border-red-500' : 'border-gray-800'} rounded-lg px-3 py-2 text-sm font-bold text-white outline-none focus:border-amber-500 transition-all`}
        />
        {desc && <p className="text-[9px] text-gray-600 leading-tight italic">{desc}</p>}
      </div>
    );
  };

  const curSigs = activeTab === 'ON_CHAIN' ? onChainSigs : offChainSigs;
  const isCurrentFormValid = activeTab === 'ON_CHAIN' ? isOnChainValid : isOffChainValid;

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20 relative">

      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h1 className="text-3xl font-black text-white flex items-center">
            <Settings className="w-8 h-8 mr-3 text-amber-500" />
            {t.params.title}
          </h1>
          <p className="text-gray-400 mt-1">{t.params.subtitle}</p>
        </div>

        <div className="flex bg-gray-900 border border-gray-800 p-1.5 rounded-2xl shadow-inner">
          <button 
            onClick={() => setActiveTab('ON_CHAIN')}
            className={`flex items-center px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'ON_CHAIN' ? 'bg-amber-500 text-white shadow-lg shadow-amber-900/40' : 'text-gray-500 hover:text-gray-300'}`}
          >
            <Database className="w-3.5 h-3.5 mr-2" />
            {t.params.onChainTab}
          </button>
          <button 
            onClick={() => setActiveTab('OFF_CHAIN')}
            className={`flex items-center px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'OFF_CHAIN' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'text-gray-500 hover:text-gray-300'}`}
          >
            <Globe className="w-3.5 h-3.5 mr-2" />
            {t.params.offChainTab}
          </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-4 items-stretch">
        <div className="flex-1 bg-red-900/10 border border-red-900/30 p-5 rounded-3xl flex items-start space-x-4 shadow-sm">
          <AlertTriangle className="w-6 h-6 text-red-500 flex-shrink-0 mt-0.5" />
          <div className="text-sm">
            <p className="font-black text-red-500 uppercase tracking-tight mb-1">{t.params.warningTitle}</p>
            <p className="text-red-400/80 leading-relaxed">{t.params.warningDesc}</p>
          </div>
        </div>
        <button 
          onClick={handleRestoreDefaults}
          className="lg:w-48 flex flex-col items-center justify-center p-5 bg-gray-900 border border-gray-800 hover:border-amber-500/50 rounded-3xl group transition-all"
        >
          <RotateCcw className="w-6 h-6 text-gray-500 group-hover:text-amber-500 mb-2 transition-colors" />
          <span className="text-[10px] font-black uppercase text-gray-500 group-hover:text-white tracking-widest">{t.params.restoreDefaults}</span>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
