  const { t, showTip } = useLanguage();

  const [contracts, setContracts] = useState<ContractItem[]>([
    { id: 'T001', name: '黄金', symbol: 'XAU', icon: 'https://cdn-icons-png.flaticon.com/512/2992/2992742.png' },
    { id: 'T002', name: '比特币', symbol: 'BTC', icon: 'https://cryptologos.cc/logos/bitcoin-btc-logo.svg' },
  ]);

  const [searchQuery, setSearchQuery] = useState('');
  const [modal, setModal] = useState<{ open: boolean, type: 'ADD' | 'EDIT' | 'PARAMS', selectedId?: string }>({ open: false, type: 'ADD' });
  const [form, setForm] = useState({ name: '', symbol: '', icon: '' });
  const [formErrors, setFormErrors] = useState({ name: false, symbol: false });

  // Params State
  const [paramValues, setParamValues] = useState<ParamState>(DEFAULT_PARAMS);

  // Multi-sig state simulation
  const [sigCount, setSigCount] = useState(0);
  const [isSigning, setIsSigning] = useState(false);

  const openModal = (type: 'ADD' | 'EDIT' | 'PARAMS', id?: string) => {
    const item = contracts.find(c => c.id === id);
    if (item && (type === 'EDIT' || type === 'PARAMS')) {
      setForm({ name: item.name, symbol: item.symbol, icon: item.icon });
    } else {
      setForm({ name: '', symbol: '', icon: '' });
    }
    setFormErrors({ name: false, symbol: false });
    setSigCount(0);
    setModal({ open: true, type, selectedId: id });
  };

  const handleSaveInfo = () => {
    const errors = {
      name: !form.name.trim(),
      symbol: !form.symbol.trim()
    };
    setFormErrors(errors);

    if (errors.name || errors.symbol) return;

    if (modal.type === 'ADD') {
      const newId = `T00${contracts.length + 1}`;
      setContracts([...contracts, { ...form, id: newId }]);
      showTip(t.tips.contractAdded, 'success');
    } else if (modal.type === 'EDIT') {
      setContracts(contracts.map(c => c.id === modal.selectedId ? { ...c, ...form } : c));
      showTip(t.tips.contractUpdated, 'success');
    }
    setModal({ ...modal, open: false });
  };

  const handleRestoreDefaults = () => {
    setParamValues(DEFAULT_PARAMS);
    showTip(t.tips.success, 'info');
  };

  const handleResetSigs = () => {
    setSigCount(0);
    showTip(t.tips.progressReset, 'info');
  };

  const isParamsValid = useMemo(() => {
    return Object.values(paramValues).every(val => val.toString().trim() !== '');
  }, [paramValues]);

  const simulateSigning = () => {
    if (!isParamsValid) return;

    setIsSigning(true);
    setTimeout(() => {
      const newCount = Math.min(sigCount + 1, 2);
      setSigCount(newCount);
      setIsSigning(false);

      if (newCount === 2) {
          showTip(t.tips.paramsMultiSigComplete, 'success');
          // Automatically close modal as per new requirement
          setTimeout(() => setModal(prev => ({ ...prev, open: false })), 1000);
      } else {
          showTip(t.tips.paramsSigRecorded.replace('{sigs}', newCount.toString()), 'info');
      }
    }, 1200);
  };

  const filteredContracts = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return contracts;
    return contracts.filter(c => 
      c.name.toLowerCase().includes(query) || 
      c.symbol.toLowerCase().includes(query)
    );
  }, [contracts, searchQuery]);

  const paramConfigList = [
    { key: 'maxLeverage', label: t.contract.params.maxLeverage, unit: t.contract.params.units.times, desc: t.contract.params.desc.maxLeverage },
    { key: 'minOrderQty', label: t.contract.params.minOrderQty, unit: form.symbol, desc: t.contract.params.desc.minOrderQty },
    { key: 'minNotional', label: t.contract.params.minNotional, unit: 'USDC', desc: t.contract.params.desc.minNotional },
    { key: 'maxMarketQty', label: t.contract.params.maxMarketQty, unit: form.symbol, desc: t.contract.params.desc.maxMarketQty },
    { key: 'maxLimitQty', label: t.contract.params.maxLimitQty, unit: form.symbol, desc: t.contract.params.desc.maxLimitQty },
    { key: 'maxOpenOrders', label: t.contract.params.maxOpenOrders, unit: t.contract.params.units.count, desc: t.contract.params.desc.maxOpenOrders },
    { key: 'minOrderPrice', label: t.contract.params.minOrderPrice, unit: 'USDC', desc: t.contract.params.desc.minOrderPrice },
    { key: 'minPriceFluc', label: t.contract.params.minPriceFluc, unit: 'USDC', desc: t.contract.params.desc.minOrderPrice },
    { key: 'marketPriceCap', label: t.contract.params.marketPriceCap, unit: t.contract.params.units.pct, desc: t.contract.params.desc.marketPriceCap },
    { key: 'limitPriceUpper', label: t.contract.params.limitPriceUpper, unit: t.contract.params.units.pct, desc: t.contract.params.desc.limitPriceUpper },
    { key: 'limitPriceLower', label: t.contract.params.limitPriceLower, unit: t.contract.params.units.pct, desc: t.contract.params.desc.limitPriceLower },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center tracking-tight">
            <Coins className="w-6 h-6 mr-3 text-amber-500" />
            {t.contract.title}
          </h1>
          <p className="text-gray-400 text-sm">{t.contract.subtitle}</p>
        </div>
        <div className="flex w-full md:w-auto space-x-3">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-500" />
            <input 
              type="text" 
              placeholder={t.common.search}
              className="w-full bg-gray-900 border border-gray-800 rounded-xl py-2 pl-10 pr-4 text-sm text-gray-300 outline-none focus:border-amber-500/50 transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            onClick={() => openModal('ADD')}
            className="bg-amber-500 hover:bg-amber-600 text-white px-6 py-2 rounded-xl font-bold flex items-center shadow-lg shadow-amber-900/20 transition-all whitespace-nowrap"
          >
            <Plus className="w-4 h-4 mr-2" />
            {t.contract.addBtn}
          </button>
        </div>
      </div>

      <div className="bg-gray-900/40 border border-gray-800 rounded-3xl overflow-hidden shadow-2xl">
        <table className="w-full text-left">
          <thead className="bg-gray-800/50 text-gray-400 text-[10px] font-black uppercase tracking-widest">
            <tr>
              <th className="px-6 py-5">{t.contract.table.icon}</th>
              <th className="px-6 py-5">{t.contract.table.id}</th>
              <th className="px-6 py-5">{t.contract.table.name}</th>
              <th className="px-6 py-5">{t.contract.table.symbol}</th>
              <th className="px-6 py-5">{t.contract.table.pair}</th>
              <th className="px-6 py-5 text-right">{t.common.action}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-800/50">
            {filteredContracts.length > 0 ? filteredContracts.map(item => (
              <tr key={item.id} className="hover:bg-amber-500/[0.01] transition-all group">
                <td className="px-6 py-5">
                  <div className="w-10 h-10 rounded-xl bg-gray-800 p-2 flex items-center justify-center border border-gray-700 group-hover:border-amber-500/50 transition-colors">
                    <img src={item.icon || 'https://cdn-icons-png.flaticon.com/512/2992/2992742.png'} alt={item.symbol} className="w-full h-full object-contain" />
                  </div>
                </td>
                <td className="px-6 py-5 text-sm font-mono text-gray-500">{item.id}</td>
                <td className="px-6 py-5 text-sm font-bold text-white">{item.name}</td>
                <td className="px-6 py-5 text-sm font-black text-amber-500">{item.symbol}</td>
                <td className="px-6 py-5 text-sm font-bold text-gray-300">{item.symbol}USDC</td>
                <td className="px-6 py-5">
                  <div className="flex justify-end space-x-2">
                    <button 
                      onClick={() => openModal('EDIT', item.id)}
                      className="p-2 text-gray-400 hover:text-amber-500 bg-gray-800/50 hover:bg-amber-500/10 rounded-xl transition-all border border-gray-800 hover:border-amber-500/30"
                      title={t.contract.editBtn}
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => openModal('PARAMS', item.id)}
                      className="p-2 text-gray-400 hover:text-blue-500 bg-gray-800/50 hover:bg-blue-500/10 rounded-xl transition-all border border-gray-800 hover:border-blue-500/30"
                      title={t.contract.setParams}
                    >
                      <Settings className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            )) : (
              <tr>
                <td colSpan={6} className="px-6 py-20 text-center opacity-30">
                  <div className="flex flex-col items-center">
                    <X className="w-10 h-10 mb-2" />
                    <span className="text-sm font-bold uppercase tracking-widest">{t.common.noData}</span>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {(modal.open && (modal.type === 'ADD' || modal.type === 'EDIT')) && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setModal({ ...modal, open: false })} />
          <div className="relative w-full max-w-md bg-gray-900 border border-gray-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-6">
              {modal.type === 'ADD' ? t.contract.modals.addTitle : t.contract.modals.editTitle}
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">{t.contract.modals.uploadIcon}</label>
                <div className="flex items-center space-x-4">
                  <div className="w-16 h-16 rounded-2xl bg-gray-800 border-2 border-dashed border-gray-700 flex items-center justify-center text-gray-600 hover:border-amber-500/50 transition-colors cursor-pointer overflow-hidden">
                    {form.icon ? <img src={form.icon} className="w-full h-full object-contain" /> : <ImageIcon className="w-6 h-6" />}
                  </div>
                  <input 
                    type="text" 
                    placeholder="URL: https://..." 
                    className="flex-1 bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-sm text-gray-200 outline-none focus:border-amber-500 transition-all"
                    value={form.icon}
                    onChange={e => setForm({...form, icon: e.target.value})}
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">{t.contract.modals.name} <span className="text-red-500">*</span></label>
                <input 
                  type="text" 
                  className={`w-full bg-gray-800 border ${formErrors.name ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl px-4 py-2.5 text-sm text-gray-200 outline-none focus:border-amber-500 transition-all`}
                  value={form.name}
                  onChange={e => {
                    setForm({...form, name: e.target.value});
                    if (formErrors.name && e.target.value.trim()) setFormErrors({...formErrors, name: false});
                  }}
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">{t.contract.modals.symbol} <span className="text-red-500">*</span></label>
                <input 
                  type="text" 
                  className={`w-full bg-gray-800 border ${formErrors.symbol ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl px-4 py-2.5 text-sm font-black text-amber-500 uppercase outline-none focus:border-amber-500 transition-all`}
                  value={form.symbol}
                  onChange={e => {
                    setForm({...form, symbol: e.target.value});
                    if (formErrors.symbol && e.target.value.trim()) setFormErrors({...formErrors, symbol: false});
                  }}
                />
              </div>
            </div>
            <div className="flex space-x-3 mt-8">
              <button 
                onClick={() => setModal({ ...modal, open: false })}
                className="flex-1 px-4 py-3 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm font-bold text-gray-300 transition-all"
              >
                {t.common.cancel}
              </button>
              <button 
                onClick={handleSaveInfo}
                className="flex-1 px-4 py-3 bg-amber-500 hover:bg-amber-600 rounded-xl text-sm font-bold text-white shadow-lg shadow-amber-900/40"
              >
                {t.common.confirm}
              </button>
            </div>
          </div>
        </div>
      )}

      {(modal.open && modal.type === 'PARAMS') && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setModal({ ...modal, open: false })} />
          <div className="relative w-full max-w-6xl bg-gray-900 border border-gray-800 rounded-[40px] shadow-2xl p-8 animate-in slide-in-from-bottom-8 duration-300 overflow-hidden">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h3 className="text-2xl font-black text-white flex items-center">
                  <Settings className="w-6 h-6 mr-3 text-blue-500" />
                  {t.contract.modals.paramsTitle} - {form.symbol}USDC
                </h3>
                <p className="text-gray-500 text-sm mt-1">{t.contract.subtitle}</p>
              </div>
              <div className="flex items-center space-x-2">
                <button 
                  onClick={handleRestoreDefaults}
                  className="flex items-center space-x-2 px-3 py-1.5 bg-gray-800 hover:bg-gray-700 border border-gray-700 rounded-xl text-[10px] font-black uppercase text-gray-400 hover:text-white transition-all"
                >
                  <RotateCcw className="w-3.5 h-3.5" />
                  <span>{t.params.restoreDefaults}</span>
                </button>
                <button onClick={() => setModal({ ...modal, open: false })} className="p-2 hover:bg-gray-800 rounded-full transition-colors">
                  <X className="w-6 h-6 text-gray-500" />
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-x-6 gap-y-4 max-h-[55vh] overflow-y-auto pr-4 custom-scrollbar">
              {paramConfigList.map((p) => (
                <div key={p.key} className="space-y-1.5 p-3 bg-gray-800/20 rounded-2xl border border-gray-800/50 transition-all">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest truncate">{p.label}</label>
                    <span className="text-[9px] font-bold text-gray-600 uppercase flex-shrink-0 ml-2">{p.unit}</span>
                  </div>
                  <input 
                    type="text" 
                    value={paramValues[p.key as keyof ParamState]}
                    onChange={(e) => setParamValues({...paramValues, [p.key]: e.target.value})}
                    placeholder="..."
                    className={`w-full bg-gray-950 border ${paramValues[p.key as keyof ParamState].toString().trim() === '' ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.25)]' : 'border-gray-800'} rounded-xl px-4 py-2 text-sm font-bold text-white outline-none focus:border-blue-500 transition-all`}
                  />
                  <p className="text-[9px] text-gray-600 leading-tight px-1 line-clamp-2" title={p.desc}>{p.desc}</p>
                </div>
              ))}
            </div>

            <div className="mt-8 pt-6 border-t border-gray-800 flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex items-center space-x-8">
                <div className="flex flex-col">
                  <div className="flex items-center space-x-2 mb-2">
                    <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{t.contract.modals.pendingSigs}</span>
                    {sigCount > 0 && (
                      <button onClick={handleResetSigs} className="p-1 hover:bg-white/5 rounded transition-colors text-blue-500" title="Reset Progress">
                        <RotateCcw className="w-3 h-3" />
                      </button>
                    )}
                  </div>
                  <div className="flex space-x-2">
                    {[1, 2].map(n => (
                      <div key={n} className={`w-8 h-8 rounded-lg border flex items-center justify-center transition-all ${sigCount >= n ? 'bg-green-500/20 border-green-500 text-green-500' : 'bg-gray-800 border-gray-700 text-gray-600'}`}>
                        {sigCount >= n ? <Shield className="w-4 h-4" /> : <Shield className="w-4 h-4 opacity-20" />}
                      </div>
                    ))}
                  </div>
                </div>
                <div className="text-xs text-gray-500 font-medium max-w-[180px]">
                  {t.contract.modals.sigRequired}
                </div>
              </div>

              <div className="flex space-x-4 w-full md:w-auto">
                <button 
                  onClick={simulateSigning}
                  disabled={isSigning || sigCount >= 2 || !isParamsValid}
                  className={`flex-1 md:flex-none px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center
                    ${sigCount >= 2 ? 'bg-gray-800 text-gray-500 cursor-default' : 
                      (!isParamsValid ? 'bg-gray-900 border border-red-500/30 text-gray-600 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-900/20 active:scale-95')}
                  `}
                >
                  {isSigning ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Shield className="w-4 h-4 mr-2" />}
                  {t.contract.modals.sign}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ContractManager;

import React, { useState, useMemo } from 'react';
import { UserPlus, Shield, Trash2, Edit2, ShieldAlert, X, Check, ListChecks, ShieldCheck, ChevronRight, LayoutGrid } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface Role {
  id: string;
  name: string;
  isSuper?: boolean;
  permissions: string[];
}

interface Admin {
  id: string;
  name: string;
  wallet: string;
  roleId: string;
}

interface PermissionItem {
  id: string;
  label: string;
  category: string;
}

const AdminSettings: React.FC = () => {
  const { t, showTip } = useLanguage();

  const [roles, setRoles] = useState<Role[]>([
    { id: 'role-1', name: t.admin.roles.super, isSuper: true, permissions: ['*'] },
    { id: 'role-2', name: t.admin.roles.risk, permissions: ['/dashboard', '/market', 'market:view_pos', '/risk', 'risk:recharge'] },
    { id: 'role-3', name: t.admin.roles.finance, permissions: ['/funds', 'funds:view_deposits', '/logs'] },
  ]);

  const [admins, setAdmins] = useState<Admin[]>([
    { id: '1', name: 'Root Admin', wallet: '0x71C7...d8976F', roleId: 'role-1' },
    { id: '2', name: 'Risk Lead A', wallet: '0xRisk...1111', roleId: 'role-2' },
    { id: '3', name: 'Finance Lead', wallet: '0xFin...2222', roleId: 'role-3' },
  ]);

  const [adminModal, setAdminModal] = useState<{ open: boolean, editId?: string, isSubmitted?: boolean }>({ open: false });
  const [roleModal, setRoleModal] = useState<{ open: boolean, editId?: string, isSubmitted?: boolean }>({ open: false });

  const [adminForm, setAdminForm] = useState({ name: '', wallet: '', roleId: 'role-2' });
  const [roleForm, setRoleForm] = useState<{ name: string, permissions: string[] }>({ name: '', permissions: [] });

  // Categorized Permission List for Finer Granularity
  const permissionGroups = useMemo(() => [
    {
      title: t.nav.dashboard,
      perms: [{ id: '/dashboard', label: t.common.all }]
    },
    {
      title: t.nav.admin,
      perms: [
        { id: '/admin', label: t.common.all },
        { id: 'admin:add_role', label: t.admin.addRoleBtn },
        { id: 'admin:edit_role', label: t.admin.modals.editRole },
        { id: 'admin:delete_role', label: t.tips.adminDeleted.split(' ')[0] + '角色' },
        { id: 'admin:add_admin', label: t.admin.addBtn },
        { id: 'admin:edit_admin', label: t.admin.modals.editAdmin },
        { id: 'admin:delete_admin', label: t.admin.headers.role + '撤销' },
      ]
    },
    {
      title: t.nav.market,
      perms: [
        { id: '/market', label: t.common.all },
        { id: 'market:view_pos', label: t.market.openPositions },
        { id: 'market:view_history', label: t.market.closedHistory },
      ]
    },
    {
      title: t.nav.risk,
      perms: [
        { id: '/risk', label: t.common.all },
        { id: 'risk:recharge', label: t.risk.recharge },
        { id: 'risk:withdraw', label: t.risk.withdraw },
      ]
    },
    {
      title: t.nav.alerts,
      perms: [
        { id: '/alerts', label: t.common.all },
        { id: 'alerts:ack', label: t.alerts.ack },
        { id: 'alerts:read_all', label: t.alerts.markRead },
      ]
    },
    {
      title: t.nav.users,
      perms: [
        { id: '/users', label: t.common.all },
        { id: 'users:freeze', label: t.users.freezeTitle },
        { id: 'users:unfreeze', label: t.users.unfreezeTitle },
      ]
    },
    {
      title: t.nav.funds,
      perms: [
        { id: '/funds', label: t.common.all },
        { id: 'funds:view_deposits', label: t.funds.recharge },
        { id: 'funds:view_withdrawals', label: t.funds.withdrawals },
        { id: 'funds:approve_withdraw', label: t.funds.table.approve },
      ]
    },
    {
      title: t.nav.contractManager,
      perms: [
        { id: '/contracts', label: t.common.all },
        { id: 'contracts:add', label: t.contract.addBtn },
        { id: 'contracts:edit', label: t.contract.editBtn },
        { id: 'contracts:params', label: t.contract.setParams },
      ]
    },
    {
      title: t.nav.params,
      perms: [
        { id: '/settings', label: t.common.all },
        { id: 'params:onchain_view', label: t.params.onChainTab + '查看' },
        { id: 'params:onchain_sign', label: t.params.onChainTab + '签名' },
        { id: 'params:offchain_view', label: t.params.offChainTab + '查看' },
        { id: 'params:offchain_sign', label: t.params.offChainTab + '签名' },
      ]
    },
    {
      title: t.nav.logs,
      perms: [{ id: '/logs', label: t.common.all }]
    },
  ], [t]);

  const allPermIds = useMemo(() => 
    permissionGroups.flatMap(g => g.perms.map(p => p.id)), 
  [permissionGroups]);

  const openAdminModal = (editId?: string) => {
    if (editId) {
      const admin = admins.find(a => a.id === editId);
      if (admin) setAdminForm({ name: admin.name, wallet: admin.wallet, roleId: admin.roleId });
    } else {
      setAdminForm({ name: '', wallet: '', roleId: roles[1]?.id || 'role-2' });
    }
    setAdminModal({ open: true, editId, isSubmitted: false });
  };

  const handleAdminSubmit = () => {
    setAdminModal(prev => ({ ...prev, isSubmitted: true }));
    const isValid = adminForm.name.trim() !== '' && adminForm.wallet.trim() !== '';
    if (!isValid) return;

    if (adminModal.editId) {
      setAdmins(admins.map(a => a.id === adminModal.editId ? { ...a, ...adminForm } : a));
      showTip(t.tips.adminUpdated, 'success');
    } else {
      setAdmins([...admins, { id: Math.random().toString(36).substr(2, 9), ...adminForm }]);
      showTip(t.tips.adminAdded, 'success');
    }
    setAdminModal({ open: false });
  };

  const handleDeleteAdmin = (id: string) => {
    setAdmins(admins.filter(a => a.id !== id));
    showTip(t.tips.adminDeleted, 'info');
  };

  const openRoleModal = (editId?: string) => {
    if (editId) {
      const role = roles.find(r => r.id === editId);
      if (role) setRoleForm({ name: role.name, permissions: role.permissions });
    } else {
      setRoleForm({ name: '', permissions: [] });
    }
    setRoleModal({ open: true, editId, isSubmitted: false });
  };

  const handleRoleSubmit = () => {
    setRoleModal(prev => ({ ...prev, isSubmitted: true }));
    const isValid = roleForm.name.trim() !== '' && roleForm.permissions.length > 0;
    if (!isValid) return;

    if (roleModal.editId) {
      setRoles(roles.map(r => r.id === roleModal.editId ? { ...r, ...roleForm } : r));
      showTip(t.tips.roleUpdated, 'success');
    } else {
      setRoles([...roles, { id: Math.random().toString(36).substr(2, 9), ...roleForm }]);
      showTip(t.tips.roleAdded, 'success');
    }
    setRoleModal({ open: false });
  };

  const handleDeleteRole = (id: string) => {
    setRoles(roles.filter(r => r.id !== id));
    showTip(t.tips.roleDeleted, 'info');
  };

  const togglePermission = (id: string) => {
    setRoleForm(prev => ({
      ...prev,
      permissions: prev.permissions.includes(id) 
        ? prev.permissions.filter(p => p !== id) 
        : [...prev.permissions, id]
    }));
  };

  const toggleAllPermissions = () => {
    if (roleForm.permissions.length === allPermIds.length) {
      setRoleForm(prev => ({ ...prev, permissions: [] }));
    } else {
      setRoleForm(prev => ({ ...prev, permissions: [...allPermIds] }));
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center">
            <ShieldCheck className="w-6 h-6 mr-3 text-amber-500" />
            {t.admin.title}
          </h1>
          <p className="text-gray-400">{t.admin.subtitle}</p>
        </div>
        <div className="flex space-x-3">
          <button 
            onClick={() => openRoleModal()}
            className="flex items-center space-x-2 bg-gray-800 hover:bg-gray-700 px-4 py-2 rounded-lg text-white font-semibold transition-all"
          >
            <Shield className="w-4 h-4 text-amber-500" />
            <span>{t.admin.addRoleBtn}</span>
          </button>
          <button 
            onClick={() => openAdminModal()}
            className="flex items-center space-x-2 bg-amber-500 hover:bg-amber-600 px-4 py-2 rounded-lg text-white font-semibold transition-all shadow-lg shadow-amber-900/20"
          >
            <UserPlus className="w-4 h-4" />
            <span>{t.admin.addBtn}</span>
          </button>
        </div>
      </div>

      <div className="bg-blue-900/10 border border-blue-900/30 p-4 rounded-xl flex items-start space-x-3">
        <ShieldAlert className="w-5 h-5 text-blue-500 flex-shrink-0 mt-0.5" />
        <div className="text-sm text-blue-400">
          <p className="font-semibold mb-1">{t.admin.policyNote}</p>
          <p>{t.admin.policyDesc}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.activeAdmins}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-800 text-gray-400 text-xs uppercase font-bold">
                <tr>
                  <th className="px-6 py-4">{t.admin.headers.nameId}</th>
                  <th className="px-6 py-4">{t.admin.headers.wallet}</th>
                  <th className="px-6 py-4">{t.admin.headers.role}</th>
                  <th className="px-6 py-4">{t.common.action}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800">
                {admins.map((admin) => {
                  const role = roles.find(r => r.id === admin.roleId);
                  return (
                    <tr key={admin.id} className="hover:bg-gray-800/20 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-medium text-white">{admin.name}</div>
                        <div className="text-xs text-gray-500">UID: {admin.id}</div>
                      </td>
                      <td className="px-6 py-4 font-mono text-xs text-amber-500">{admin.wallet}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded text-[10px] font-bold ${role?.isSuper ? 'bg-purple-500/20 text-purple-500' : 'bg-blue-500/20 text-blue-500'}`}>
                          {role?.name || t.common.none}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {!role?.isSuper && (
                          <div className="flex space-x-3">
                            <button onClick={() => openAdminModal(admin.id)} className="text-gray-400 hover:text-amber-500 transition-colors"><Edit2 className="w-4 h-4" /></button>
                            <button onClick={() => handleDeleteAdmin(admin.id)} className="text-gray-400 hover:text-red-500 transition-colors"><Trash2 className="w-4 h-4" /></button>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.roleDefs}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl p-6 space-y-4">
            {roles.map(role => (
              <div key={role.id} className="p-4 bg-gray-800/40 rounded-xl border border-gray-800 hover:border-amber-500/50 transition-all relative group">
                <div className="flex items-center justify-between mb-2">
                  <span className={`${role.isSuper ? 'text-amber-500' : 'text-blue-500'} font-bold text-sm uppercase`}>{role.name}</span>
                  {!role.isSuper && (
                    <div className="flex space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => openRoleModal(role.id)} className="text-gray-400 hover:text-white"><Edit2 className="w-3 h-3" /></button>
                      <button onClick={() => handleDeleteRole(role.id)} className="text-gray-400 hover:text-red-500"><Trash2 className="w-3 h-3" /></button>
                    </div>
                  )}
                </div>
                <div className="flex flex-wrap gap-1 mt-2 max-h-24 overflow-y-auto custom-scroll">
                   {role.isSuper ? (
                     <span className="text-[10px] bg-amber-500/10 text-amber-500 px-1.5 py-0.5 rounded">{t.admin.allAccess}</span>
                   ) : (
                     role.permissions.map(p => {
                       const found = allPermIds.includes(p);
                       if (!found) return null;
                       const group = permissionGroups.find(g => g.perms.some(item => item.id === p));
                       const perm = group?.perms.find(item => item.id === p);
                       return (
                         <span key={p} className="text-[9px] bg-gray-700/50 text-gray-400 px-1.5 py-0.5 rounded flex items-center whitespace-nowrap">
                           {group?.title}: {perm?.label}
                         </span>
                       );
                     })
                   )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {adminModal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setAdminModal({ open: false })} />
          <div className="relative w-full max-w-md bg-gray-900 border border-gray-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-6">{adminModal.editId ? t.admin.modals.editAdmin : t.admin.modals.addAdmin}</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.name}</label>
                <input 
                  type="text" 
                  value={adminForm.name}
                  onChange={e => setAdminForm({...adminForm, name: e.target.value})}
                  className={`w-full bg-gray-800 border ${adminModal.isSubmitted && adminForm.name.trim() === '' ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl px-4 py-2.5 text-sm outline-none focus:border-amber-500 transition-all`}
                  placeholder="e.g. Satoshi"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.wallet}</label>
                <input 
                  type="text" 
                  value={adminForm.wallet}
                  onChange={e => setAdminForm({...adminForm, wallet: e.target.value})}
                  className={`w-full bg-gray-800 border ${adminModal.isSubmitted && adminForm.wallet.trim() === '' ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl px-4 py-2.5 text-sm outline-none font-mono focus:border-amber-500 transition-all`}
                  placeholder="0x..."
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.role}</label>
                <select value={adminForm.roleId} onChange={e => setAdminForm({...adminForm, roleId: e.target.value})} className="w-full bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-amber-500 transition-all appearance-none">
                  {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                </select>
              </div>
            </div>
            <div className="flex space-x-3 mt-8">
              <button onClick={() => setAdminModal({ open: false })} className="flex-1 px-4 py-2.5 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm font-bold text-gray-300 transition-all">{t.common.cancel}</button>
              <button onClick={handleAdminSubmit} className="flex-1 px-4 py-2.5 rounded-xl text-sm font-bold text-white bg-amber-500 hover:bg-amber-600 transition-all shadow-lg shadow-amber-900/20">{t.common.confirm}</button>
            </div>
          </div>
        </div>
      )}

      {roleModal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setRoleModal({ open: false })} />
          <div className="relative w-full max-w-2xl bg-gray-900 border border-gray-800 rounded-[32px] shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-xl font-bold text-white">{roleModal.editId ? t.admin.modals.editRole : t.admin.modals.addRole}</h3>
              <button onClick={toggleAllPermissions} className="flex items-center space-x-1.5 px-3 py-1.5 rounded-xl bg-gray-800 hover:bg-gray-700 text-[10px] font-black uppercase text-amber-500 transition-all">
                <ListChecks className="w-4 h-4" />
                <span>{roleForm.permissions.length === allPermIds.length ? t.admin.modals.deselectAll : t.admin.modals.selectAll}</span>
              </button>
            </div>

            <div className="space-y-6">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2 px-1">{t.admin.modals.fields.name}</label>
                <input 
                  type="text" 
                  value={roleForm.name}
                  onChange={e => setRoleForm({...roleForm, name: e.target.value})}
                  className={`w-full bg-gray-800 border ${roleModal.isSubmitted && roleForm.name.trim() === '' ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-2xl px-4 py-3 text-sm text-white outline-none focus:border-amber-500 transition-all`}
                  placeholder="e.g. Compliance Auditor"
                />
              </div>

              <div className="space-y-4 max-h-[50vh] overflow-y-auto pr-4 custom-scroll">
                {permissionGroups.map((group) => (
                  <div key={group.title} className="bg-gray-800/20 border border-gray-800 rounded-2xl p-4">
                    <h4 className="text-[10px] font-black uppercase text-gray-500 tracking-[0.2em] mb-4 flex items-center">
                      <LayoutGrid className="w-3 h-3 mr-2 text-amber-500" />
                      {group.title}
                    </h4>
                    <div className="grid grid-cols-2 gap-3">
                      {group.perms.map((perm) => (
                        <button 
                          key={perm.id} 
                          onClick={() => togglePermission(perm.id)} 
                          className={`flex items-center justify-between p-3 rounded-xl border text-left transition-all group/item
                            ${roleForm.permissions.includes(perm.id) 
                              ? 'bg-amber-500/10 border-amber-500/50 text-amber-500 shadow-[0_0_15px_rgba(245,158,11,0.05)]' 
                              : 'bg-gray-900/40 border-gray-800 text-gray-400 hover:border-gray-700 hover:text-gray-300'}
                          `}
                        >
                          <div className="flex items-center space-x-3">
                            <div className={`w-4 h-4 rounded border flex items-center justify-center transition-colors
                              ${roleForm.permissions.includes(perm.id) ? 'bg-amber-500 border-amber-500' : 'border-gray-700 group-hover/item:border-amber-500/50'}
                            `}>
                              {roleForm.permissions.includes(perm.id) && <Check className="w-3 h-3 text-white" strokeWidth={4} />}
                            </div>
                            <span className="text-xs font-bold truncate">{perm.label}</span>
                          </div>
                          {perm.id.startsWith('/') && <ChevronRight className="w-3 h-3 opacity-30" />}
                        </button>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="flex space-x-4 mt-10">
              <button onClick={() => setRoleModal({ open: false })} className="flex-1 px-4 py-3.5 bg-gray-800 hover:bg-gray-700 rounded-2xl text-sm font-bold text-gray-300 transition-all">{t.common.cancel}</button>
              <button onClick={handleRoleSubmit} className="flex-1 px-4 py-3.5 rounded-2xl text-sm font-bold text-white bg-amber-500 hover:bg-amber-600 transition-all shadow-xl shadow-amber-900/30">{t.common.confirm}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminSettings;

import React, { useState, useMemo } from 'react';
import { UserPlus, Shield, Trash2, Edit2, ShieldAlert, X, Check, ListChecks, ShieldCheck, ChevronRight, LayoutGrid } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface Role {
  id: string;
  name: string;
  isSuper?: boolean;
  permissions: string[];
}

interface Admin {
  id: string;
  name: string;
  wallet: string;
  roleId: string;
}

interface PermissionItem {
  id: string;
  label: string;
  category: string;
}

const AdminSettings: React.FC = () => {
  const { t, showTip } = useLanguage();

  const [roles, setRoles] = useState<Role[]>([
    { id: 'role-1', name: t.admin.roles.super, isSuper: true, permissions: ['*'] },
    { id: 'role-2', name: t.admin.roles.risk, permissions: ['/dashboard', '/market', 'market:view_pos', '/risk', 'risk:recharge'] },
    { id: 'role-3', name: t.admin.roles.finance, permissions: ['/funds', 'funds:view_deposits', '/logs'] },
  ]);

  const [admins, setAdmins] = useState<Admin[]>([
    { id: '1', name: 'Root Admin', wallet: '0x71C7...d8976F', roleId: 'role-1' },
    { id: '2', name: 'Risk Lead A', wallet: '0xRisk...1111', roleId: 'role-2' },
    { id: '3', name: 'Finance Lead', wallet: '0xFin...2222', roleId: 'role-3' },
  ]);

  const [adminModal, setAdminModal] = useState<{ open: boolean, editId?: string, isSubmitted?: boolean }>({ open: false });
  const [roleModal, setRoleModal] = useState<{ open: boolean, editId?: string, isSubmitted?: boolean }>({ open: false });

  const [adminForm, setAdminForm] = useState({ name: '', wallet: '', roleId: 'role-2' });
  const [roleForm, setRoleForm] = useState<{ name: string, permissions: string[] }>({ name: '', permissions: [] });

  // Categorized Permission List for Finer Granularity
  const permissionGroups = useMemo(() => [
    {
      title: t.nav.dashboard,
      perms: [{ id: '/dashboard', label: t.common.view }]
    },
    {
      title: t.nav.admin,
      perms: [
        { id: '/admin', label: t.common.view },
        { id: 'admin:add_role', label: t.admin.addRoleBtn },
        { id: 'admin:edit_role', label: t.admin.modals.editRole },
        { id: 'admin:delete_role', label: t.tips.adminDeleted.split(' ')[0] + '角色' },
        { id: 'admin:add_admin', label: t.admin.addBtn },
        { id: 'admin:edit_admin', label: t.admin.modals.editAdmin },
        { id: 'admin:delete_admin', label: t.admin.headers.role + '撤销' },
      ]
    },
    {
      title: t.nav.market,
      perms: [
        { id: '/market', label: t.common.view },
        { id: 'market:view_pos', label: t.market.openPositions },
        { id: 'market:view_history', label: t.market.closedHistory },
      ]
    },
    {
      title: t.nav.risk,
      perms: [
        { id: '/risk', label: t.common.view },
        { id: 'risk:recharge', label: t.risk.recharge },
        { id: 'risk:withdraw', label: t.risk.withdraw },
      ]
    },
    {
      title: t.nav.alerts,
      perms: [
        { id: '/alerts', label: t.common.view },
        { id: 'alerts:ack', label: t.alerts.ack },
        { id: 'alerts:read_all', label: t.alerts.markRead },
      ]
    },
    {
      title: t.nav.users,
      perms: [
        { id: '/users', label: t.common.view },
        { id: 'users:freeze', label: t.users.freezeTitle },
        { id: 'users:unfreeze', label: t.users.unfreezeTitle },
      ]
    },
    {
      title: t.nav.funds,
      perms: [
        { id: '/funds', label: t.common.view },
        { id: 'funds:view_deposits', label: t.funds.recharge },
        { id: 'funds:view_withdrawals', label: t.funds.withdrawals },
        { id: 'funds:approve_withdraw', label: t.funds.table.approve },
      ]
    },
    {
      title: t.nav.contractManager,
      perms: [
        { id: '/contracts', label: t.common.view },
        { id: 'contracts:add', label: t.contract.addBtn },
        { id: 'contracts:edit', label: t.contract.editBtn },
        { id: 'contracts:params', label: t.contract.setParams },
      ]
    },
    {
      title: t.nav.params,
      perms: [
        { id: '/settings', label: t.common.view },
        { id: 'params:onchain_view', label: t.params.onChainTab + '查看' },
        { id: 'params:onchain_sign', label: t.params.onChainTab + '签名' },
        { id: 'params:offchain_view', label: t.params.offChainTab + '查看' },
        { id: 'params:offchain_sign', label: t.params.offChainTab + '签名' },
      ]
    },
    {
      title: t.nav.logs,
      perms: [{ id: '/logs', label: t.common.view }]
    },
  ], [t]);

  const allPermIds = useMemo(() => 
    permissionGroups.flatMap(g => g.perms.map(p => p.id)), 
  [permissionGroups]);

  const openAdminModal = (editId?: string) => {
    if (editId) {
      const admin = admins.find(a => a.id === editId);
      if (admin) setAdminForm({ name: admin.name, wallet: admin.wallet, roleId: admin.roleId });
    } else {
      setAdminForm({ name: '', wallet: '', roleId: roles[1]?.id || 'role-2' });
    }
    setAdminModal({ open: true, editId, isSubmitted: false });
  };

  const handleAdminSubmit = () => {
    setAdminModal(prev => ({ ...prev, isSubmitted: true }));
    const isValid = adminForm.name.trim() !== '' && adminForm.wallet.trim() !== '';
    if (!isValid) return;

    if (adminModal.editId) {
      setAdmins(admins.map(a => a.id === adminModal.editId ? { ...a, ...adminForm } : a));
      showTip(t.tips.adminUpdated, 'success');
    } else {
      setAdmins([...admins, { id: Math.random().toString(36).substr(2, 9), ...adminForm }]);
      showTip(t.tips.adminAdded, 'success');
    }
    setAdminModal({ open: false });
  };

  const handleDeleteAdmin = (id: string) => {
    setAdmins(admins.filter(a => a.id !== id));
    showTip(t.tips.adminDeleted, 'info');
  };

  const openRoleModal = (editId?: string) => {
    if (editId) {
      const role = roles.find(r => r.id === editId);
      if (role) setRoleForm({ name: role.name, permissions: role.permissions });
    } else {
      setRoleForm({ name: '', permissions: [] });
    }
    setRoleModal({ open: true, editId, isSubmitted: false });
  };

  const handleRoleSubmit = () => {
    setRoleModal(prev => ({ ...prev, isSubmitted: true }));
    const isValid = roleForm.name.trim() !== '' && roleForm.permissions.length > 0;
    if (!isValid) return;

    if (roleModal.editId) {
      setRoles(roles.map(r => r.id === roleModal.editId ? { ...r, ...roleForm } : r));
      showTip(t.tips.roleUpdated, 'success');
    } else {
      setRoles([...roles, { id: Math.random().toString(36).substr(2, 9), ...roleForm }]);
      showTip(t.tips.roleAdded, 'success');
    }
    setRoleModal({ open: false });
  };

  const handleDeleteRole = (id: string) => {
    setRoles(roles.filter(r => r.id !== id));
    showTip(t.tips.roleDeleted, 'info');
  };

  const togglePermission = (id: string) => {
    setRoleForm(prev => ({
      ...prev,
      permissions: prev.permissions.includes(id) 
        ? prev.permissions.filter(p => p !== id) 
        : [...prev.permissions, id]
    }));
  };

  const toggleAllPermissions = () => {
    if (roleForm.permissions.length === allPermIds.length) {
      setRoleForm(prev => ({ ...prev, permissions: [] }));
    } else {
      setRoleForm(prev => ({ ...prev, permissions: [...allPermIds] }));
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center">
            <ShieldCheck className="w-6 h-6 mr-3 text-amber-500" />
            {t.admin.title}
          </h1>
          <p className="text-gray-400">{t.admin.subtitle}</p>
        </div>
        <div className="flex space-x-3">
          <button 
            onClick={() => openRoleModal()}
            className="flex items-center space-x-2 bg-gray-800 hover:bg-gray-700 px-4 py-2 rounded-lg text-white font-semibold transition-all"
          >
            <Shield className="w-4 h-4 text-amber-500" />
            <span>{t.admin.addRoleBtn}</span>
          </button>
          <button 
            onClick={() => openAdminModal()}
            className="flex items-center space-x-2 bg-amber-500 hover:bg-amber-600 px-4 py-2 rounded-lg text-white font-semibold transition-all shadow-lg shadow-amber-900/20"
          >
            <UserPlus className="w-4 h-4" />
            <span>{t.admin.addBtn}</span>
          </button>
        </div>
      </div>

      <div className="bg-blue-900/10 border border-blue-900/30 p-4 rounded-xl flex items-start space-x-3">
        <ShieldAlert className="w-5 h-5 text-blue-500 flex-shrink-0 mt-0.5" />
        <div className="text-sm text-blue-400">
          <p className="font-semibold mb-1">{t.admin.policyNote}</p>
          <p>{t.admin.policyDesc}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.activeAdmins}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-800 text-gray-400 text-xs uppercase font-bold">
                <tr>
                  <th className="px-6 py-4">{t.admin.headers.nameId}</th>
                  <th className="px-6 py-4">{t.admin.headers.wallet}</th>
                  <th className="px-6 py-4">{t.admin.headers.role}</th>
                  <th className="px-6 py-4">{t.common.action}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800">
                {admins.map((admin) => {
                  const role = roles.find(r => r.id === admin.roleId);
                  return (
                    <tr key={admin.id} className="hover:bg-gray-800/20 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-medium text-white">{admin.name}</div>
                        <div className="text-xs text-gray-500">UID: {admin.id}</div>
                      </td>
                      <td className="px-6 py-4 font-mono text-xs text-amber-500">{admin.wallet}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded text-[10px] font-bold ${role?.isSuper ? 'bg-purple-500/20 text-purple-500' : 'bg-blue-500/20 text-blue-500'}`}>
                          {role?.name || t.common.none}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {!role?.isSuper && (
                          <div className="flex space-x-3">
                            <button onClick={() => openAdminModal(admin.id)} className="text-gray-400 hover:text-amber-500 transition-colors"><Edit2 className="w-4 h-4" /></button>
                            <button onClick={() => handleDeleteAdmin(admin.id)} className="text-gray-400 hover:text-red-500 transition-colors"><Trash2 className="w-4 h-4" /></button>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.roleDefs}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl p-6 space-y-4">
            {roles.map(role => (
              <div key={role.id} className="p-4 bg-gray-800/40 rounded-xl border border-gray-800 hover:border-amber-500/50 transition-all relative group">
                <div className="flex items-center justify-between mb-2">
                  <span className={`${role.isSuper ? 'text-amber-500' : 'text-blue-500'} font-bold text-sm uppercase`}>{role.name}</span>
                  {!role.isSuper && (
                    <div className="flex space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => openRoleModal(role.id)} className="text-gray-400 hover:text-white"><Edit2 className="w-3 h-3" /></button>
                      <button onClick={() => handleDeleteRole(role.id)} className="text-gray-400 hover:text-red-500"><Trash2 className="w-3 h-3" /></button>
                    </div>
                  )}
                </div>
                <div className="flex flex-wrap gap-1 mt-2 max-h-24 overflow-y-auto custom-scroll">
                   {role.isSuper ? (
                     <span className="text-[10px] bg-amber-500/10 text-amber-500 px-1.5 py-0.5 rounded">{t.admin.allAccess}</span>
                   ) : (
                     role.permissions.map(p => {
                       const found = allPermIds.includes(p);
                       if (!found) return null;
                       const group = permissionGroups.find(g => g.perms.some(item => item.id === p));
                       const perm = group?.perms.find(item => item.id === p);
                       return (
                         <span key={p} className="text-[9px] bg-gray-700/50 text-gray-400 px-1.5 py-0.5 rounded flex items-center whitespace-nowrap">
                           {group?.title}: {perm?.label}
                         </span>
                       );
                     })
                   )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {adminModal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setAdminModal({ open: false })} />
          <div className="relative w-full max-w-md bg-gray-900 border border-gray-800 rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-6">{adminModal.editId ? t.admin.modals.editAdmin : t.admin.modals.addAdmin}</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.name}</label>
                <input 
                  type="text" 
                  value={adminForm.name}
                  onChange={e => setAdminForm({...adminForm, name: e.target.value})}
                  className={`w-full bg-gray-800 border ${adminModal.isSubmitted && adminForm.name.trim() === '' ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl px-4 py-2.5 text-sm outline-none focus:border-amber-500 transition-all`}
                  placeholder="e.g. Satoshi"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.wallet}</label>
                <input 
                  type="text" 
                  value={adminForm.wallet}
                  onChange={e => setAdminForm({...adminForm, wallet: e.target.value})}
                  className={`w-full bg-gray-800 border ${adminModal.isSubmitted && adminForm.wallet.trim() === '' ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-xl px-4 py-2.5 text-sm outline-none font-mono focus:border-amber-500 transition-all`}
                  placeholder="0x..."
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t.admin.modals.fields.role}</label>
                <select value={adminForm.roleId} onChange={e => setAdminForm({...adminForm, roleId: e.target.value})} className="w-full bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-amber-500 transition-all appearance-none">
                  {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                </select>
              </div>
            </div>
            <div className="flex space-x-3 mt-8">
              <button onClick={() => setAdminModal({ open: false })} className="flex-1 px-4 py-2.5 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm font-bold text-gray-300 transition-all">{t.common.cancel}</button>
              <button onClick={handleAdminSubmit} className="flex-1 px-4 py-2.5 rounded-xl text-sm font-bold text-white bg-amber-500 hover:bg-amber-600 transition-all shadow-lg shadow-amber-900/20">{t.common.confirm}</button>
            </div>
          </div>
        </div>
      )}

      {roleModal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setRoleModal({ open: false })} />
          <div className="relative w-full max-w-2xl bg-gray-900 border border-gray-800 rounded-[32px] shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-xl font-bold text-white">{roleModal.editId ? t.admin.modals.editRole : t.admin.modals.addRole}</h3>
              <button onClick={toggleAllPermissions} className="flex items-center space-x-1.5 px-3 py-1.5 rounded-xl bg-gray-800 hover:bg-gray-700 text-[10px] font-black uppercase text-amber-500 transition-all">
                <ListChecks className="w-4 h-4" />
                <span>{roleForm.permissions.length === allPermIds.length ? t.admin.modals.deselectAll : t.admin.modals.selectAll}</span>
              </button>
            </div>

            <div className="space-y-6">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2 px-1">{t.admin.modals.fields.name}</label>
                <input 
                  type="text" 
                  value={roleForm.name}
                  onChange={e => setRoleForm({...roleForm, name: e.target.value})}
                  className={`w-full bg-gray-800 border ${roleModal.isSubmitted && roleForm.name.trim() === '' ? 'border-red-500 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-700'} rounded-2xl px-4 py-3 text-sm text-white outline-none focus:border-amber-500 transition-all`}
                  placeholder="e.g. Compliance Auditor"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-4 px-1 tracking-widest">{t.admin.modals.fields.permissions}</label>
                <div className="space-y-4 max-h-[50vh] overflow-y-auto pr-4 custom-scroll">
                  {permissionGroups.map((group) => (
                    <div key={group.title} className="bg-gray-800/20 border border-gray-800 rounded-2xl p-4">
                      <h4 className="text-[10px] font-black uppercase text-gray-500 tracking-[0.2em] mb-4 flex items-center">
                        <LayoutGrid className="w-3 h-3 mr-2 text-amber-500" />
                        {group.title}
                      </h4>
                      <div className="grid grid-cols-2 gap-3">
                        {group.perms.map((perm) => (
                          <button 
                            key={perm.id} 
                            onClick={() => togglePermission(perm.id)} 
                            className={`flex items-center justify-between p-3 rounded-xl border text-left transition-all group/item
                              ${roleForm.permissions.includes(perm.id) 
                                ? 'bg-amber-500/10 border-amber-500/50 text-amber-500 shadow-[0_0_15px_rgba(245,158,11,0.05)]' 
                                : 'bg-gray-900/40 border-gray-800 text-gray-400 hover:border-gray-700 hover:text-gray-300'}
                            `}
                          >
                            <div className="flex items-center space-x-3">
                              <div className={`w-4 h-4 rounded border flex items-center justify-center transition-colors
                                ${roleForm.permissions.includes(perm.id) ? 'bg-amber-500 border-amber-500' : 'border-gray-700 group-hover/item:border-amber-500/50'}
                              `}>
                                {roleForm.permissions.includes(perm.id) && <Check className="w-3 h-3 text-white" strokeWidth={4} />}
                              </div>
                              <span className="text-xs font-bold truncate">{perm.label}</span>
                            </div>
                            {perm.id.startsWith('/') && <ChevronRight className="w-3 h-3 opacity-30" />}
                          </button>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex space-x-4 mt-10">
              <button onClick={() => setRoleModal({ open: false })} className="flex-1 px-4 py-3.5 bg-gray-800 hover:bg-gray-700 rounded-2xl text-sm font-bold text-gray-300 transition-all">{t.common.cancel}</button>
              <button onClick={handleRoleSubmit} className="flex-1 px-4 py-3.5 rounded-2xl text-sm font-bold text-white bg-amber-500 hover:bg-amber-600 transition-all shadow-xl shadow-amber-900/30">{t.common.confirm}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminSettings;

import React, { useState, useMemo } from 'react';
import { UserPlus, Shield, Trash2, Edit2, ShieldAlert, X, Check, ListChecks, ShieldCheck, ChevronRight, LayoutGrid } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface Role {
  id: string;
  name: string;
  isSuper?: boolean;
  permissions: string[];
}

interface Admin {
  id: string;
  name: string;
  wallet: string;
  roleId: string;
}

interface PermissionItem {
  id: string;
  label: string;
  category: string;
}

const AdminSettings: React.FC = () => {
  const { t, showTip } = useLanguage();

  const [roles, setRoles] = useState<Role[]>([
    { id: 'role-1', name: t.admin.roles.super, isSuper: true, permissions: ['*'] },
    { id: 'role-2', name: t.admin.roles.risk, permissions: ['/dashboard', '/market', 'market:view_pos', '/risk', 'risk:recharge'] },
    { id: 'role-3', name: t.admin.roles.finance, permissions: ['/funds', 'funds:view_deposits', '/logs'] },
  ]);

  const [admins, setAdmins] = useState<Admin[]>([
    { id: '1', name: 'Root Admin', wallet: '0x71C7...d8976F', roleId: 'role-1' },
    { id: '2', name: 'Risk Lead A', wallet: '0xRisk...1111', roleId: 'role-2' },
    { id: '3', name: 'Finance Lead', wallet: '0xFin...2222', roleId: 'role-3' },
  ]);

  const [adminModal, setAdminModal] = useState<{ open: boolean, editId?: string, isSubmitted?: boolean }>({ open: false });
  const [roleModal, setRoleModal] = useState<{ open: boolean, editId?: string, isSubmitted?: boolean }>({ open: false });

  const [adminForm, setAdminForm] = useState({ name: '', wallet: '', roleId: 'role-2' });
  const [roleForm, setRoleForm] = useState<{ name: string, permissions: string[] }>({ name: '', permissions: [] });

  // Categorized Permission List for Finer Granularity
  const permissionGroups = useMemo(() => [
    {
      title: t.nav.dashboard,
      perms: [{ id: '/dashboard', label: t.common.view }]
    },
    {
      title: t.nav.admin,
      perms: [
        { id: '/admin', label: t.common.view },
        { id: 'admin:add_role', label: t.admin.addRoleBtn },
        { id: 'admin:edit_role', label: t.admin.modals.editRole },
        { id: 'admin:delete_role', label: '删除角色' },
        { id: 'admin:add_admin', label: t.admin.addBtn },
        { id: 'admin:edit_admin', label: t.admin.modals.editAdmin },
        { id: 'admin:delete_admin', label: '删除管理员' },
      ]
    },
    {
      title: t.nav.market,
      perms: [
        { id: '/market', label: t.common.view },
        { id: 'market:view_pos', label: t.market.openPositions },
        { id: 'market:view_history', label: t.market.closedHistory },
      ]
    },
    {
      title: t.nav.risk,
      perms: [
        { id: '/risk', label: t.common.view },
        { id: 'risk:recharge', label: '保险基金充值' },
        { id: 'risk:withdraw', label: '保险基金提取' },
      ]
    },
    {
      title: t.nav.health,
      perms: [
        { id: '/health', label: t.common.view },
      ]
    },
    {
      title: t.nav.alerts,
      perms: [
        { id: '/alerts', label: t.common.view },
        { id: 'alerts:ack', label: t.alerts.ack },
        { id: 'alerts:read_all', label: t.alerts.markRead },
      ]
    },
    {
      title: t.nav.users,
      perms: [
        { id: '/users', label: t.common.view },
        { id: 'users:freeze', label: t.users.freezeTitle },
        { id: 'users:unfreeze', label: t.users.unfreezeTitle },
      ]
    },
    {
      title: t.nav.funds,
      perms: [
        { id: '/funds', label: t.common.view },
        { id: 'funds:view_deposits', label: t.funds.recharge },
        { id: 'funds:view_withdrawals', label: t.funds.withdrawals },
        { id: 'funds:approve_withdraw', label: '提现审核' },
      ]
    },
    {
      title: t.nav.contractManager,
      perms: [
        { id: '/contracts', label: t.common.view },
        { id: 'contracts:add', label: t.contract.addBtn },
        { id: 'contracts:edit', label: t.contract.editBtn },
        { id: 'contracts:params', label: t.contract.setParams },
      ]
    },
    {
      title: t.nav.params,
      perms: [
        { id: '/settings', label: t.common.view },
        { id: 'params:onchain_view', label: '查看链上多签参数' },
        { id: 'params:onchain_sign', label: t.params.onChainTab + '签名' },
        { id: 'params:offchain_view', label: '查看链下多签参数' },
        { id: 'params:offchain_sign', label: t.params.offChainTab + '签名' },
      ]
    },
    {
      title: t.nav.logs,
      perms: [{ id: '/logs', label: t.common.view }]
    },
  ], [t]);

  const allPermIds = useMemo(() => 
    permissionGroups.flatMap(g => g.perms.map(p => p.id)), 
  [permissionGroups]);

  const openAdminModal = (editId?: string) => {
    if (editId) {
      const admin = admins.find(a => a.id === editId);
      if (admin) setAdminForm({ name: admin.name, wallet: admin.wallet, roleId: admin.roleId });
    } else {
      setAdminForm({ name: '', wallet: '', roleId: roles[1]?.id || 'role-2' });
    }
    setAdminModal({ open: true, editId, isSubmitted: false });
  };

  const handleAdminSubmit = () => {
    setAdminModal(prev => ({ ...prev, isSubmitted: true }));
    const isValid = adminForm.name.trim() !== '' && adminForm.wallet.trim() !== '';
    if (!isValid) return;

    if (adminModal.editId) {
      setAdmins(admins.map(a => a.id === adminModal.editId ? { ...a, ...adminForm } : a));
      showTip(t.tips.adminUpdated, 'success');
    } else {
      setAdmins([...admins, { id: Math.random().toString(36).substr(2, 9), ...adminForm }]);
      showTip(t.tips.adminAdded, 'success');
    }
    setAdminModal({ open: false });
  };

  const handleDeleteAdmin = (id: string) => {
    setAdmins(admins.filter(a => a.id !== id));
    showTip(t.tips.adminDeleted, 'info');
  };

  const openRoleModal = (editId?: string) => {
    if (editId) {
      const role = roles.find(r => r.id === editId);
      if (role) setRoleForm({ name: role.name, permissions: role.permissions });
    } else {
      setRoleForm({ name: '', permissions: [] });
    }
    setRoleModal({ open: true, editId, isSubmitted: false });
  };

  const handleRoleSubmit = () => {
    setRoleModal(prev => ({ ...prev, isSubmitted: true }));
    const isValid = roleForm.name.trim() !== '' && roleForm.permissions.length > 0;
    if (!isValid) return;

    if (roleModal.editId) {
      setRoles(roles.map(r => r.id === roleModal.editId ? { ...r, ...roleForm } : r));
      showTip(t.tips.roleUpdated, 'success');
    } else {
      setRoles([...roles, { id: Math.random().toString(36).substr(2, 9), ...roleForm }]);
      showTip(t.tips.roleAdded, 'success');
    }
    setRoleModal({ open: false });
  };

  const handleDeleteRole = (id: string) => {
    setRoles(roles.filter(r => r.id !== id));
    showTip(t.tips.roleDeleted, 'info');
  };

  const togglePermission = (id: string) => {
    setRoleForm(prev => ({
      ...prev,
      permissions: prev.permissions.includes(id) 
        ? prev.permissions.filter(p => p !== id) 
        : [...prev.permissions, id]
    }));
  };

  const toggleAllPermissions = () => {
    if (roleForm.permissions.length === allPermIds.length) {
      setRoleForm(prev => ({ ...prev, permissions: [] }));
    } else {
      setRoleForm(prev => ({ ...prev, permissions: [...allPermIds] }));
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center">
            <ShieldCheck className="w-6 h-6 mr-3 text-amber-500" />
            {t.admin.title}
          </h1>
          <p className="text-gray-400">{t.admin.subtitle}</p>
        </div>
        <div className="flex space-x-3">
          <button 
            onClick={() => openRoleModal()}
            className="flex items-center space-x-2 bg-gray-800 hover:bg-gray-700 px-4 py-2 rounded-lg text-white font-semibold transition-all"
          >
            <Shield className="w-4 h-4 text-amber-500" />
            <span>{t.admin.addRoleBtn}</span>
          </button>
          <button 
            onClick={() => openAdminModal()}
            className="flex items-center space-x-2 bg-amber-500 hover:bg-amber-600 px-4 py-2 rounded-lg text-white font-semibold transition-all shadow-lg shadow-amber-900/20"
          >
            <UserPlus className="w-4 h-4" />
            <span>{t.admin.addBtn}</span>
          </button>
        </div>
      </div>

      <div className="bg-blue-900/10 border border-blue-900/30 p-4 rounded-xl flex items-start space-x-3">
        <ShieldAlert className="w-5 h-5 text-blue-500 flex-shrink-0 mt-0.5" />
        <div className="text-sm text-blue-400">
          <p className="font-semibold mb-1">{t.admin.policyNote}</p>
          <p>{t.admin.policyDesc}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.activeAdmins}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-800 text-gray-400 text-xs uppercase font-bold">
                <tr>
                  <th className="px-6 py-4">{t.admin.headers.nameId}</th>
                  <th className="px-6 py-4">{t.admin.headers.wallet}</th>
                  <th className="px-6 py-4">{t.admin.headers.role}</th>
                  <th className="px-6 py-4">{t.common.action}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800">
                {admins.map((admin) => {
                  const role = roles.find(r => r.id === admin.roleId);
                  return (
                    <tr key={admin.id} className="hover:bg-gray-800/20 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-medium text-white">{admin.name}</div>
                        <div className="text-xs text-gray-500">UID: {admin.id}</div>
                      </td>
                      <td className="px-6 py-4 font-mono text-xs text-amber-500">{admin.wallet}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded text-[10px] font-bold ${role?.isSuper ? 'bg-purple-500/20 text-purple-500' : 'bg-blue-500/20 text-blue-500'}`}>
                          {role?.name || t.common.none}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {!role?.isSuper && (
                          <div className="flex space-x-3">
                            <button onClick={() => openAdminModal(admin.id)} className="text-gray-400 hover:text-amber-500 transition-colors"><Edit2 className="w-4 h-4" /></button>
                            <button onClick={() => handleDeleteAdmin(admin.id)} className="text-gray-400 hover:text-red-500 transition-colors"><Trash2 className="w-4 h-4" /></button>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-lg font-bold text-gray-300">{t.admin.roleDefs}</h2>
          <div className="bg-gray-900/40 border border-gray-800 rounded-2xl p-6 space-y-4">
            {roles.map(role => (
              <div key={role.id} className="p-4 bg-gray-800/40 rounded-xl border border-gray-800 hover:border-amber-500/50 transition-all relative group">
                <div className="flex items-center justify-between mb-2">
                  <span className={`${role.isSuper ? 'text-amber-500' : 'text-blue-500'} font-bold text-sm uppercase`}>{role.name}</span>
