}

const ON_CHAIN_DEFAULTS: OnChainParams = {
  vaultDepositArb: true,
  vaultWithdrawArb: true,
  liqPenaltyRatio: '10',
  insFundSplit: '50',
  keeperSplit: '50',
  withdrawFee: '0.5',
  singleWithdrawLimit: '100000',
  dailyWithdrawLimit: '500000',
  approvalThreshold: '500000',
  delayThreshold: '1000000',
};

