                              className={`px-3 py-1.5 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all flex items-center
                                ${(sigs[rec.id] || 0) >= 2 
                                  ? 'bg-green-500/10 border-green-500/30 text-green-500 cursor-default' 
